import{C as e,H as t,R as n,S as r,Z as i,v as a,w as o,x as s}from"./vue-BDYVXuuN.js";import{c}from"./app-m3La2wLh.js";var l=JSON.parse(`{"path":"/courses/zsb-english/l/23/","title":"第 23 课 · 语法填空 Grammar Filling | 备考·英语","lang":"zh-CN","frontmatter":{"title":"第 23 课 · 语法填空 Grammar Filling","createTime":"2026-09-09T22:39:43.000Z","permalink":"/courses/zsb-english/l/23/","banner":"/images/covers/zsb-english.png","description":"这是本课阅读版。即可在同一页阅读、作答与复习，学习记录保存在此设备。 / 02 · 题型技巧 / 第六课 题型技巧 · 第六课 10 空 × 1.5 分 = 15 分——有提示，看词性；无提示，看成分；答案放回全文复读。 考点地图 · 点击跳转 题型：10 空 × 1.5 分 = 15 分（教材上册 P240-254）；以语篇为载体，设空分无提示词型与...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"第 23 课 · 语法填空 Grammar Filling\\",\\"image\\":[\\"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png\\"],\\"dateModified\\":\\"2026-10-07T13:23:39.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://liuj66794-sys.github.io/blog/courses/zsb-english/l/23/"}],["meta",{"property":"og:site_name","content":"知序"}],["meta",{"property":"og:title","content":"第 23 课 · 语法填空 Grammar Filling"}],["meta",{"property":"og:description","content":"这是本课阅读版。即可在同一页阅读、作答与复习，学习记录保存在此设备。 / 02 · 题型技巧 / 第六课 题型技巧 · 第六课 10 空 × 1.5 分 = 15 分——有提示，看词性；无提示，看成分；答案放回全文复读。 考点地图 · 点击跳转 题型：10 空 × 1.5 分 = 15 分（教材上册 P240-254）；以语篇为载体，设空分无提示词型与..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-10-07T13:23:39.000Z"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:image:src","content":"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png"}],["meta",{"name":"twitter:image:alt","content":"第 23 课 · 语法填空 Grammar Filling"}],["meta",{"property":"article:modified_time","content":"2026-10-07T13:23:39.000Z"}],["link",{"rel":"canonical","href":"https://liuj66794-sys.github.io/blog/courses/zsb-english/l/23/"}]]},"readingTime":{"minutes":213.06,"words":63919},"git":{"createdTime":1791379419000,"updatedTime":1791379419000,"contributors":[{"name":"38623","username":"","email":"386239680@qq.com","commits":1,"avatar":"https://gravatar.com/avatar/6a2940d3ff3182b82cb8a2c8dfebb295d647509713aef8bc86fb9e95a6767f99?d=retro"}]},"autoDesc":true,"filePathRelative":"courses/zsb-english/l/23.md","headers":[]}`),u={name:`23.md`};function d(c,l,u,d,f,p){let m=t(`VPLink`);return n(),s(`div`,null,[a(`blockquote`,null,[a(`p`,null,[l[1]||=e(`这是本课阅读版。`,-1),o(m,{href:`/blog/lessons/zsb-english/lessons/0023-grammar-fill.html`},{default:i(()=>[...l[0]||=[a(`strong`,null,`打开互动课程`,-1)]]),_:1}),l[2]||=e(`即可在同一页阅读、作答与复习，学习记录保存在此设备。`,-1)])]),a(`p`,null,[o(m,{href:`/blog/lessons/zsb-english/lessons/course.html`},{default:i(()=>[...l[3]||=[e(`课程总览`,-1)]]),_:1}),l[4]||=e(` / 02 · 题型技巧 / 第六课`,-1)]),l[22]||=r(`<p>题型技巧 · 第六课</p><p>10 空 × 1.5 分 = 15 分——有提示，看词性；无提示，看成分；答案放回全文复读。</p><div class="hint-container info"><p class="hint-container-title">考点地图 · 点击跳转</p><ol><li><a href="#pt-1"><strong>题型</strong>：10 空 × 1.5 分 = 15 分（教材上册 P240-254）；以语篇为载体，设空分<strong>无提示词型</strong>与<strong>给提示词型</strong></a></li><li><a href="#pt-2"><strong>无提示词五技巧</strong>：缺主宾填代词 → 名词前限定词 → 介词 → 特殊句式 → 句间连词</a></li><li><a href="#pt-3"><strong>有提示词四技巧</strong>：名词（单复数 / 所有格 / 转形容词）、形容词（转副词 / 否定词缀 / 比较级最高级）、动词（谓语 vs 非谓语）、词性转换总表</a></li><li><a href="#pt-4"><strong>实战</strong>：2025 / 2024 真题 + 题海 15 篇（原题转四选一课堂练习）</a></li></ol></div><h2 id="考情分析-教材-p240-技巧课-p3-4" tabindex="-1"><a class="header-anchor" href="#考情分析-教材-p240-技巧课-p3-4"><span>考情分析（教材 P240；技巧课 p3-4）</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 考情分析（教材 P240；技巧课 p3-4）</p><ul><li><strong>目标</strong>：说清语法填空的命题形式（语篇 10 空 × 1.5 分 = 15 分、每空一词），分清无提示词与给提示词两类设空，并建立「读全文 → 判类型 → 回填复读」的总流程。</li><li><strong>建议用时</strong>：10 分钟</li><li><strong>知识点</strong>：<code>语法填空题型与解题总流程</code></li></ul></div><h3 id="考情分析-教材-p240-技巧课-p3-4-·-小步学" tabindex="-1"><a class="header-anchor" href="#考情分析-教材-p240-技巧课-p3-4-·-小步学"><span>考情分析（教材 P240；技巧课 p3-4） · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>语法填空：先判断空缺的任务</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>10 空 15 分：先分「有没有提示词」，再决定思考方向</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>三步总流程：读全文知大意 → 看空判类型 → 回填复读</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：合上课件说出：语法填空的分值形式、两类设空各自考什么，以及三步总流程的每步做什么。</p><div class="hint-container tip"><p class="hint-container-title">10 空 15 分：先分「有没有提示词」，再决定思考方向</p><p><strong>句意</strong>：语法填空以一篇约 200 词的语篇挖 10 处空白，每空 1.5 分共 15 分，答案每空限填一词。设空分两类：给提示词（名词、动词、形容词/副词、代词要求变形）与无提示词（填冠词、介词、代词、连词）。</p><p><strong>拆解</strong></p><ul><li>分值：10 空 × 1.5 分 = 15 分，与一篇阅读的体量相当，但考点更偏语法</li><li>有提示词空：括号里给出词根，任务是变形——变词性、变复数、变时态语态或变非谓语</li><li>无提示词空：括号里没有词，任务是补缺——缺什么成分就补什么词类的「小词」（冠词、介词、代词、连词）</li><li>核心考点：非谓语、构词法、时态、语态、主谓一致和三大从句</li><li>两类空交替出现，第一判断永远是「看空处有没有括号提示词」</li></ul><p><strong>语法</strong>：命题特点：文章一般设 10 处空白，分为无提示词与给提示词两类。有提示词重点考名词、动词、代词、形容词/副词、数词与词性转换；无提示词重点考冠词、并列连词或从属连词、介词、代词。</p><p>正例：有提示词：Tim ____（hurry）to the scene. → 考虑时态 → hurried；无提示词：responded to ____ call about an accident. → 考虑限定词 → a 反例：见到提示词就只管加 -ed 或 -s ×（先判成分再定形式）；无提示词空想不出就跳过 ×（无提示词空往往是最有规律的五类小词） 适用边界：「有提示词考变形、无提示词考补缺」是分工而不是绝对：有提示词也可能要把名词转成形容词（felt silent），无提示词也可能填代词（缺主宾）。先看括号，再看成分，两步缺一不可。</p><p><strong>口诀</strong>：有提示，看词性；无提示，看成分 —— 八个字定方向：括号里给了词，就想这个词该变成什么形式；没给词，就想这个空在句子里缺什么成分。</p></div><div class="hint-container tip"><p class="hint-container-title">三步总流程：读全文知大意 → 看空判类型 → 回填复读</p><p><strong>句意</strong>：拿到一篇语法填空，先通读全文了解大意和时态基调，再逐空判断类型并作答，最后把 10 个答案全部放回原句复读一遍，检查语法、逻辑、大小写和拼写。</p><p><strong>拆解</strong></p><ul><li>第一步读全文：划出全文的基本时态（多为过去时或现在时）和话题，后面每个动词空都要与它一致</li><li>第二步逐空判断：先分有无提示词 → 有提示词判词性变形 / 无提示词判缺什么成分 → 在草稿上写出答案</li><li>第三步回填复读：把答案放回整句乃至全段，读一遍看是否通顺、语法是否成立、首字母该大写的是否大写</li><li>三遍之外还要检查拼写陷阱：双写辅音（hotter）、不规则复数（children）、-ly 构词（truly）都是扣分点</li></ul><p><strong>语法</strong>：答案必须放回全文复读，检查语法、逻辑、大小写和拼写。全文时态一致是动词空的第一依据；语篇衔接（代词指代、连词逻辑）是无提示词空的第一依据。</p><p>正例：通读 2025 真题：全文叙述上周救人事件 → 基调一般过去时 → Tim hurried / was wearing / shared 全部落在过去时框架内；回填检查：Fortunately, the boy and his mother were unharmed. 副词放句首修饰全句，首字母大写，复读成立 反例：不读全文直接做空：孤立地看 Each child ____（offer）an apple 可能填 offers，放回原文 yesterday 的语境才发现该是 was offered ×；写完不复读：把 as a result 写成 As result 或少写大写 × 适用边界：三步流程适合全部 10 空，但每空内部仍要「一空一词先定岗」：主宾名代、修饰副、系后形、句间连。流程是顺序，定岗是每空的内核。</p><p><strong>口诀</strong>：读全文，判类型，回填复读 —— 先做功课（读全文），再做题（判类型），最后做检查（复读）。跳过任何一步，错题率都会明显上升。</p></div><p>命题特点：文章一般设 <strong>10 处空白</strong>，分为<strong>无提示词</strong>与<strong>给提示词</strong>两类。核心考点包括<strong>非谓语、构词法、时态、语态、主谓一致和三大从句</strong>。</p><table><thead><tr><th>设空类型</th><th>重点考查</th></tr></thead><tbody><tr><td><strong>有提示词</strong></td><td>名词、动词、代词、形容词/副词、数词、词性转换</td></tr><tr><td><strong>无提示词</strong></td><td>冠词、并列连词或从属连词、介词、代词</td></tr></tbody></table><h2 id="解题技巧-·-无提示词-技巧课-p5-14" tabindex="-1"><a class="header-anchor" href="#解题技巧-·-无提示词-技巧课-p5-14"><span>解题技巧 · 无提示词（技巧课 p5-14）</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 解题技巧 · 无提示词（技巧课 p5-14）</p><ul><li><strong>目标</strong>：解决「括号里没有词时空什么」：按五条技巧依次排查——缺主宾填代词、名词前缺限定词、成分完整填介词、特殊句式、句间连词。</li><li><strong>建议用时</strong>：15 分钟</li><li><strong>知识点</strong>：<code>无提示词①：缺主语或宾语填代词</code> <code>无提示词②：名词前缺限定词</code> <code>无提示词③：句子成分完整时填介词</code> <code>无提示词④：用特殊句式判断</code> <code>无提示词⑤：缺连接时填连词或从句引导词</code></li></ul></div><h3 id="解题技巧-·-无提示词-技巧课-p5-14-·-小步学" tabindex="-1"><a class="header-anchor" href="#解题技巧-·-无提示词-技巧课-p5-14-·-小步学"><span>解题技巧 · 无提示词（技巧课 p5-14） · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>语法填空：先判断空缺的任务</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>技巧 1–2：缺主宾填代词，名词前缺限定词</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>技巧 3：句子成分完整，而名词或代词前有空，考虑介词</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>技巧 4–5：特殊句式定 it/that，句间缺连接填连词</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：按顺序背出无提示词五技巧：缺主宾→代词；名词前→限定词；成分完整→介词；特殊句式；句间连词，并各举一个课件例句。</p><div class="hint-container tip"><p class="hint-container-title">技巧 1–2：缺主宾填代词，名词前缺限定词</p><p><strong>句意</strong>：I can send a message to Kenya whenever I want to, and ____ gets there almost in a second. 意思是「我可以随时给肯尼亚发信息，而且信息几乎一秒就能到达那里」；It is said that a short-tempered man in the Song Dynasty was very anxious to help ____ rice crop grow up quickly. 意思是「据说宋朝有个急性子的人，非常着急地想让他的禾苗快快长高」。</p><p><strong>拆解</strong></p><ul><li>第一句：and 后的分句缺主语，所指是前文的 the message → 用代词 it 替代</li><li>第二句：rice crop 前没有任何限定成分，禾苗属于故事中的这个人 → 填形容词性物主代词 his</li><li>两题的共同动作：先检查空处缺什么成分，再回到上文找所指对象</li><li>限定词的范围不止物主代词：第一次提到的可数名词单数用 a/an，上文已提或被最高级限定的用 the</li></ul><p><strong>语法</strong>：句子缺主语或宾语时通常填代词或名词，代词必须与上文所指一致（同一事物用 it，指人用 he/she/they，与主语同指用反身代词）。名词前没有冠词、形容词性物主代词、形容词或不定代词等限定成分时，设空处很可能需要限定词：泛指单数用 a/an（看音素不看字母），特指用 the。</p><p>正例：...and it gets there almost in a second.（it 指代 the message）；...to help his rice crop grow up quickly.（his 限定 rice crop）；responded to a call about an accident.（第一次提到，泛指一通）；in the most beautiful city in the world.（最高级前用 the） 反例：...and he gets there... ×（所指是物 message，不是人）；help he rice crop ×（名词前要用形容词性物主代词 his，不能用人称代词主格）；responded to an call ×（call 以辅音音素开头，该用 a） 适用边界：a/an 看音素不看字母：an annual charity event（annual 以元音音素开头）、an important part；a successful translator（successful 以辅音音素开头）。the 用于特指、最高级、序数词和上文已提的事物。</p><p><strong>口诀</strong>：缺主宾，想代词；名词前，想限定；a/an 听音素，the 看特指 —— 两问连用：第一问「这个空是不是缺主语或宾语」，第二问「空后是不是紧跟着一个光溜溜的名词」。问完再回到上文确认所指。</p></div><div class="hint-container tip"><p class="hint-container-title">技巧 3：句子成分完整，而名词或代词前有空，考虑介词</p><p><strong>句意</strong>：...who should have the honour of receiving me ____ a guest in their house. 意思是「……谁有幸把我当作客人接待到家中」；In my opinion, our future depends ____ saving the rainforests. 意思是「在我看来，我们的未来取决于拯救雨林」。</p><p><strong>拆解</strong></p><ul><li>第一句：a guest 不作主语、表语或动词宾语，整个句子成分已经完整 → 空处填介词，as 表示「当作」</li><li>第二句：depends 是不及物动词，后面需要介词才能接 saving → depend on</li><li>判断路径：先确认主谓宾（或主系表）齐全，再看空后的名词/代词和前面动词或形容词是什么搭配</li><li>介词后接名词、代词或动名词——填了介词后形态还要跟上</li></ul><p><strong>语法</strong>：句子不缺主语、宾语或表语时，名词/代词前的空通常填介词。靠搭配与语义判断：同一动词配不同介词意义不同（respond to / talk to sb. about sth. / succeed in doing / depend on / worry about / lead to / be familiar with）；固定短语整体记忆（as a result、for example、in a hurry、for lunch、the risk of、in a newspaper）。</p><p>正例：receiving me as a guest（as = 当作）；our future depends on saving the rainforests（depend on + doing）；This can lead to heart disease.（lead to）；Are you familiar with them?（be familiar with） 反例：depend in saving ×（搭配错）；lead for heart disease ×（lead to 是固定搭配）；familiar to them ×（熟悉某物用 with；familiar to 是「为某人所熟知」，主语通常是事物） 适用边界：介词空最依赖平时积累：考试时能做的是把动词、形容词前后的搭配逐个读一遍，读不通的那个往往就是缺介词的位置。注意 because of + 名词与 because + 从句的分工。</p><p><strong>口诀</strong>：成分全，缺介词；动词形容词，找搭配 —— 先确认句子骨架完整，再回头问「前面的动词或形容词通常跟什么介词」——搭配是介词空的唯一判据。</p></div><div class="hint-container tip"><p class="hint-container-title">技巧 4–5：特殊句式定 it/that，句间缺连接填连词</p><p><strong>句意</strong>：...and it was only after I heard she became sick that I learned she couldn&#39;t eat MSG! 意思是「直到听说她病了，我才知道她不能吃味精」；My friend showed me around the town, which was very kind of him. 意思是「我的朋友带我参观了这座城镇，他这样做真是太好了」。</p><p><strong>拆解</strong></p><ul><li>强调句：It is/was...that... 的框架里，that 不能换成 which 或其他词</li><li>it 作形式主语/宾语：It takes sb. some time to do sth. / make it possible for sb. to do sth.，it 不能换成 this/that</li><li>so/such...that 的结果从句：that 引出结果</li><li>两个句子之间既无连词又无分号、句号 → 必须填并列连词或从属连词；逗号后的非限制性定语从句用 which（指代整件事也行），不能用 that</li></ul><p><strong>语法</strong>：特殊句式：强调句 It is/was...that...；it 作形式主语（It takes sb. some time to do / It is difficult for sb. to do）或形式宾语（make it possible for sb. to do）；so/such...that...。连词判断：并列成分间填 and/or/but；名词性从句引导词分「不作成分 that/whether」与「作成分 what/which/who」；定语从句关系词看先行词与从句成分；状语从句按逻辑关系选 when/because/if/unless 等。</p><p>正例：It was only after I heard she became sick that I learned...（强调句）；The event made it possible for the neighbors to have a chance to be together.（it 作形式宾语）；My friend showed me around the town, which was very kind of him.（which 指代整件事）；Please send us postcards and we&#39;ll know where you have visited.（并列句） 反例：It was...which I learned... ×（强调句框架里只能用 that）；made this possible for... ×（形式宾语只能用 it）；the town, that was very kind ×（逗号后非限制性定语从句不能用 that） 适用边界：which 指代前面整件事是非限制性从句的合法用法；that 不能用于逗号后的非限制性定语从句。判断从句类型先划从句界限：去掉引导词后从句缺不缺成分、是什么词性。</p><p><strong>口诀</strong>：特殊句式 it/that 不能换；句间无连必有连；逗号之后 which 不用 that —— 三类特殊句式认框架；句间连词先划从句再判类型——名词性、定语、状语各有一套引导词名单。</p></div><h3 id="技巧-1-·-句子缺主语或宾语-通常填代词或名词" tabindex="-1"><a class="header-anchor" href="#技巧-1-·-句子缺主语或宾语-通常填代词或名词"><span>技巧 1 · 句子缺主语或宾语，通常填代词或名词</span></a></h3><p>I can send a message to Kenya whenever I want to, and <strong>____</strong> gets there almost in a second. 我可以随时给肯尼亚发信息，而且信息几乎一秒就能到达那里。</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>答案解析<strong>it</strong> —— and 连接两个分句，后一分句<strong>缺主语</strong>；所指对象是前文的 the message，用代词 it 替代。</p></div><h3 id="技巧-2-·-名词前缺限定词-优先考虑限定词" tabindex="-1"><a class="header-anchor" href="#技巧-2-·-名词前缺限定词-优先考虑限定词"><span>技巧 2 · 名词前缺限定词，优先考虑限定词</span></a></h3><p>若名词前没有<strong>冠词、形容词性物主代词、形容词或不定代词</strong>等限定成分，设空处很可能需要限定词。</p><p>It is said that a short-tempered man in the Song Dynasty was very anxious to help <strong>____</strong> rice crop grow up quickly. 据说宋朝有个急性子的人，非常着急地想让他的禾苗快快长高。</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>答案解析<strong>his</strong> —— rice crop 前缺限定词；故事中的禾苗属于这个人，应填形容词性物主代词 his。</p></div><h3 id="技巧-3-·-句子成分完整-而名词或代词前有空-考虑介词" tabindex="-1"><a class="header-anchor" href="#技巧-3-·-句子成分完整-而名词或代词前有空-考虑介词"><span>技巧 3 · 句子成分完整，而名词或代词前有空，考虑介词</span></a></h3><ul><li>当句子不缺主语、宾语或表语时，名词/代词前的空通常填<strong>介词</strong>。</li><li>介词后接<strong>名词、代词或动名词</strong>。</li></ul><p>...who should have the honour of receiving me <strong>____</strong> a guest in their house. ……谁有幸把我当作客人接待到家中。</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>答案解析<strong>as</strong> —— a guest 不作主语、表语或动词宾语，需要介词引出；as 表示“当作”。</p></div><h3 id="技巧-4-·-用特殊句式判断" tabindex="-1"><a class="header-anchor" href="#技巧-4-·-用特殊句式判断"><span>技巧 4 · 用特殊句式判断</span></a></h3><table><thead><tr><th>特殊句式</th><th>课件例句</th><th>答案与依据</th></tr></thead><tbody><tr><td><strong>强调句</strong> It is/was...that...</td><td>...and ____ was only after I heard she became sick that I learned she couldn&#39;t eat MSG（味精）!</td><td><strong>it</strong> —— 句子是 It was...that... 强调结构。</td></tr><tr><td><strong>it 作形式主语或形式宾语</strong></td><td>...as ____ took them just three minutes to steal paintings by two world-famous artists...</td><td><strong>it</strong> —— 句型为 It takes sb. some time to do sth.，不定式 to steal paintings 是真正主语。</td></tr><tr><td><strong>so/such...that...</strong></td><td>This made the goat so jealous ____ it began plotting against（谋划对付）the donkey.</td><td><strong>that</strong> —— 固定结构为 so...that...。</td></tr></tbody></table><h3 id="技巧-5-·-两个成分或两个句子之间缺连接-考虑连词" tabindex="-1"><a class="header-anchor" href="#技巧-5-·-两个成分或两个句子之间缺连接-考虑连词"><span>技巧 5 · 两个成分或两个句子之间缺连接，考虑连词</span></a></h3><ul><li>两个或多个单词/短语之间没有连词，可能填 <strong>and, or</strong> 等并列连词；填并列连词时判断<strong>顺承、转折</strong>等逻辑。</li><li>两个句子之间<strong>既无连词，又无分号或句号</strong>，一定要填并列连词或从属连词；填从属连词时先划出从句，再判断从句类型。</li></ul><table><thead><tr><th>从句类型</th><th>引导词判断</th></tr></thead><tbody><tr><td><strong>名词性从句</strong>（主、宾、表、同位语）</td><td>不作从句成分：that, whether、“四何”；作从句成分：who, whom, what, which, whose</td></tr><tr><td><strong>定语从句</strong></td><td>关系代词：that, which, who, whom, whose, as；关系副词：when, where, why</td></tr><tr><td><strong>状语从句</strong></td><td>先判断具体状语关系，再选相应引导词</td></tr></tbody></table><p>...two world-famous artists, Pablo Picasso <strong>____</strong> Candido Portinari, which are worth millions of dollars. ……两位世界著名艺术家巴勃罗·毕加索和坎迪多·波尔蒂纳里的画作，价值数百万美元。　<strong>答案：and</strong> —— 两个人名并列，需要并列连词。</p><p>Please send us postcards <strong>and</strong> we&#39;ll know where you have visited. 请给我们寄明信片，这样我们就会知道你去过哪里。</p><p>We were having a heated discussion <strong>when</strong> there was a power failure. 我们正在激烈讨论，这时突然停电了。（课件原文 a failure power 按语义修正为 a power failure。）</p><h2 id="解题技巧-·-有提示词-技巧课-p15-25" tabindex="-1"><a class="header-anchor" href="#解题技巧-·-有提示词-技巧课-p15-25"><span>解题技巧 · 有提示词（技巧课 p15-25）</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 解题技巧 · 有提示词（技巧课 p15-25）</p><ul><li><strong>目标</strong>：解决「括号里有词时怎么变」：名词先判数再判格、形容词转副词/加否定词缀/变比较级、动词先判谓语还是非谓语，并按词性转换总表定位。</li><li><strong>建议用时</strong>：15 分钟</li><li><strong>知识点</strong>：<code>有提示词·名词：单复数与所有格</code> <code>有提示词·词性转换总表</code> <code>有提示词·形容词转副词构词规则</code> <code>有提示词·否定词缀与反义构词</code> <code>有提示词·比较级与最高级</code> <code>有提示词·代词形式选择</code> <code>有提示词·动词①：谓语动词（时态语态一致）</code> <code>有提示词·动词②：非谓语动词</code></li></ul></div><h3 id="解题技巧-·-有提示词-技巧课-p15-25-·-小步学" tabindex="-1"><a class="header-anchor" href="#解题技巧-·-有提示词-技巧课-p15-25-·-小步学"><span>解题技巧 · 有提示词（技巧课 p15-25） · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>语法填空：先判断空缺的任务</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>技巧 6、9：名词先判数再判格，词性转换先看成分</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>技巧 7：形容词转副词的构词规则、否定词缀与比较级</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>技巧 8：动词先判谓语还是非谓语，再定时态语态或形态</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：说出有提示词四大类（名词、形容词、动词、词性转换）各自的判断顺序，并把「动词三问」完整背一遍。</p><div class="hint-container tip"><p class="hint-container-title">技巧 6、9：名词先判数再判格，词性转换先看成分</p><p><strong>句意</strong>：Air pollution is caused by the following three ____（reason）: ... 意思是「空气污染由以下三个原因造成」；He immediately felt ____（silence）as tears flew down from his big blue eyes. 意思是「泪水从他蓝色的大眼睛里涌出时，他立刻沉默下来」。</p><p><strong>拆解</strong></p><ul><li>第一句：three 后接可数名词复数 → reasons；若表所属关系，单数和不以 -s 结尾的复数加 &#39;s（children&#39;s），以 -s 结尾的复数只加 &#39;</li><li>第二句：felt 是系动词，后面接形容词作表语 → silence 转成 silent</li><li>词性转换总表：作表语/定语/补语用形容词；作主语、宾语用名词；物主代词后、冠词后用名词；作状语修饰动词、形容词或全句用副词</li><li>关键动作不是「怎么变」而是「变成什么」——先定成分，再定词性，最后才是具体形式</li></ul><p><strong>语法</strong>：名词提示词：前有数词或 these/those/several/many/all/both/various/numerous、one of 结构、谓语为复数时用复数；所有格单数与不规则复数加 &#39;s，s 结尾复数加 &#39;。名词还可转形容词（a silent boy）。词性转换总表：表语、定语、补语 → 形容词；主语、及物动词/介词后宾语 → 名词；物主代词后、冠词（+形容词）后 → 名词；状语 → 副词；反义 → 加否定词缀。</p><p>正例：three reasons（数词 + 复数）；the children&#39;s houses（不规则复数 children 加 &#39;s）；He felt silent.（系动词 + 形容词）；his death / their kindness（物主代词后接名词） 反例：three reason ×（漏复数）；childrens&#39; ×（children 不以 s 结尾，加 &#39;s 不是 s&#39;）；He felt silence. ×（felt 后接形容词，不接名词） 适用边界：「名词前有限定词修饰」不等于用形容词：冠词和物主代词后面要的是名词（his death、the importance）。判断顺序：先看空后是不是名词（是 → 空处可能是形容词或限定词），再看空前是不是限定词（是 → 空处必须是名词或形容词）。</p><p><strong>口诀</strong>：先定成分，再定词性，最后定形式 —— 成分 → 词性 → 形式三步走，顺序不能反：先想「这个空在句子里当什么」，再想「当什么成分该用什么词性」，最后才写具体单词。</p></div><div class="hint-container tip"><p class="hint-container-title">技巧 7：形容词转副词的构词规则、否定词缀与比较级</p><p><strong>句意</strong>：Jack ____（deep）loves Rose. 意思是「杰克深爱着露丝」，答案是 deeply；Not taking a proper lunch break is ____（healthy）. 意思是「不好好午休是不健康的」，答案是 unhealthy；Your sweater is much ____（expensive）than mine. 意思是「你的毛衣比我的贵得多」，答案是 more expensive。</p><p><strong>拆解</strong></p><ul><li>deep → deeply：副词修饰动词 loves；多数形容词直接加 -ly</li><li>healthy → unhealthy：下文「使人生病」说明要否定意义，加前缀 un-</li><li>expensive → more expensive：much 和 than 双提示比较级，多音节词前加 more</li><li>构词细则：辅音 + y 变 i 加 -ly（happily）；辅音 + le 去 e 加 y（terribly）；ue 结尾去 e 加 -ly（truly）；ll 结尾加 y（fully）；ic 结尾加 -ally（basically）</li></ul><p><strong>语法</strong>：副词修饰形容词、动词或全句，位置有「副词 + 形容词」「主语 + 副词 + 谓语」「助动词 + 副词 + 实义动词」三种。否定词缀：un-、im-、in-、dis-、ir- 或后加 -less（successful → unsuccessful、possible → impossible、honest → dishonest、help → helpless、active → inactive）。比较级：than、much/far/still/even/rather/a little/a lot 提示比较级；in/of/among 范围、one of the、the + 序数词提示最高级；固定句型 the + 比较级..., the + 比较级...；「否定词 + 比较级」表最高级；无 than 也要看隐含比较。</p><p>正例：Jack deeply loves Rose.（副词修饰动词）；girls were extremely sensitive（副词修饰形容词）；is unhealthy / an inactive person（否定词缀）；no sweeter sight in the world（否定词 + 比较级 = 最高级） 反例：Jack deep loves Rose. ×（形容词不能修饰动词）；is healthily ×（系动词后接形容词）；more hotter ×（比较级不能叠加） 适用边界：比较级不只看 than：much/even/still 等程度词、固定句型和隐含比较（my new way of thinking brought me closer to my mother than before）都能提示；最高级不一定带 the（most beautiful 前有 the 是因为形容词最高级作定语，副词最高级可省略 the）。</p><p><strong>口诀</strong>：修饰动形用副词，un/im/dis 表否定，than 和 much 想比较级 —— 形容词提示词三问：修饰谁（动词/形容词/全句 → 副词）？意思要不要反（→ 否定词缀）？有没有比较（→ 比较级/最高级）？</p></div><div class="hint-container tip"><p class="hint-container-title">技巧 8：动词先判谓语还是非谓语，再定时态语态或形态</p><p><strong>句意</strong>：Each child ____（offer）an apple at the party yesterday. 意思是「昨天聚会上每个孩子都被分到了一个苹果」，答案是 was offered；He was determined ____（use）this challenge to raise funds. 意思是「他决心用这次挑战来筹集资金」，答案是 to use。</p><p><strong>拆解</strong></p><ul><li>第一问永远是「这个动词是不是谓语」：句中没有其他谓语，或空与已有谓语由 and/but/or 连接并列 → 是谓语题</li><li>谓语题三定：定时态（yesterday → 一般过去时）、定语态（child 被 offer → 被动）、定一致（each child → 单数）→ was offered</li><li>已有谓语且无并列连词 → 非谓语题：作目的状语、形容词后状语用 to do；作主宾用 doing/to do；作定语看主被动；介词后用 doing；固定搭配按搭配（be determined to do）</li><li>情态动词与助动词后一律接动词原形</li></ul><p><strong>语法</strong>：谓语动词：先定时态（时间状语、全文基调、主从句呼应），再定语态（主语是承受者用 be + done），最后核对主谓一致（主语单复数、不可数、everybody 等不定代词）。非谓语：作主语或宾语常用 -ing 表一般、不定式表具体将来；作目的状语或形容词后用不定式；作定语 doing 主动进行、being done 被动进行、done 被动完成、to do 目的将来。</p><p>正例：was offered（过去 + 被动 + 单数）；are cleaning（Look! 提示现在进行）；have lived（for 5 years 提示现在完成）；to use（be determined to do）；named after his birth city（done 作状语表被动） 反例：Each child offered an apple ×（孩子是被给苹果的一方，语态反了）；was determining to use ×（be determined 是形容词化结构，接 to do）；spent his whole life to write ×（spend time doing） 适用边界：找谓语要看全句：插入语（with her parents）和后置定语不算谓语；并列连词连接两个动词时两个都是谓语。固定搭配优先于形态推断：be determined to do、encourage sb. to do、let sb. do、begin doing、spend time doing 直接定形。</p><p><strong>口诀</strong>：动词三问：是不是谓语？什么时态语态？主谓是否一致？ —— 已有谓语无连词，第二动词变非谓。先把第一问问死，后面两问才有意义。</p></div><h3 id="技巧-6-·-提示词为名词" tabindex="-1"><a class="header-anchor" href="#技巧-6-·-提示词为名词"><span>技巧 6 · 提示词为名词</span></a></h3><p><strong>① 单复数</strong>：前有数词或 these, those, several, many, all, both, various, numerous 等词时用复数；前有 one of 时用复数；谓语动词为复数时主语空格也可能需要名词复数。</p><p>Air pollution is caused by the following three <strong>____</strong>（reason）: about half of the problem is caused by vehicles. 空气污染由以下三个原因造成：其中约一半的问题由车辆引起。</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>答案解析<strong>reasons</strong> —— three 后接可数名词复数。</p></div><p><strong>② 所有格</strong>：单数名词和不以 -s 结尾的复数名词，词尾通常加 &#39;s；以 -s/-es 结尾的复数名词，形式为 -s&#39;/-es&#39;。</p><p>There are many students living at school; the <strong>____</strong>（child）houses are all far from school. 许多学生住在学校，因为孩子们的家都离学校很远。</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>答案解析<strong>children&#39;s</strong> —— 不规则复数 children 不以 s 结尾，所有格加 &#39;s。</p></div><p><strong>③ 名词转形容词</strong>：常见位置有 a/an/the + 形容词 + 名词、副词后、系动词后、make/let/have + sb. + 形容词。</p><p>He immediately felt <strong>____</strong>（silence）as tears flew down from his big blue eyes. 泪水从他蓝色的大眼睛里涌出时，他立刻沉默下来。</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>答案解析<strong>silent</strong> —— felt 是系动词，后接形容词作表语。</p></div><h3 id="技巧-7-·-提示词为形容词" tabindex="-1"><a class="header-anchor" href="#技巧-7-·-提示词为形容词"><span>技巧 7 · 提示词为形容词</span></a></h3><p><strong>① 形容词转副词</strong>：副词可修饰形容词、动词或全句；常见位置包括“副词 + 形容词”“主语 + 副词 + 谓语”“助动词 + 副词 + 实义动词”。构词规则：</p><ol><li>多数形容词直接加 -ly。</li><li>辅音字母 + y：变 y 为 i 再加 -ly，如 happy → happily。</li><li>辅音字母 + le：去 e 加 y，如 terrible → terribly, possible → possibly。</li><li>以 ue 结尾：去 e 加 -ly，如 true → truly。</li><li>以 ll 结尾：直接加 y，如 full → fully。</li><li>以 c 结尾：词尾加 -ally，如 basic → basically。</li><li>个别例外：whole → wholly。</li></ol><p>Jack <strong>____</strong>（deep）loves Rose.　杰克深爱着露丝。　<strong>答案：deeply</strong> —— 副词修饰动词 loves。</p><p>She can <strong>____</strong>（quick）adapt to the new class.　她能很快适应新班级。　<strong>答案：quickly</strong> —— 副词修饰动词 adapt。</p><p><strong>② 添加否定词缀</strong>：根据句意和逻辑，在词根前加 un-, im-, dis- 等，或在词根后加 -less：successful → unsuccessful; possible → impossible; honest → dishonest; help → helpless。</p><p><strong>③ 比较级与最高级</strong>：</p><ul><li>much, far, still, even, rather, a little, a bit, a lot, a great deal, than 常提示<strong>比较级</strong>。</li><li>范围标志 in, of, among 常提示<strong>最高级</strong>；one of the、the + 序数词 常接最高级。</li><li>固定句型：the + 比较级..., the + 比较级...；比较级 + and + 比较级；“否定词 + 比较级”表达最高级含义。</li><li>即使没有 than，也要根据<strong>隐含比较</strong>判断。</li></ul><table><thead><tr><th>课件例句</th><th>答案与依据</th></tr></thead><tbody><tr><td>If you work harder, your English will be ____（good）.</td><td><strong>better</strong> —— 句意含前后比较。</td></tr><tr><td>The elephant is ____（big）than the horse.</td><td><strong>bigger</strong> —— than 提示比较级。</td></tr><tr><td>Your sweater is much ____（expensive）than mine.</td><td><strong>more expensive</strong> —— much...than 修饰比较级。</td></tr></tbody></table><h3 id="技巧-8-·-提示词为动词-先判断谓语还是非谓语" tabindex="-1"><a class="header-anchor" href="#技巧-8-·-提示词为动词-先判断谓语还是非谓语"><span>技巧 8 · 提示词为动词：先判断谓语还是非谓语</span></a></h3><p><strong>① 谓语动词</strong>：句中没有其他谓语，或设空动词与已有谓语构成并列时，考虑<strong>时态、语态和主谓一致</strong>。</p><table><thead><tr><th>课件例句</th><th>答案</th><th>判断依据</th></tr></thead><tbody><tr><td>Each child ____（offer）an apple at the party yesterday.</td><td><strong>was offered</strong></td><td>一般过去时的被动语态。</td></tr><tr><td>Look! The students ____（clean）the classroom.</td><td><strong>are cleaning</strong></td><td>Look! 提示现在进行时。</td></tr><tr><td>I ____（live）in this city for 5 years.</td><td><strong>have lived</strong></td><td>for 5 years 提示现在完成时。</td></tr><tr><td>By the time he arrived at the station, the train ____（leave）.</td><td><strong>had left</strong></td><td>火车离开发生在过去动作 arrived 之前。</td></tr><tr><td>The girl, with her parents, ____（wait）at the school gate now.</td><td><strong>is waiting</strong></td><td>with 不改变主语，谓语与 the girl 一致。</td></tr></tbody></table><p><strong>② 非谓语动词</strong>：句中已有谓语且设空处不与之并列时，用非谓语：</p><ul><li><strong>作主语或宾语</strong>：通常用 -ing 表示一般情况，用不定式表示具体或将来的情况。<strong>Going to bed on time</strong> is a good habit.（按时睡觉是一个好习惯。）</li><li><strong>作目的状语，或在形容词后作状语</strong>：通常用不定式。<strong>To complete the project as planned</strong>, we&#39;ll have to work two more hours a day.（为按计划完成项目，我们每天还得多工作两小时。）</li><li><strong>作定语</strong>：现在分词表示主动、正在进行；being done 表示被动且正在发生；过去分词表示被动、完成；不定式表示目的或将来。</li></ul><h3 id="技巧-9-·-词性转换总表" tabindex="-1"><a class="header-anchor" href="#技巧-9-·-词性转换总表"><span>技巧 9 · 词性转换总表</span></a></h3><table><thead><tr><th>句子位置 / 功能</th><th>用什么词性</th></tr></thead><tbody><tr><td>作表语、定语或补语</td><td>常用<strong>形容词</strong></td></tr><tr><td>作主语，或在及物动词/介词后作宾语</td><td>用<strong>名词</strong></td></tr><tr><td>形容词性物主代词后，或“冠词（+ 形容词）”后</td><td>用<strong>名词</strong></td></tr><tr><td>修饰动词、形容词、副词或全句，作状语</td><td>用<strong>副词</strong></td></tr><tr><td>根据句意和前后逻辑构成反义词</td><td>词根前加 un-, im- 等，或词根后加 -less 等</td></tr></tbody></table><h2 id="易错清单" tabindex="-1"><a class="header-anchor" href="#易错清单"><span>易错清单</span></a></h2><div class="hint-container caution"><p class="hint-container-title">易错</p><p>高频易错</p><ol><li><p>有提示词不能机械变形：先判断句子缺什么成分，再决定词性、时态、语态和数</p></li><li><p>动词题先找全句谓语：已有谓语且无并列连词时，优先考虑非谓语</p></li><li><p>无提示词先查句子是否缺主语/宾语，再查名词前限定词、介词搭配和句间连词</p></li><li><p><strong>which</strong> 可引导非限制性定语从句并指代前面整件事；<strong>that</strong> 不能用于逗号后的非限制性定语从句</p></li><li><p>系动词后用形容词；修饰动词、形容词或全句用副词</p></li><li><p>比较级不只看 than，也要看 much/even/still、固定句型和隐含比较</p></li><li><p>答案必须放回全文复读，检查语法、逻辑、大小写和拼写</p></li></ol></div><h2 id="课堂练习" tabindex="-1"><a class="header-anchor" href="#课堂练习"><span>课堂练习</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 课堂练习</p><ul><li><strong>目标</strong>：把技巧落到真题与 15 篇题海语篇上：先通读全文定时态基调，逐空按「有无提示词 → 成分/词性 → 形式」作答，最后把答案放回全文复读。</li><li><strong>建议用时</strong>：15 分钟</li><li><strong>知识点</strong>：<code>答案回填复读与易错清单</code></li></ul></div><h3 id="课堂练习-·-小步学" tabindex="-1"><a class="header-anchor" href="#课堂练习-·-小步学"><span>课堂练习 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>语法填空：先判断空缺的任务</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>实战节奏：一篇 10 空按「先无提示词小词、后提示词变形」两遍扫描</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：用 2025 真题任意 3 个空演示「有无提示词 → 成分/词性 → 形式 → 回填复读」的完整过程，再说出五条易错清单。</p><div class="hint-container tip"><p class="hint-container-title">实战节奏：一篇 10 空按「先无提示词小词、后提示词变形」两遍扫描</p><p><strong>句意</strong>：做完整的一篇语法填空，建议第一遍先解决无提示词空（冠词、介词、代词、连词——词类小、依据硬），第二遍再处理有提示词空（变形题需要更多上下文核对），最后整篇复读。</p><p><strong>拆解</strong></p><ul><li>第一遍扫描无提示词空：缺主宾 → 代词；名词前 → 限定词；成分完整 → 介词；看句式框架 → it/that；句间无连 → 连词</li><li>第二遍扫描有提示词空：名词 → 数与格；形容词 → 副词/否定/比较级；动词 → 谓语三问或非谓语形态</li><li>每填一空就在脑中把整句读一遍，语句不通立即回头检查</li><li>两遍都做完后把全文连同 10 个答案完整复读一遍，专门检查大小写、拼写、时态一致</li></ul><p><strong>语法</strong>：五条易错清单：有提示词不能机械变形；动词题先找全句谓语；无提示词按「主宾 → 限定词 → 介词 → 连词」顺序排查；which 可指代整件事、that 不能用于逗号后；系动词后用形容词、修饰动词/形容词/全句用副词。最后答案回填全文检查。</p><p>正例：2025 真题节奏：先填 a / about / who 三个无提示词空，再处理 hurried / Fortunately / wearing / powerful / shared / reactions / myself 七个变形空；复读发现：Fortunately 句首大写、reactions 复数与 are 一致、myself 与主语 I 呼应 反例：从头到尾顺着做空：做到第 7 空忘记第 2 空的全文时态线索 ×；填完不复读：hotter 写成 hoter、tomatoes 写成 tomatos 这类拼写扣分 × 适用边界：两遍扫描是效率策略，不是死规矩：如果某篇无提示词空恰好依赖后文线索（如 without makeup 要读到下文「不得不洗脸」），先做后面的空再回来补也完全正常。</p><p><strong>口诀</strong>：先小词，后变形；答完全篇复读一遍 —— 无提示词空依据硬、花时间少，先拿下；变形空需要全文时态和逻辑兜底，放第二遍；复读专抓大小写和拼写。</p></div><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>原题说明语法填空原题为「有提示词 / 无提示词」语篇填空，每空一词。此处转成四选一：<strong>正确项 = 笔记答案</strong>，干扰项 = 该空典型错误形式，解析沿用笔记判断依据并注明原题型。两份题海来源内容相同，仅分页不同，以下按 31 页完整版本合并；题海部分课件未提供文字答案，答案与解析为笔记整理时补充（why 中标注「笔记补充解析」）。</p></div><h3 id="连词随堂练习-技巧课-p14" tabindex="-1"><a class="header-anchor" href="#连词随堂练习-技巧课-p14"><span>连词随堂练习（技巧课 p14）</span></a></h3><p><strong>【连词随堂 · 原题为填空】This is the best film ____ I have ever seen. 这是我看过的最好的电影。</strong></p><ul><li>A. which</li><li>B. what</li><li>C. that</li><li>D. who</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（that）</strong> —— 课件原答案：先行词由最高级 the best 修饰，限制性定语从句用 that。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 先行词 film 被最高级 the best 修饰时，关系代词只能用 that，不能用 which。干扰点：一般情况下 which 和 that 可互换，忽略了最高级限定的特殊规则。</li><li>B ❌ what 不能引导定语从句，它引导名词性从句；本句需要关系代词在从句中作 seen 的宾语。</li><li>C ✅ 先行词由最高级 the best 修饰，限制性定语从句的关系代词只能用 that（课件原答案）。</li><li>D ❌ who 的先行词必须指人，film 是物；语法和语义都不成立。</li></ul><p><strong>整句翻译</strong>：这是我看过的最好的电影。</p><p><strong>词组</strong>：<code>the best film (that) I have ever seen</code> 我看过的最好的电影（that 可省略）；<code>先行词</code> 定语从句所修饰的那个名词或代词</p><p><strong>对比自测</strong>：做完后对照 quiz-c:1，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 · 连词随堂练习（技巧5 · 定语从句））：This is the best film ____ I have ever seen.（先行词由最高级修饰，限制性定语从句用 that）</p></details><p><strong>【连词随堂 · 原题为填空】My friend showed me around the town, ____ was very kind of him. 我的朋友带我参观了这座城镇，他这样做真是太好了。</strong></p><ul><li>A. that</li><li>B. which</li><li>C. what</li><li>D. it</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（which）</strong> —— 课件原答案：非限制性定语从句用 which 指代前面整件事；that 不能用于逗号后的非限制性定语从句。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 逗号后是非限制性定语从句，that 不能用于逗号后的非限制性定语从句。</li><li>B ✅ which 引导非限制性定语从句，指代前面整件事「朋友带我参观」；课件原答案。</li><li>C ❌ what 只能引导名词性从句，不能跟在逗号后作定语从句。</li><li>D ❌ 两个逗号之间需要连词，直接放代词 it 会让句子出现两套主谓而无连接。干扰点：把 it was very kind of him 当成独立句硬接。</li></ul><p><strong>整句翻译</strong>：我的朋友带我参观了这座城镇，他这样做真是太好了。</p><p><strong>词组</strong>：<code>show sb. around</code> 带某人参观；<code>非限制性定语从句</code> 用逗号与主句隔开、对先行词补充说明的定语从句</p><p><strong>对比自测</strong>：做完后对照 quiz-c:0，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 · 连词随堂练习（技巧5 · 非限制性定语从句））：My friend showed me around the town, ____ was very kind of him.（which 指代前面整件事）</p></details><p><strong>【连词随堂 · 原题为填空】____ he wants to go there is obvious. 很明显，他想去那里。</strong></p><ul><li>A. That</li><li>B. What</li><li>C. Which</li><li>D. As</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（That）</strong> —— 课件原答案：that 引导主语从句，在从句中不作成分。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ that 引导主语从句，在从句中不作任何成分只起连接作用；he wants to go there 本身成分完整（课件原答案）。</li><li>B ❌ what 要在从句中作成分（主语、宾语等），而从句 he wants to go there 不缺成分，放进 what 反而多出一个宾语位。</li><li>C ❌ which 表「哪一个」，需要选择范围，句中没有可挑选的对象；主语从句也不用 which 起连接作用。</li><li>D ❌ as 可引导定语从句和状语从句，但不引导这种成分完整的主语从句。</li></ul><p><strong>整句翻译</strong>：很明显，他想去那里。</p><p><strong>词组</strong>：<code>主语从句</code> 在句中充当主语的从句；<code>it is obvious that...</code> ……是明显的（it 作形式主语的常见变体）</p><p><strong>对比自测</strong>：做完后对照 quiz-c:3，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 · 连词随堂练习（技巧5 · 名词性从句））：____ he wants to go there is obvious.（that 引导主语从句，不作成分）</p></details><p><strong>【连词随堂 · 原题为填空】____ he knocked at the door, I was working at the table. 当他敲门时，我正在桌旁工作。</strong></p><ul><li>A. Because</li><li>B. Which</li><li>C. Unless</li><li>D. When</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（When）</strong> —— 课件原答案：表示「当……时」，when 引导时间状语从句。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ because 表原因，「因为他敲门，所以我在工作」逻辑不通；本句是时间关系。干扰点：只看出两个动作有先后就猜因果。</li><li>B ❌ which 引导定语从句，需要先行词；空格前是完整句子，没有可被修饰的名词。</li><li>C ❌ unless 表「除非」，引导条件状语从句，与「敲门时正在工作」的时间关系不符。</li><li>D ✅ 表示「当……时」，when 引导时间状语从句；课件原答案。</li></ul><p><strong>整句翻译</strong>：当他敲门时，我正在桌旁工作。</p><p><strong>词组</strong>：<code>knock at the door</code> 敲门；<code>时间状语从句</code> 说明主句动作发生时间的从句</p><p><strong>对比自测</strong>：做完后对照 quiz-c:2，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 · 连词随堂练习（技巧5 · 状语从句））：____ he knocked at the door, I was working at the table.（when 引导时间状语从句）</p></details><h3 id="真题一-·-2025-年-技巧课-p26-29" tabindex="-1"><a class="header-anchor" href="#真题一-·-2025-年-技巧课-p26-29"><span>真题一 · 2025 年（技巧课 p26-29）</span></a></h3><p>Last weekend, as snow fell heavily in North Andover, Firefighter Tim of the North Andover Fire Department responded to <strong>36 ______</strong> call about an accident. Tim <strong>37 ______</strong>（hurry）to the scene and discovered a mother and her son inside the vehicle. <strong>38 ______</strong>（fortunate）, the boy and his mother were unharmed. But as the tow truck arrived to take away their damaged car, the child stood in the cold, watching the scene unfold.</p><p>“He was actually <strong>39 ______</strong>（wear）a Marvel coat that night, so I talked to him <strong>40 ______</strong> some superheroes he liked,” Tim said.</p><p>The real superhero of the night was Tim, <strong>41 ______</strong> draped his turnout coat over the little boy as he watched his mother&#39;s car get towed away. This simple but <strong>42 ______</strong>（power）action that Tim did offered the little boy warmth and comfort in the storm. A photo capturing the moment, <strong>43 ______</strong>（share）by the fire department on Facebook, quickly gained attention, with commenters praising the firefighter&#39;s compassion.</p><p>“All the <strong>44 ______</strong>（reaction）online are incredible. All the positive comments people have left just makes me feel really proud of <strong>45 ______</strong>（I）and the job I get to do every day,” Tim said.</p><p><strong>【2025 真题 · 无提示词】...Firefighter Tim of the North Andover Fire Department responded to ____ call about an accident.</strong></p><ul><li>A. an</li><li>B. the</li><li>C. one</li><li>D. a</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（a）</strong> —— 原题为无提示词填空（课件原答案）：call 是可数名词单数，此处泛指「一通事故电话」，用不定冠词 a。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ an 用于元音音素开头的词前，call 以辅音音素 /k/ 开头，应用 a。干扰点：只看空后紧跟的 about 以元音开头，误判了冠词服务的词。</li><li>B ❌ the 表特指，但这通电话是首次提到、泛指「一通事故电话」，上下文没有把它限定为某一通。</li><li>C ❌ one 强调数量「一个」，且不能充当名词前的限定冠词角色；这里需要的是冠词而非数词。干扰点：把「一通」直译成 one。</li><li>D ✅ call 是可数名词单数，此处泛指「一通事故电话」，用不定冠词 a；课件原答案。</li></ul><p><strong>整句翻译</strong>：上周，北安多弗下起了大雪，消防队员蒂姆接到一通关于事故的电话后出警。</p><p><strong>词组</strong>：<code>respond to a call</code> 响应一通电话（call 可数，泛指一通用 a）；<code>about an accident</code> 关于一起事故（accident 以元音音素开头用 an）</p><p><strong>对比自测</strong>：做完后对照 quiz-t2:3，比较两题的判断依据</p><p><strong>原文定位</strong>（真题一 2025 · 第1段第1句（空36））：Firefighter Tim of the North Andover Fire Department responded to ____ call about an accident.</p></details><p><strong>【2025 真题 · 提示词 hurry】Tim ____ to the scene and discovered a mother and her son inside the vehicle.</strong></p><ul><li>A. hurried</li><li>B. hurries</li><li>C. hurrying</li><li>D. to hurry</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（hurried）</strong> —— 原题为有提示词填空：全文叙述过去事件，且后文用 discovered，用一般过去时。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 全文叙述上周救人事件（Last weekend），且后文用 discovered，and 连接两个并列谓语，时态要一致 → 一般过去时 hurried；课件原答案。</li><li>B ❌ hurries 是一般现在时第三人称单数，与全文过去时基调冲突。干扰点：只盯主语 Tim 想主谓一致，忽略了时态。</li><li>C ❌ hurrying 是非谓语：句中已有谓语 discovered，但空格与 discovered 由 and 连接，本空必须是谓语形式，hurrying 会造成句子没有与 and 匹配的谓语。</li><li>D ❌ to hurry 是不定式，同样不能作 and 连接的并列谓语；也不存在目的关系。</li></ul><p><strong>整句翻译</strong>：蒂姆匆忙赶到现场，发现车里有一位母亲和她的儿子。</p><p><strong>词组</strong>：<code>hurry to the scene</code> 匆忙赶到现场；<code>discover sb. inside the vehicle</code> 发现某人在车内</p><p><strong>对比自测</strong>：做完后对照 quiz-t2:2，比较两题的判断依据</p><p><strong>原文定位</strong>（真题一 2025 · 第1段第1句（空37））：Tim ____（hurry）to the scene and discovered a mother and her son inside the vehicle.（and 连接两个过去时谓语）</p></details><p><strong>【2025 真题 · 提示词 fortunate】____, the boy and his mother were unharmed.</strong></p><ul><li>A. Fortunate</li><li>B. Unfortunately</li><li>C. Fortune</li><li>D. Fortunately</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（Fortunately）</strong> —— 原题为有提示词填空：副词作评注性状语修饰全句，位于句首首字母大写。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ Fortunate 是形容词，不能单独放句首修饰整个句子；句中已有谓语 were，也不需要第二个表语。干扰点：提示词是形容词就填形容词原形。</li><li>B ❌ Unfortunately 意为「不幸的是」，与下文「母子平安」的语义相反；词形对了但逻辑反了。</li><li>C ❌ Fortune 是名词「运气」，放句首既不作主语（后面已有完整句子）也不能修饰全句。</li><li>D ✅ 副词作评注性状语修饰全句「母子都没有受伤」这件事，位于句首首字母大写 → Fortunately；课件原答案。</li></ul><p><strong>整句翻译</strong>：幸运的是，男孩和他的母亲都没有受伤。</p><p><strong>词组</strong>：<code>be unharmed</code> 没有受伤、安然无恙；<code>评注性状语</code> 位于句首、修饰全句的副语，表达说话人态度</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:8，比较两题的判断依据</p><p><strong>原文定位</strong>（真题一 2025 · 第1段第2句（空38））：____（fortunate）, the boy and his mother were unharmed.（副词修饰全句，句首大写）</p></details><p><strong>【2025 真题 · 提示词 wear】“He was actually ____ a Marvel coat that night, so I talked to him about some superheroes he liked,” Tim said.</strong></p><ul><li>A. wearing</li><li>B. wore</li><li>C. worn</li><li>D. wears</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（wearing）</strong> —— 原题为有提示词填空：与 was 构成过去进行时，表示当时正穿着漫威外套。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 与 was 构成过去进行时，表示「那晚当时正穿着」漫威外套；课件原答案。</li><li>B ❌ wore 是过去式谓语：句中已有 was，再放 wore 就是一句两谓语（was wore 结构不成立）。干扰点：只想到「穿」的过去式。</li><li>C ❌ worn 是过去分词，与 was 构成被动「被穿着」；人是主动穿衣，语态不通。</li><li>D ❌ wears 是一般现在时，与 that night 的过去时间冲突，且与 was 无法搭配。</li></ul><p><strong>整句翻译</strong>：「他那晚其实穿着一件漫威外套，所以我就和他聊了他喜欢的超级英雄。」蒂姆说。</p><p><strong>词组</strong>：<code>that night</code> 那天晚上（具体过去时间点）；<code>talk to sb. about sth.</code> 和某人谈论某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:7，比较两题的判断依据</p><p><strong>原文定位</strong>（真题一 2025 · 第2段（空39））：“He was actually ____（wear）a Marvel coat that night, so I talked to him about some superheroes he liked,” Tim said.</p></details><p><strong>【2025 真题 · 无提示词】“...so I talked to him ____ some superheroes he liked,” Tim said.</strong></p><ul><li>A. with</li><li>B. about</li><li>C. on</li><li>D. at</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（about）</strong> —— 原题为无提示词填空：固定搭配 talk to sb. about sth.。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ talk with sb. 表「与某人交谈」，但空格后接的是话题 some superheroes（物），不是交谈对象；与 to him 已用 with 属张冠李戴。干扰点：只记住 talk with 这个搭配。</li><li>B ✅ 固定搭配 talk to sb. about sth.：about 引出谈论的话题；课件原答案。</li><li>C ❌ talk on 后接正式议题（talk on politics），不用于聊「他喜欢的超级英雄」这类日常话题。</li><li>D ❌ talk at 表「对……说而不听对方讲」，语义不合，也不接话题。</li></ul><p><strong>整句翻译</strong>：所以我就和他聊了他喜欢的超级英雄。</p><p><strong>词组</strong>：<code>talk to sb. about sth.</code> 和某人谈论某事（about 引出话题）；<code>superhero</code> 超级英雄</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:5，比较两题的判断依据</p><p><strong>原文定位</strong>（真题一 2025 · 第2段（空40））：“...so I talked to him ____ some superheroes he liked,” Tim said.（talk to sb. about sth.）</p></details><p><strong>【2025 真题 · 无提示词】The real superhero of the night was Tim, ____ draped his turnout coat over the little boy as he watched his mother’s car get towed away.</strong></p><ul><li>A. which</li><li>B. who</li><li>C. whom</li><li>D. whose</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（who）</strong> —— 原题为无提示词填空：非限制性定语从句，先行词 Tim 指人，关系词作主语；that 不能用于逗号后的非限制性定语从句。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 逗号后是非限制性定语从句，which 指物，先行词 Tim 指人；that 才因非限制性出局，which 是因指代对象出局。</li><li>B ✅ 先行词 Tim 指人，关系词在从句中作主语（draped 的发出者），非限制性定语从句用 who；课件原答案。</li><li>C ❌ whom 是宾格，只能在从句中作宾语；本空是 draped 的主语。干扰点：看到人先行词就在 who/whom 里蒙。</li><li>D ❌ whose 表所属「谁的」，后面要接名词；空后是谓语 draped，不是名词。</li></ul><p><strong>整句翻译</strong>：那晚真正的超级英雄是蒂姆——他把自己的消防大衣披在小男孩身上，男孩眼看着母亲的车被拖走。</p><p><strong>词组</strong>：<code>drape sth. over sb.</code> 把……披在某人身上；<code>get towed away</code> 被拖走</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:2，比较两题的判断依据</p><p><strong>原文定位</strong>（真题一 2025 · 第3段第1句（空41））：The real superhero of the night was Tim, ____ draped his turnout coat over the little boy as he watched his mother&#39;s car get towed away.</p></details><p><strong>【2025 真题 · 提示词 power】This simple but ____ action that Tim did offered the little boy warmth and comfort in the storm.</strong></p><ul><li>A. powerfully</li><li>B. powerless</li><li>C. powerful</li><li>D. power</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（powerful）</strong> —— 原题为有提示词填空：形容词与 simple 并列，修饰 action（课件解析原写「作表语、修饰 something」，据原句语法校正）。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ powerfully 是副词，不能放在冠词/形容词位置上与 simple 并列修饰名词 action。干扰点：觉得「有力地做」该用副词。</li><li>B ❌ powerless 意为「无力的」，与下文「带来温暖和安慰」的正面语义矛盾。干扰点：只认出是形容词，没核对词义方向。</li><li>C ✅ 形容词 powerful 与 simple 由 but 连接，并列修饰名词 action；课件解析原写「作表语、修饰 something」，据原句语法校正为定语。</li><li>D ❌ power 是名词，不能直接修饰名词 action；此处需要形容词。</li></ul><p><strong>整句翻译</strong>：蒂姆这个简单却有力的举动，在暴风雪中给小男孩带来了温暖和安慰。</p><p><strong>词组</strong>：<code>simple but powerful</code> 简单却有力的（but 连接两个并列形容词）；<code>offer sb. warmth and comfort</code> 给某人带来温暖和安慰</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:7，比较两题的判断依据</p><p><strong>原文定位</strong>（真题一 2025 · 第3段第2句（空42））：This simple but ____（power）action that Tim did offered the little boy warmth and comfort in the storm.</p></details><p><strong>【2025 真题 · 提示词 share】A photo capturing the moment, ____ by the fire department on Facebook, quickly gained attention, with commenters praising the firefighter’s compassion.</strong></p><ul><li>A. sharing</li><li>B. to share</li><li>C. shares</li><li>D. shared</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（shared）</strong> —— 原题为有提示词填空：过去分词作后置定语，表示照片「被分享」。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ sharing 表主动「照片分享（别人）」，而照片是被分享的；主被动弄反。干扰点：只认出需要非谓语，没判方向。</li><li>B ❌ to share 表目的或将来「要去分享」，与「已被分享在脸书上」的事实不符。</li><li>C ❌ shares 是谓语形式：句中已有谓语 gained，非并列结构不能再放一个谓语。</li><li>D ✅ 过去分词 shared 作后置定语修饰 a photo，表示「（被）分享到脸书的照片」；课件原答案。</li></ul><p><strong>整句翻译</strong>：一张捕捉了这一刻的照片被消防部门分享到脸书上，很快引起关注，评论者纷纷称赞这位消防员的善举。</p><p><strong>词组</strong>：<code>capture the moment</code> 捕捉那一刻；<code>gain attention</code> 引起关注</p><p><strong>对比自测</strong>：做完后对照 quiz-t2:0，比较两题的判断依据</p><p><strong>原文定位</strong>（真题一 2025 · 第3段第3句（空43））：A photo capturing the moment, ____（share）by the fire department on Facebook, quickly gained attention...</p></details><p><strong>【2025 真题 · 提示词 reaction】“All the ____ online are incredible. All the positive comments people have left just makes me feel really proud of myself and the job I get to do every day,” Tim said.</strong></p><ul><li>A. reaction</li><li>B. reaction’s</li><li>C. reactions</li><li>D. reacting</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（reactions）</strong> —— 原题为有提示词填空：reaction 可数；All the 和复数谓语提示复数。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ reaction 是单数，与 All the（全部）和复数谓语 are 都不一致。干扰点：忘了看空后 are。</li><li>B ❌ reaction&#39;s 是所有格「反响的」，后面要接名词；空后就是谓语 are，不需要所有格。干扰点：名词题先想到所有格。</li><li>C ✅ reaction 可数；All the 和复数谓语 are 都提示用复数 reactions；课件原答案。</li><li>D ❌ reacting 是动名词/现在分词，不能充当本句被 All the 修饰的主语中心词。</li></ul><p><strong>整句翻译</strong>：「网上所有的反响都令人难以置信。人们留下的所有正面评论让我为自己和我每天能做的工作感到非常自豪。」蒂姆说。</p><p><strong>词组</strong>：<code>reaction</code> 反响、反应（可数名词）；<code>feel proud of oneself</code> 为自己感到自豪</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:7，比较两题的判断依据</p><p><strong>原文定位</strong>（真题一 2025 · 第4段（空44））：“All the ____（reaction）online are incredible. ...” Tim said.（All the + 复数，are 印证）</p></details><p><strong>【2025 真题 · 提示词 I】“All the positive comments people have left just makes me feel really proud of ____ and the job I get to do every day,” Tim said.</strong></p><ul><li>A. me</li><li>B. mine</li><li>C. myself</li><li>D. my</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（myself）</strong> —— 原题为有提示词填空：反身代词作 of 的宾语，并与主语 I 呼应。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ me 是宾格「我」，「为我自豪」与句意不符——蒂姆是为自己自豪；且 me 不与主语 I 呼应。干扰点：of 后面要宾语就填宾格。</li><li>B ❌ mine 是名词性物主代词「我的（东西）」，后面不能再接 and the job 并列的宾语结构，语义也不通。</li><li>C ✅ 反身代词 myself 作 of 的宾语，并与主语 I 呼应：proud of myself = 为自己自豪；课件原答案。</li><li>D ❌ my 是形容词性物主代词，后面必须接名词；空后是并列连词 and，不是名词。</li></ul><p><strong>整句翻译</strong>：人们留下的所有正面评论让我为自己和我每天能做的工作感到非常自豪。</p><p><strong>词组</strong>：<code>feel proud of oneself</code> 为自己感到自豪（oneself 与主语呼应）；<code>the job I get to do</code> 我得以从事的工作</p><p><strong>对比自测</strong>：做完后对照 quiz-t2:9，比较两题的判断依据</p><p><strong>原文定位</strong>（真题一 2025 · 第4段（空45））：“All the positive comments people have left just makes me feel really proud of ____（I）and the job I get to do every day,” Tim said.</p></details><h3 id="真题二-·-2024-年-技巧课-p30-32" tabindex="-1"><a class="header-anchor" href="#真题二-·-2024-年-技巧课-p30-32"><span>真题二 · 2024 年（技巧课 p30-32）</span></a></h3><p>On his tenth birthday, Tim woke to the news of a serious earthquake in the city where he was born. Living in another country but <strong>36 ______</strong>（name）after his birth city, Tim felt he was <strong>37 ______</strong>（deep）connected to the disaster. Driven by a strong desire to help, he <strong>38 ______</strong>（see）an opportunity to make a difference through his love of running. Two years before, Tim had run his first half-marathon, raising money for <strong>39 ______</strong> annual charity event for kids.</p><p>This time he set a new goal, <strong>40 ______</strong> was to run ten kilometers ten times, each run marking a year of his life. He was determined <strong>41 ______</strong>（use）this challenge to raise funds for the earthquake relief. Over the course of four months, he ran a total of 100 kilometers — more than two marathons. In his final run, the local charity center succeeded <strong>42 ______</strong> organizing a community event. Tim was joined by his father, his teacher and <strong>43 ______</strong>（member）of the local community.</p><p>In the end, Tim&#39;s project raised more than $100,000 for the earthquake victims. “Sometimes I felt <strong>44 ______</strong>（tire）. I remind <strong>45 ______</strong>（I）of local people. I&#39;m helping them and I&#39;m happy.”</p><p><strong>【2024 真题 · 提示词 name】Living in another country but ____ after his birth city, Tim felt he was deeply connected to the disaster.</strong></p><ul><li>A. named</li><li>B. naming</li><li>C. to name</li><li>D. name</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（named）</strong> —— 原题为有提示词填空：过去分词作状语；name 与 Tim 是被动关系。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 过去分词 named 作状语：name 与 Tim 是被动关系（蒂姆被以城市命名），与前面的 Living 并列；课件原答案。</li><li>B ❌ naming 表主动「蒂姆给（别人）命名」，与 be named after「被命名」的固定语义不符。干扰点：看不出 name 与 Tim 的被动关系。</li><li>C ❌ to name 表目的「为了命名」，与句意「虽然住在国外，但（因）以出生城市命名而感到相连」的逻辑不符。</li><li>D ❌ name 原形不能作非谓语；句中 felt 已是谓语，but 连接的是两个并列的分词状语结构。</li></ul><p><strong>整句翻译</strong>：蒂姆住在另一个国家，但以他出生的城市命名，他感到自己与这场灾难深深相连。</p><p><strong>词组</strong>：<code>be named after</code> 以……命名；<code>be connected to</code> 与……相连</p><p><strong>对比自测</strong>：做完后对照 quiz-t1:7，比较两题的判断依据</p><p><strong>原文定位</strong>（真题二 2024 · 第1段第2句（空36））：Living in another country but ____（name）after his birth city, Tim felt he was deeply connected to the disaster.</p></details><p><strong>【2024 真题 · 提示词 deep】...Tim felt he was ____ connected to the disaster.</strong></p><ul><li>A. deeply</li><li>B. deep</li><li>C. depth</li><li>D. deepen</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（deeply）</strong> —— 原题为有提示词填空：副词修饰形容词 connected。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 副词 deeply 修饰形容词 connected；deep 本身也可作副词，但此处与 connected 搭配表抽象程度用 deeply 更规范，且构词题考点是形容词加 -ly；课件原答案。</li><li>B ❌ deep 作副词多修饰具体深度（dig deep），修饰抽象的情感联系时习惯用 deeply；本题考形容词转副词的构词规则，deep 不体现词性转换。干扰点：deep 确实有副词词性。</li><li>C ❌ depth 是名词「深度」，不能修饰形容词 connected。</li><li>D ❌ deepen 是动词「加深」，was 后不能再接动词原形，语法不成立。</li></ul><p><strong>整句翻译</strong>：蒂姆感到自己与这场灾难深深相连。</p><p><strong>词组</strong>：<code>deeply connected</code> 深深地相连（副词修饰形容词）；<code>disaster</code> 灾难</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:3，比较两题的判断依据</p><p><strong>原文定位</strong>（真题二 2024 · 第1段第2句（空37））：Tim felt he was ____（deep）connected to the disaster.（副词修饰形容词）</p></details><p><strong>【2024 真题 · 提示词 see】Driven by a strong desire to help, he ____ an opportunity to make a difference through his love of running.</strong></p><ul><li>A. seen</li><li>B. saw</li><li>C. has seen</li><li>D. would see</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（saw）</strong> —— 原题为有提示词填空：全文叙述过去发生的事情，用一般过去时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ seen 是过去分词：句中缺少谓语（Driven... 是分词状语，不是谓语），缺谓语不能填非谓语。干扰点：句首的 Driven 让人误以为句中已有谓语。</li><li>B ✅ 全文叙述过去发生的事情（woke、had run），用一般过去时 saw；课件原答案。</li><li>C ❌ has seen 是现在完成时，与全文的过去叙事基调不一致；上下文没有「对现在有影响」的提示。</li><li>D ❌ would see 是过去将来时，「将会看见」与「当时看到了机会」的已然事实不符。</li></ul><p><strong>整句翻译</strong>：在强烈的助人愿望驱使下，他看到了一个通过自己对跑步的热爱来作出改变的机会。</p><p><strong>词组</strong>：<code>driven by a desire to help</code> 在助人愿望的驱使下；<code>make a difference</code> 作出改变、有所作为</p><p><strong>对比自测</strong>：做完后对照 quiz-t1:1，比较两题的判断依据</p><p><strong>原文定位</strong>（真题二 2024 · 第1段第3句（空38））：Driven by a strong desire to help, he ____（see）an opportunity to make a difference through his love of running.</p></details><p><strong>【2024 真题 · 无提示词】Two years before, Tim had run his first half-marathon, raising money for ____ annual charity event for kids.</strong></p><ul><li>A. a</li><li>B. the</li><li>C. one</li><li>D. an</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（an）</strong> —— 原题为无提示词填空：annual charity event 泛指一场年度活动，annual 以元音音素开头。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ a 用在辅音音素开头的词前，annual 以元音音素 /æ/ 开头，应用 an。干扰点：看字母 n 是辅音字母就选了 a。</li><li>B ❌ the 表特指，但这是第一次提到、泛指「一场」年度活动，没有限定依据。</li><li>C ❌ one 强调数量，不能替代冠词；且 for one annual charity event 的「一场」不需要强调。</li><li>D ✅ annual charity event 泛指一场年度活动，annual 以元音音素开头 → an；课件原答案。</li></ul><p><strong>整句翻译</strong>：两年前，蒂姆跑完了自己的第一次半程马拉松，为一场儿童年度慈善活动筹款。</p><p><strong>词组</strong>：<code>half-marathon</code> 半程马拉松；<code>raise money for</code> 为……筹款；<code>annual charity event</code> 年度慈善活动（annual 以元音音素开头）</p><p><strong>对比自测</strong>：做完后对照 quiz-t1:0，比较两题的判断依据</p><p><strong>原文定位</strong>（真题二 2024 · 第1段第4句（空39））：Two years before, Tim had run his first half-marathon, raising money for ____ annual charity event for kids.</p></details><p><strong>【2024 真题 · 无提示词】This time he set a new goal, ____ was to run ten kilometers ten times, each run marking a year of his life.</strong></p><ul><li>A. what</li><li>B. that</li><li>C. which</li><li>D. it</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（which）</strong> —— 原题为无提示词填空：非限制性定语从句，先行词 a new goal 指物，关系词作主语；that 不能用于逗号后的非限制性定语从句。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ what 引导名词性从句，但空格前是完整句 + 逗号，需要定语从句修饰 a new goal；what 不能引导定语从句。干扰点：见逗号就以为从句独立。</li><li>B ❌ 逗号后是非限制性定语从句，that 不能用于逗号后的非限制性定语从句。</li><li>C ✅ 先行词 a new goal 指物，关系词在从句中作主语，非限制性定语从句用 which；课件原答案。</li><li>D ❌ it 使句子变成两套主谓（he set a goal, it was...）而无连词，结构不成立。</li></ul><p><strong>整句翻译</strong>：这次他设定了一个新目标——跑十次十公里，每一次跑纪念他生命中的一岁。</p><p><strong>词组</strong>：<code>set a goal</code> 设定目标；<code>mark a year of one&#39;s life</code> 纪念生命中的一岁</p><p><strong>对比自测</strong>：做完后对照 quiz-c:1，比较两题的判断依据</p><p><strong>原文定位</strong>（真题二 2024 · 第2段第1句（空40））：This time he set a new goal, ____ was to run ten kilometers ten times, each run marking a year of his life.</p></details><p><strong>【2024 真题 · 提示词 use】He was determined ____ this challenge to raise funds for the earthquake relief.</strong></p><ul><li>A. using</li><li>B. used</li><li>C. use</li><li>D. to use</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（to use）</strong> —— 原题为有提示词填空：固定搭配 be determined to do sth.。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ using 不能跟在 be determined 后；determined 已形容词化，后面用不定式。干扰点：把 determine 当普通动词接 doing。</li><li>B ❌ used 作过去分词会被读成被动或完成，be determined used 结构不成立。</li><li>C ❌ use 原形不能接在 was determined 后；谓语已完整，缺的是非谓语部分。</li><li>D ✅ 固定搭配 be determined to do sth.：不定式作状语；课件原答案。</li></ul><p><strong>整句翻译</strong>：他决心用这次挑战为地震救援筹款。</p><p><strong>词组</strong>：<code>be determined to do sth.</code> 决心做某事（固定搭配，接不定式）；<code>raise funds for</code> 为……筹款</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:9，比较两题的判断依据</p><p><strong>原文定位</strong>（真题二 2024 · 第2段第2句（空41））：He was determined ____（use）this challenge to raise funds for the earthquake relief.</p></details><p><strong>【2024 真题 · 无提示词】In his final run, the local charity center succeeded ____ organizing a community event.</strong></p><ul><li>A. on</li><li>B. in</li><li>C. at</li><li>D. to</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（in）</strong> —— 原题为无提示词填空：固定搭配 succeed in doing sth.。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ succeed on 不成立；on 可接具体日期或主题，不与 succeed 搭配表「成功做某事」。干扰点：只记得 succeed 后有个介词。</li><li>B ✅ 固定搭配 succeed in doing sth.；课件原答案。</li><li>C ❌ succeed at 后可接名词（succeed at school），但不接 doing 表成功完成某事。</li><li>D ❌ to 会让人联想到不定式，但 succeed 后不接不定式；succeed to 是「继承（王位等）」，语义完全不同。</li></ul><p><strong>整句翻译</strong>：在最后一跑中，当地慈善中心成功组织了一次社区活动。</p><p><strong>词组</strong>：<code>succeed in doing sth.</code> 成功做某事（in 后接动名词）；<code>organize a community event</code> 组织社区活动</p><p><strong>对比自测</strong>：做完后对照 quiz-p5:8，比较两题的判断依据</p><p><strong>原文定位</strong>（真题二 2024 · 第2段第3句（空42））：In his final run, the local charity center succeeded ____ organizing a community event.（succeed in doing）</p></details><p><strong>【2024 真题 · 提示词 member】Tim was joined by his father, his teacher and ____ of the local community.</strong></p><ul><li>A. member</li><li>B. member’s</li><li>C. members</li><li>D. membership</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（members）</strong> —— 原题为有提示词填空：member 可数，语境表示当地社区的多名成员。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ member 单数与语境不符：并列的是 father、teacher 和「社区成员们」，指多名成员；且单数可数名词前缺限定词。</li><li>B ❌ member&#39;s 是所有格「成员的」，后面要接名词，而空后就是 of 短语。</li><li>C ✅ member 可数，语境表示当地社区的多名成员，用复数 members；课件原答案。</li><li>D ❌ membership 意为「会员资格、成员身份」，是抽象名词，不能指具体的人。</li></ul><p><strong>整句翻译</strong>：蒂姆的父亲、老师和当地社区的成员们一起加入了他。</p><p><strong>词组</strong>：<code>be joined by</code> 由……陪同加入；<code>members of the community</code> 社区成员（复数，指多人）</p><p><strong>对比自测</strong>：做完后对照 quiz-t1:8，比较两题的判断依据</p><p><strong>原文定位</strong>（真题二 2024 · 第2段第3句（空43））：Tim was joined by his father, his teacher and ____（member）of the local community.</p></details><p><strong>【2024 真题 · 提示词 tire】“Sometimes I felt ____. I remind myself of local people. I’m helping them and I’m happy.”</strong></p><ul><li>A. tiring</li><li>B. tires</li><li>C. tired</li><li>D. tireless</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（tired）</strong> —— 原题为有提示词填空：felt 是系动词，用形容词描述人的感受。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ tiring 意为「令人疲倦的」，主语应是人时它描述的是「使人累」的属性；「我感到累」要用 -ed。干扰点：分不清 -ing/-ed 形容词的分工。</li><li>B ❌ tires 是动词第三人称单数「使疲倦」，felt 后不能再接谓语动词。</li><li>C ✅ felt 是系动词，用形容词描述人的感受 → tired；课件原答案。</li><li>D ❌ tireless 意为「不知疲倦的」，与下文「提醒自己、坚持下去」的语境（累但仍坚持）不符。</li></ul><p><strong>整句翻译</strong>：「有时我觉得累。我提醒自己当地的人们。我在帮助他们，我很快乐。」</p><p><strong>词组</strong>：<code>feel tired</code> 感到疲倦（-ed 形容词描述人的感受）；<code>remind oneself of</code> 提醒自己想起</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:4，比较两题的判断依据</p><p><strong>原文定位</strong>（真题二 2024 · 第3段（空44））：“Sometimes I felt ____（tire）. I remind myself of local people. I&#39;m helping them and I&#39;m happy.”</p></details><p><strong>【2024 真题 · 提示词 I】“I remind ____ of local people. I’m helping them and I’m happy.”</strong></p><ul><li>A. me</li><li>B. mine</li><li>C. my</li><li>D. myself</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（myself）</strong> —— 原题为有提示词填空：固定搭配 remind oneself of sth.，与主语 I 呼应。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ me 是宾格「我」：remind me of 意为「使我想起」，与「累的时候给自己打气」的句意不符；且不与主语 I 呼应。</li><li>B ❌ mine 是名词性物主代词「我的（东西）」，语义与语法都不成立。</li><li>C ❌ my 是形容词性物主代词，后面必须接名词，而空后是介词 of。</li><li>D ✅ 固定搭配 remind oneself of sth.，oneself 与主语 I 呼应 → myself；课件原答案。</li></ul><p><strong>整句翻译</strong>：我提醒自己想起当地的人们。</p><p><strong>词组</strong>：<code>remind oneself of sth.</code> 提醒自己想起某事（固定搭配）；<code>local people</code> 当地的人们</p><p><strong>对比自测</strong>：做完后对照 quiz-t1:9，比较两题的判断依据</p><p><strong>原文定位</strong>（真题二 2024 · 第3段（空45））：“Sometimes I felt tired. I remind ____（I）of local people. I&#39;m helping them and I&#39;m happy.”</p></details><h3 id="练习一-·-余光中与《乡愁》-题海-p5" tabindex="-1"><a class="header-anchor" href="#练习一-·-余光中与《乡愁》-题海-p5"><span>练习一 · 余光中与《乡愁》（题海 P5）</span></a></h3><p>He was a poet known for the nostalgia（乡愁）he describes in his poems. Now, it&#39;s time for us to express <strong>1. ______</strong>（we）nostalgia for this great writer.</p><p>On December 14, 2017, the famous Chinese poet Yu Guangzhong passed away in Taiwan. He was born in 1928 in Nanjing, Jiangsu. Yu and his family moved to Taiwan in the 1950s. He lived and worked there until his <strong>2. ______</strong>（die）.</p><p><em>Nostalgia</em> is Yu&#39;s famous poem in which he <strong>3. ______</strong>（express）his homesickness（乡愁）for the Chinese mainland when he was in Taiwan. The poem came out in 1971, and it remains highly popular among Chinese <strong>4. ______</strong>（speaker）worldwide. Even those who know little about literature enjoy lines from the poem. The poem is <strong>5. ______</strong>（include）in Chinese high school textbooks.</p><p>Besides his <strong>6. ______</strong>（achievement）in poems, Yu was also <strong>7. ______</strong> successful translator（翻译家）, essay writer and critic. He once <strong>8. ______</strong>（translate）English poet Siegfried Sassoon&#39;s poem <em>In Me, Past, Present, Future Meet</em> into Chinese. It is regarded as a perfect and powerful translation, in which the most famous line is “心有猛虎，细嗅蔷薇” for “In me the tiger sniffs the rose”.</p><p>Yu spent his whole life <strong>9. ______</strong>（write）. In a 2015 interview with <em>People&#39;s Daily</em>, he said, “The reason <strong>10. ______</strong> I stick to writing till today is my passion（热爱）for the Chinese language.” He then added that his love for his mother and his motherland made this passion stronger.</p><p><strong>【练习一 · 提示词 we】Now, it’s time for us to express ____ nostalgia for this great writer.</strong></p><ul><li>A. our</li><li>B. us</li><li>C. ours</li><li>D. we</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（our）</strong> —— 笔记补充解析（原题为有提示词填空）：形容词性物主代词修饰 nostalgia。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 形容词性物主代词 our 修饰名词 nostalgia，并与主语 us 呼应（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ us 是宾格，不能放在名词前作定语。干扰点：与主句 for us 呼应就选了宾格。</li><li>C ❌ ours 是名词性物主代词，后面不能再接名词 nostalgia。</li><li>D ❌ we 是主格，不能修饰名词；express we nostalgia 结构不成立。</li></ul><p><strong>整句翻译</strong>：现在，轮到我们表达对这位伟大作家自己的乡愁了。</p><p><strong>词组</strong>：<code>it is time for sb. to do sth.</code> 轮到某人做某事了；<code>express one&#39;s nostalgia</code> 表达某人的乡愁</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 第1段第2句（空1，提示词 we））：Now, it&#39;s time for us to express ____（we）nostalgia for this great writer.</p></details><p><strong>【练习一 · 提示词 die】He lived and worked there until his ____.</strong></p><ul><li>A. died</li><li>B. dying</li><li>C. death</li><li>D. dead</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（death）</strong> —— 笔记补充解析（原题为有提示词填空）：物主代词 his 后用名词。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ died 是过去式谓语：until 后接从句才用句子，接名词性成分时要用名词；his died 结构不成立。干扰点：提示词 die 先想到过去式。</li><li>B ❌ dying 是动名词/现在分词「垂死的/临终」，his dying 可表「他的临终时刻」，但 until his dying 不是自然搭配，常规答案是名词 death。</li><li>C ✅ 物主代词 his 后用名词：until his death = 直到他去世（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ dead 是形容词「死的」，his dead 后缺名词中心词，until his dead 读不通。</li></ul><p><strong>整句翻译</strong>：他在那里生活、工作，直到去世。</p><p><strong>词组</strong>：<code>live and work</code> 生活与工作；<code>until one&#39;s death</code> 直到某人去世（death 是名词）</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 第2段末句（空2，提示词 die））：He lived and worked there until his ____（die）.</p></details><p><strong>【练习一 · 提示词 express】Nostalgia is Yu’s famous poem in which he ____ his homesickness for the Chinese mainland when he was in Taiwan.</strong></p><ul><li>A. expresses</li><li>B. expressing</li><li>C. has expressed</li><li>D. expressed</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（expressed）</strong> —— 笔记补充解析（原题为有提示词填空）：诗写于过去，且 when he was in Taiwan 提示一般过去时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ expresses 是一般现在时：写诗是过去的行为，且定语从句中 when he was in Taiwan 明确指向过去。干扰点：诗「表达乡愁」是永恒事实，容易误用现在时。</li><li>B ❌ expressing 是非谓语：定语从句 in which he ____ 缺少从句谓语，必须填谓语动词。</li><li>C ❌ has expressed 是现在完成时：强调「至今已经表达」与从句的过去时间状语 was 冲突；诗歌创作是明确的过去事件。</li><li>D ✅ 诗写于过去，when he was in Taiwan 提示一般过去时 → expressed（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：《乡愁》是余光中的名篇，他在台湾时在这首诗里表达了对大陆的乡愁。</p><p><strong>词组</strong>：<code>homesickness for</code> 对……的乡愁；<code>the Chinese mainland</code> 中国大陆</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 第3段第1句（空3，提示词 express））：Nostalgia is Yu&#39;s famous poem in which he ____（express）his homesickness for the Chinese mainland when he was in Taiwan.</p></details><p><strong>【练习一 · 提示词 speaker】The poem came out in 1971, and it remains highly popular among Chinese ____ worldwide.</strong></p><ul><li>A. speaker</li><li>B. speakers</li><li>C. speaker’s</li><li>D. spoken</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（speakers）</strong> —— 笔记补充解析（原题为有提示词填空）：指世界各地说中文的人，应用可数名词复数。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ speaker 单数：among 后指「世界各地的说中文的人们」，是复数概念；且单数可数名词前缺冠词。</li><li>B ✅ 指世界各地说中文的人，应用可数名词复数 speakers（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ speaker&#39;s 是所有格「说话者的」，后面要接名词，而空后是谓语/介词结构。</li><li>D ❌ spoken 是过去分词「口头的」，不能指人；spoken 作定语常见搭配是 spoken English。</li></ul><p><strong>整句翻译</strong>：这首诗发表于 1971 年，至今仍在全球华人中广受欢迎。</p><p><strong>词组</strong>：<code>come out</code> （作品）发表、出版；<code>Chinese speakers</code> 说中文的人（复数泛指一类人）</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 第3段第2句（空4，提示词 speaker））：The poem came out in 1971, and it remains highly popular among Chinese ____（speaker）worldwide.</p></details><p><strong>【练习一 · 提示词 include】The poem is ____ in Chinese high school textbooks.</strong></p><ul><li>A. including</li><li>B. includes</li><li>C. included</li><li>D. to include</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（included）</strong> —— 笔记补充解析（原题为有提示词填空）：诗「被收录」进教材，用被动语态。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ including 是现在分词：诗「包括教材」主被动反了，且 is including 会被读成进行时「正在包括」。</li><li>B ❌ includes 是主动语态第三人称单数：诗不会自己「收录」教材，语态与语义都不通。</li><li>C ✅ 诗「被收录」进教材，与 is 构成被动语态 → included（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ to include 表目的或将来「要去收录」，与「已被收录进教材」的事实状态不符。</li></ul><p><strong>整句翻译</strong>：这首诗被收录进中学语文教材。</p><p><strong>词组</strong>：<code>be included in</code> 被收录进……；<code>textbook</code> 教科书</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 第3段末句（空5，提示词 include））：The poem is ____（include）in Chinese high school textbooks.</p></details><p><strong>【练习一 · 提示词 achievement】Besides his ____ in poems, Yu was also a successful translator, essay writer and critic.</strong></p><ul><li>A. achievement</li><li>B. achievements</li><li>C. achieving</li><li>D. achievement’s</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（achievements）</strong> —— 笔记补充解析（原题为有提示词填空）：achievement 为可数名词，语境指多项成就。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ achievement 单数：诗歌、翻译、散文等多领域成就，语境指多项成就；且 his achievement 特指单一成就与后文并列身份不搭。</li><li>B ✅ achievement 为可数名词，语境指他在诗歌上的多项成就 → 复数 achievements（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ achieving 是动名词，his 后需要的是名词中心词。</li><li>D ❌ achievement&#39;s 是所有格「成就的」，后面要接名词；besides his achievement&#39;s 没有可接的名词。</li></ul><p><strong>整句翻译</strong>：除了他在诗歌上的成就，余光中还是一位成功的翻译家、散文家和评论家。</p><p><strong>词组</strong>：<code>achievements in poems</code> 诗歌方面的成就（多项，用复数）；<code>essay writer</code> 散文家</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 第4段第1句（空6，提示词 achievement））：Besides his ____（achievement）in poems, Yu was also a successful translator, essay writer and critic.</p></details><p><strong>【练习一 · 无提示词】Besides his achievements in poems, Yu was also ____ successful translator, essay writer and critic.</strong></p><ul><li>A. an</li><li>B. the</li><li>C. one</li><li>D. a</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（a）</strong> —— 笔记补充解析（原题为无提示词填空）：translator 是可数名词单数，successful 以辅音音素开头。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ an 用于元音音素开头的词前，successful 以辅音音素 /s/ 开头，应用 a。干扰点：successful 含元音字母 u 就选了 an。</li><li>B ❌ the 表特指，但这里首次介绍他的身份，泛指「一位」。</li><li>C ❌ one 强调数量「一个」，身份介绍不需要强调；且 one 不充当冠词角色。</li><li>D ✅ translator 是可数名词单数、泛指一位，successful 以辅音音素开头 → a（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：除了诗歌成就，他还是一位成功的翻译家、散文家和评论家。</p><p><strong>词组</strong>：<code>a successful translator</code> 一位成功的翻译家（successful 以辅音音素开头）；<code>a translator, essay writer and critic</code> 一位翻译家、散文家和评论家（一人多身份共用一个冠词）</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 第4段第1句（空7，无提示词））：Besides his achievements in poems, Yu was also ____ successful translator, essay writer and critic.</p></details><p><strong>【练习一 · 提示词 translate】He once ____ English poet Siegfried Sassoon’s poem In Me, Past, Present, Future Meet into Chinese.</strong></p><ul><li>A. translates</li><li>B. translating</li><li>C. has translated</li><li>D. translated</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（translated）</strong> —— 笔记补充解析（原题为有提示词填空）：once 叙述过去的翻译行为，用一般过去时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ translates 是一般现在时：once「曾经」明确指向过去的翻译行为。干扰点：认为这是客观事实就用现在时。</li><li>B ❌ translating 是非谓语：句中 He once 后缺谓语，必须填谓语动词。</li><li>C ❌ has translated 是现在完成时：翻译萨松这首诗是具体的过去事件，没有「持续到现在」的语境；once 叙述往事时用一般过去时更自然。</li><li>D ✅ once 叙述过去的翻译行为，用一般过去时 translated（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：他曾把英国诗人西格夫里·萨松的诗《于我，过去，现在以及未来》译成中文。</p><p><strong>词组</strong>：<code>once</code> 曾经（提示过去的行为）；<code>translate...into...</code> 把……翻译成……</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 第4段第2句（空8，提示词 translate））：He once ____（translate）English poet Siegfried Sassoon&#39;s poem In Me, Past, Present, Future Meet into Chinese.</p></details><p><strong>【练习一 · 提示词 write】Yu spent his whole life ____.</strong></p><ul><li>A. writing</li><li>B. to write</li><li>C. wrote</li><li>D. written</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（writing）</strong> —— 笔记补充解析（原题为有提示词填空）：固定搭配 spend time doing sth.。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 固定搭配 spend time (in) doing sth. → writing（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ to write 是目的/将来含义：spend 后不接不定式；「花费一生去写」在 spend 句型里要用 doing。干扰点：把「为了写作」的目的义套进 spend。</li><li>C ❌ wrote 是谓语形式：句中已有谓语 spent，再填 wrote 就一句两谓语。</li><li>D ❌ written 是过去分词，表被动或完成：Yu 与 write 是主动关系，且 spend 结构不用过去分词。</li></ul><p><strong>整句翻译</strong>：余光中一生都在写作。</p><p><strong>词组</strong>：<code>spend one&#39;s life doing sth.</code> 一生/花费时间做某事（spend 后接动名词）；<code>whole</code> 整个的</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 第5段第1句（空9，提示词 write））：Yu spent his whole life ____（write）.（spend time doing）</p></details><p><strong>【练习一 · 无提示词】The reason ____ I stick to writing till today is my passion for the Chinese language.</strong></p><ul><li>A. why</li><li>B. which</li><li>C. what</li><li>D. when</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（why）</strong> —— 笔记补充解析（原题为无提示词填空）：固定结构 the reason why...，关系副词在从句中作原因状语。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 固定结构 the reason why...：why 是关系副词，在从句中作原因状语（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ which 是关系代词，要在从句中作主语或宾语；从句 I stick to writing 成分完整，不缺主宾。干扰点：见名词就想用 which。</li><li>C ❌ what 引导名词性从句，不能引导修饰 reason 的定语从句。</li><li>D ❌ when 是时间关系副词：从句不缺时间状语，缺的是原因状语。</li></ul><p><strong>整句翻译</strong>：「我坚持写作至今的原因是我对中文的热爱。」</p><p><strong>词组</strong>：<code>the reason why...</code> ……的原因（why 引导定语从句修饰 reason）；<code>stick to doing sth.</code> 坚持做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-c:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习一 · 第5段第2句（空10，无提示词））：“The reason ____ I stick to writing till today is my passion for the Chinese language.”（the reason why...）</p></details><h3 id="练习二-·-英国学校假期-题海-p5-6" tabindex="-1"><a class="header-anchor" href="#练习二-·-英国学校假期-题海-p5-6"><span>练习二 · 英国学校假期（题海 P5-6）</span></a></h3><p>Do you know what is special about November and June in the UK? They are, possibly, the only two months with no school holidays. A newspaper <strong>1. ______</strong>（recent）did a survey among a group of students. In the survey, 68 percent <strong>2. ______</strong> the students said that their parents were at work in the school holidays. 73 percent <strong>3. ______</strong>（say）that they were bored during the school holidays and 35 percent said they were happy to <strong>4. ______</strong>（go）back to school! The results of the survey show that not everybody <strong>5. ______</strong>（want）to have many holidays.</p><p>If you don&#39;t want to stay at home and get bored, take part in some <strong>6. ______</strong>（interest）activities. A lot of schools organize various trips during the holidays, <strong>7. ______</strong>（especial）when they have a one-week holiday. You have many choices to make.</p><p>Many <strong>8. ______</strong>（school）take groups of students to some training centers. There, students can learn a lot from outdoor activities. <strong>9. ______</strong> example, students learn how to make a camp in the forest. At the same time, they are <strong>10. ______</strong>（teach）how to find their way back to the centre. In most towns, some other centers offer students different courses, such as computer game design, film making and painting. Students can also go abroad for school trips.</p><p><strong>【练习二 · 提示词 recent】A newspaper ____ did a survey among a group of students.</strong></p><ul><li>A. recent</li><li>B. recently</li><li>C. more recent</li><li>D. recentness</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（recently）</strong> —— 笔记补充解析（原题为有提示词填空）：副词修饰动词 did。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ recent 是形容词，不能修饰动词 did；a newspaper recent did 结构不成立。干扰点：提示词是形容词就照抄。</li><li>B ✅ 副词 recently 修饰动词 did（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ more recent 是比较级：句中没有比较对象，且比较级形容词同样不能修饰动词。</li><li>D ❌ recentness 是名词「新近」，不能修饰动词。</li></ul><p><strong>整句翻译</strong>：一家报纸最近在一群学生中做了一项调查。</p><p><strong>词组</strong>：<code>do a survey among</code> 在……中做调查；<code>recently</code> 最近（副词修饰动词 did）</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 第1段第3句（空1，提示词 recent））：A newspaper ____（recent）did a survey among a group of students.</p></details><p><strong>【练习二 · 无提示词】In the survey, 68 percent ____ the students said that their parents were at work in the school holidays.</strong></p><ul><li>A. in</li><li>B. of</li><li>C. for</li><li>D. from</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（of）</strong> —— 笔记补充解析（原题为无提示词填空）：... percent of + 名词。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ in the students 不表所属比例；percent 不与 in 搭配。</li><li>B ✅ 固定结构：数字 + percent of + 名词（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ for the students 表「为了学生」，不表比例关系。</li><li>D ❌ from the students 表「来自学生」，与比例结构无关。</li></ul><p><strong>整句翻译</strong>：调查中，68% 的学生说他们的父母在学校假期里要上班。</p><p><strong>词组</strong>：<code>68 percent of the students</code> 68% 的学生（percent of + 名词）；<code>be at work</code> 在上班</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 第1段第4句（空2，无提示词））：In the survey, 68 percent ____ the students said that their parents were at work in the school holidays.（percent of）</p></details><p><strong>【练习二 · 提示词 say】73 percent ____ that they were bored during the school holidays and 35 percent said they were happy to go back to school!</strong></p><ul><li>A. said</li><li>B. says</li><li>C. saying</li><li>D. has said</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（said）</strong> —— 笔记补充解析（原题为有提示词填空）：调查发生在过去，与前文 did 一致。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 调查发生在过去，与前文 did 一致 → 一般过去时 said（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ says 是一般现在时：从句 were bored 是过去时，主句时态应与其呼应为过去。干扰点：调查结果当作普遍事实。</li><li>C ❌ saying 是非谓语：73 percent 后缺谓语，必须填谓语动词。</li><li>D ❌ has said 是现在完成时：与并列分句 said 时态不一致，且无持续到现在的时间提示。</li></ul><p><strong>整句翻译</strong>：73% 的学生说他们在学校假期里很无聊，35% 的学生说他们乐于返校。</p><p><strong>词组</strong>：<code>be bored during</code> 在……期间感到无聊；<code>be happy to do sth.</code> 乐于做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 第1段第4句（空3，提示词 say））：73 percent ____（say）that they were bored during the school holidays and 35 percent said they were happy to go back to school!</p></details><p><strong>【练习二 · 提示词 go】...and 35 percent said they were happy to ____ back to school!</strong></p><ul><li>A. going</li><li>B. went</li><li>C. go</li><li>D. gone</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（go）</strong> —— 笔记补充解析（原题为有提示词填空）：be happy to do sth.。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ going 是动名词：be happy 后不接 doing 表「乐于做」。干扰点：把 happy doing 当成可行搭配。</li><li>B ❌ went 是过去式谓语：to 后接动词原形构成不定式，to went 不成立。</li><li>C ✅ 固定搭配 be happy to do sth. → to go（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ gone 是过去分词：to gone 结构不成立。</li></ul><p><strong>整句翻译</strong>：35% 的学生说他们乐于返校。</p><p><strong>词组</strong>：<code>be happy to do sth.</code> 乐于/高兴做某事（固定搭配接不定式）；<code>go back to school</code> 返校</p><p><strong>对比自测</strong>：做完后对照 quiz-t2:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 第1段第4句（空4，提示词 go））：...35 percent said they were happy to ____（go）back to school!（be happy to do）</p></details><p><strong>【练习二 · 提示词 want】The results of the survey show that not everybody ____ to have many holidays.</strong></p><ul><li>A. wants</li><li>B. want</li><li>C. wanted</li><li>D. wanting</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（wants）</strong> —— 笔记补充解析（原题为有提示词填空）：不定代词 everybody 作主语，谓语用第三人称单数。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 不定代词 everybody 作主语，谓语用第三人称单数 wants；宾语从句陈述普遍结论，用一般现在时（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ want 是复数/原形形式：everybody 是单数概念，主谓不一致。干扰点：everybody 指「所有人」就当成复数。</li><li>C ❌ wanted 是过去时：主句 show 是一般现在时，从句陈述调查结论，时态应保持一致；也没有过去时间提示。</li><li>D ❌ wanting 是非谓语：从句中 everybody 后缺谓语。</li></ul><p><strong>整句翻译</strong>：调查结果显示，并不是每个人都想有很多假期。</p><p><strong>词组</strong>：<code>not everybody</code> 并非每个人（部分否定）；<code>the results of the survey</code> 调查结果</p><p><strong>对比自测</strong>：做完后对照 quiz-p5:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 第1段末句（空5，提示词 want））：The results of the survey show that not everybody ____（want）to have many holidays.（everybody 单数）</p></details><p><strong>【练习二 · 提示词 interest】If you don’t want to stay at home and get bored, take part in some ____ activities.</strong></p><ul><li>A. interested</li><li>B. interest</li><li>C. interesting</li><li>D. interestingly</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（interesting）</strong> —— 笔记补充解析（原题为有提示词填空）：修饰事物 activities，表示「有趣的」。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ interested 修饰「感到兴趣的人」，activities 是事物，应用 -ing。干扰点：-ed/-ing 形容词分工记反。</li><li>B ❌ interest 是名词/动词原形，不能直接修饰名词 activities。</li><li>C ✅ 修饰事物 activities，表示「有趣的」→ interesting（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ interestingly 是副词：名词前作定语要用形容词，不能用副词。</li></ul><p><strong>整句翻译</strong>：如果你不想待在家里无聊，就参加一些有趣的活动吧。</p><p><strong>词组</strong>：<code>take part in</code> 参加；<code>interesting activities</code> 有趣的活动（-ing 修饰事物）</p><p><strong>对比自测</strong>：做完后对照 quiz-p5:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 第2段第1句（空6，提示词 interest））：If you don&#39;t want to stay at home and get bored, take part in some ____（interest）activities.</p></details><p><strong>【练习二 · 提示词 especial】A lot of schools organize various trips during the holidays, ____ when they have a one-week holiday.</strong></p><ul><li>A. especial</li><li>B. more especial</li><li>C. especially</li><li>D. especialness</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（especially）</strong> —— 笔记补充解析（原题为有提示词填空）：副词强调后面的时间状语从句。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ especial 是形容词，不能修饰后面的时间状语从句。</li><li>B ❌ more especial 是比较级：句中没有比较对象，且词性仍是形容词，修饰不了从句。</li><li>C ✅ 副词 especially 强调后面的时间状语从句 when they have a one-week holiday（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ especialness 是名词「特殊性」，不能起强调作用。</li></ul><p><strong>整句翻译</strong>：许多学校利用假期组织各种各样的旅行，尤其是在有一周长假的时候。</p><p><strong>词组</strong>：<code>organize trips</code> 组织旅行；<code>especially when...</code> 尤其是在……的时候（副词强调后面的从句）</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 第2段第2句（空7，提示词 especial））：A lot of schools organize various trips during the holidays, ____（especial）when they have a one-week holiday.</p></details><p><strong>【练习二 · 提示词 school】Many ____ take groups of students to some training centers.</strong></p><ul><li>A. school</li><li>B. schools</li><li>C. school’s</li><li>D. schooling</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（schools）</strong> —— 笔记补充解析（原题为有提示词填空）：many 后接可数名词复数。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ school 单数：many 后必须接可数名词复数；且谓语 take 是复数形式，主语必须是复数。</li><li>B ✅ many 后接可数名词复数 schools（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ school&#39;s 是所有格「学校的」，后面要接名词，而空后是谓语 take。</li><li>D ❌ schooling 意为「学校教育」，不能指「学校（机构）」这个意思，与 take groups of students 的主语语义不符。</li></ul><p><strong>整句翻译</strong>：许多学校带学生团体去一些培训中心。</p><p><strong>词组</strong>：<code>many + 可数复数</code> 许多……（many 后接可数名词复数）；<code>take sb. to sp.</code> 带某人去某地</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 第3段第1句（空8，提示词 school））：Many ____（school）take groups of students to some training centers.</p></details><p><strong>【练习二 · 无提示词】____ example, students learn how to make a camp in the forest.</strong></p><ul><li>A. In</li><li>B. At</li><li>C. On</li><li>D. For</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（For）</strong> —— 笔记补充解析（原题为无提示词填空）：固定搭配 for example，位于句首首字母大写。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ in example 不成立；in 与 example 无此固定搭配。干扰点：凭语感选了常见介词 in。</li><li>B ❌ at example 不成立。</li><li>C ❌ on example 不成立；on 与 example 无搭配关系。</li><li>D ✅ 固定搭配 for example，位于句首首字母大写 → For（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：例如，学生们学习如何在森林里搭帐篷。</p><p><strong>词组</strong>：<code>for example</code> 例如（固定短语，位于句首时 For 大写）；<code>make a camp</code> 搭帐篷、扎营</p><p><strong>对比自测</strong>：做完后对照 quiz-p5:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 第3段第2句（空9，无提示词））：____ example, students learn how to make a camp in the forest.（For example）</p></details><p><strong>【练习二 · 提示词 teach】At the same time, they are ____ how to find their way back to the centre.</strong></p><ul><li>A. teaching</li><li>B. to teach</li><li>C. teach</li><li>D. taught</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（taught）</strong> —— 笔记补充解析（原题为有提示词填空）：学生「被教」，与 are 构成被动语态。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ teaching 与 are 构成进行时「正在教」：主语 they（students）是被教的一方，语态反了。</li><li>B ❌ to teach 是不定式：are to teach 会读成「将要教」，学生是学的一方不是教的一方。</li><li>C ❌ teach 是动词原形：are 后不能直接接原形，语法不成立。</li><li>D ✅ 学生「被教」，与 are 构成被动语态 → taught（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：同时，他们还被教会如何找到返回中心的路。</p><p><strong>词组</strong>：<code>at the same time</code> 同时；<code>find one&#39;s way back</code> 找到回去的路</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习二 · 第3段第3句（空10，提示词 teach））：At the same time, they are ____（teach）how to find their way back to the centre.</p></details><h3 id="练习三-·-我与母亲的关系-题海-p6" tabindex="-1"><a class="header-anchor" href="#练习三-·-我与母亲的关系-题海-p6"><span>练习三 · 我与母亲的关系（题海 P6）</span></a></h3><p>My relationship with my mother changed after I <strong>1. ______</strong>（go）to college. When I was at home, we argued about many things, for example, wearing makeup（化妆）and <strong>2. ______</strong>（talk）on the phone. One time, before a big party, she refused to let me <strong>3. ______</strong>（leave）the house. She thought <strong>4. ______</strong>（I）makeup was too heavy. I had to wash my face before I went to the party. I was the only girl <strong>5. ______</strong> makeup, and I was so mad. And when I talked to my friends on the phone, my mum always shouted to tell me to hang up, and the person I was talking to could hear her. Her <strong>6. ______</strong>（behave）always made me upset.</p><p>But after a few months at college, I changed <strong>7. ______</strong>（me）completely. I met new people. I started learning about history, politics, and the world. I didn&#39;t have the time or <strong>8. ______</strong>（patient）for long phone conversations. I stopped <strong>9. ______</strong>（care）so much about things like makeup. I once went to a party with no makeup on, but I felt fine. I just laughed about it. My new way of thinking brought me <strong>10. ______</strong>（close）to my mother than before. Now, I talk to my mother almost every day.</p><p><strong>【练习三 · 提示词 go】My relationship with my mother changed after I ____ to college.</strong></p><ul><li>A. go</li><li>B. gone</li><li>C. went</li><li>D. have gone</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（went）</strong> —— 笔记补充解析（原题为有提示词填空）：主句 changed 提示一般过去时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ go 是一般现在时：after 引导的时间状语从句时态要与主句 changed（过去时）呼应。干扰点：上大学是长期状态就用现在时。</li><li>B ❌ gone 是过去分词：after 后接从句 I ____ to college 缺谓语，不能填非谓语。</li><li>C ✅ 主句 changed 提示一般过去时，从句用 went（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ have gone 是现在完成时：主从句时态呼应要求过去时，完成时与 changed 无法搭配。</li></ul><p><strong>整句翻译</strong>：上大学后，我和母亲的关系发生了变化。</p><p><strong>词组</strong>：<code>relationship with</code> 与……的关系；<code>go to college</code> 上大学</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 第1段第1句（空1，提示词 go））：My relationship with my mother changed after I ____（go）to college.</p></details><p><strong>【练习三 · 提示词 talk】When I was at home, we argued about many things, for example, wearing makeup and ____ on the phone.</strong></p><ul><li>A. talked</li><li>B. talking</li><li>C. to talk</li><li>D. talks</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（talking）</strong> —— 笔记补充解析（原题为有提示词填空）：与 wearing makeup 并列作 about 的宾语，用动名词。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ talked 是过去式：about 是介词，后面要接名词性成分，不能直接接谓语动词。干扰点：并列的 wearing 让以为要填过去式。</li><li>B ✅ 与 wearing makeup 并列作 about 的宾语，介词后用动名词 → talking（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ to talk 是不定式：about 后不接不定式；且与 wearing 结构不平行。</li><li>D ❌ talks 是第三人称单数谓语：介词后不能接谓语形式。</li></ul><p><strong>整句翻译</strong>：在家的时候，我们会为很多事情争吵，比如化妆和打电话。</p><p><strong>词组</strong>：<code>argue about</code> 为……争吵（about 是介词）；<code>wear makeup</code> 化妆</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 第1段第2句（空2，提示词 talk））：When I was at home, we argued about many things, for example, wearing makeup and ____（talk）on the phone.</p></details><p><strong>【练习三 · 提示词 leave】One time, before a big party, she refused to let me ____ the house.</strong></p><ul><li>A. leaving</li><li>B. leave</li><li>C. left</li><li>D. to leave</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（leave）</strong> —— 笔记补充解析（原题为有提示词填空）：let sb. do sth.。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ leaving 是动名词：let 后不接 doing 作宾补；let sb. doing 结构不成立。干扰点：把 leave 当成介词后动词处理。</li><li>B ✅ let sb. do sth.：使役动词 let 后接省 to 的不定式 → leave（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ left 是过去式/过去分词：let me left 结构不成立。</li><li>D ❌ to leave 多了 to：let 属「三使」之一，主动句中省 to；refuse to let 的 to 属于 refuse，不是 let。</li></ul><p><strong>整句翻译</strong>：有一次，在一个大型聚会前，她不让（ refused to let ）我出门。</p><p><strong>词组</strong>：<code>let sb. do sth.</code> 让某人做某事（使役动词后接省 to 不定式）；<code>refuse to do sth.</code> 拒绝做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-t2:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 第1段第3句（空3，提示词 leave））：One time, before a big party, she refused to let me ____（leave）the house.（let sb. do）</p></details><p><strong>【练习三 · 提示词 I】She thought ____ makeup was too heavy.</strong></p><ul><li>A. me</li><li>B. mine</li><li>C. my</li><li>D. myself</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（my）</strong> —— 笔记补充解析（原题为有提示词填空）：形容词性物主代词修饰 makeup。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ me 是宾格：空格后 makeup 是名词，需要定语，宾格不能修饰名词。干扰点：与主句 I 对应就选宾格。</li><li>B ❌ mine 是名词性物主代词，后面不能再接名词 makeup。</li><li>C ✅ 形容词性物主代词 my 修饰名词 makeup（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ myself 是反身代词：myself makeup 结构不成立；语境也没有「给自己化妆」的强调。</li></ul><p><strong>整句翻译</strong>：她认为我的妆太浓了。</p><p><strong>词组</strong>：<code>makeup</code> 化妆品、妆容（名词）；<code>too heavy</code> 太浓/太重</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 第1段第4句（空4，提示词 I））：She thought ____（I）makeup was too heavy.</p></details><p><strong>【练习三 · 无提示词】I was the only girl ____ makeup, and I was so mad.</strong></p><ul><li>A. with</li><li>B. in</li><li>C. on</li><li>D. without</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（without）</strong> —— 笔记补充解析（原题为无提示词填空）：根据「不得不洗脸」和「很生气」可知，她是唯一没化妆的女孩。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ with makeup 意为「化了妆」：与上文「不得不洗脸」「很生气」的语境矛盾。干扰点：只按「女孩 + 妆容」的常态搭配猜。</li><li>B ❌ in makeup 意为「化了妆（的状态）」，同样与语境矛盾；in 表「穿着/戴着」时后接衣物配饰。</li><li>C ❌ on makeup 不成立；on 与 makeup 无此搭配。</li><li>D ✅ 根据「不得不洗脸」和「很生气」可知，她是唯一没化妆的女孩 → without（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：我是唯一一个没化妆的女孩，我气坏了。</p><p><strong>词组</strong>：<code>the only girl without makeup</code> 唯一没化妆的女孩（without 表「没有」）；<code>wash one&#39;s face</code> 洗脸</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 第1段第5句（空5，无提示词））：I had to wash my face before I went to the party. I was the only girl ____ makeup, and I was so mad.（由上文推出 without）</p></details><p><strong>【练习三 · 提示词 behave】Her ____ always made me upset.</strong></p><ul><li>A. behave</li><li>B. behaved</li><li>C. behavior</li><li>D. behavioral</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（behavior）</strong> —— 笔记补充解析（原题为有提示词填空）：形容词性物主代词 Her 后接名词（behavior/behaviour 均可）。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ behave 是动词：Her 是物主代词，后面要接名词，不能接动词原形。干扰点：提示词照抄。</li><li>B ❌ behaved 是过去式/过去分词：Her behaved 结构不成立。</li><li>C ✅ 形容词性物主代词 Her 后接名词（behavior/behaviour 均可）（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ behavioral 是形容词「行为的」：Her behavioral 后缺名词中心词，与 made me upset 的主语需求不符。</li></ul><p><strong>整句翻译</strong>：她的行为总是让我心烦。</p><p><strong>词组</strong>：<code>behavior/behaviour</code> 行为（名词）；<code>make sb. upset</code> 让某人心烦</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 第1段末句（空6，提示词 behave））：Her ____（behave）always made me upset.</p></details><p><strong>【练习三 · 提示词 me】But after a few months at college, I changed ____ completely.</strong></p><ul><li>A. me</li><li>B. mine</li><li>C. my</li><li>D. myself</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（myself）</strong> —— 笔记补充解析（原题为有提示词填空）：主语和宾语同指一人，用反身代词。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ me 是宾格：「我改变了我」语义不通——改变的对象就是主语自己，必须用反身代词。干扰点：及物动词后接宾格就完事。</li><li>B ❌ mine 是名词性物主代词「我的（东西）」，不能作 change 的宾语。</li><li>C ❌ my 是形容词性物主代词，后面必须接名词。</li><li>D ✅ 主语和宾语同指一人（我改变了我自己），用反身代词 myself（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：但在大学待了几个月后，我完全改变了自己。</p><p><strong>词组</strong>：<code>change oneself</code> 改变自己（主宾同指用反身代词）；<code>after a few months</code> 几个月后</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 第2段第1句（空7，提示词 me））：But after a few months at college, I changed ____（me）completely.</p></details><p><strong>【练习三 · 提示词 patient】I didn’t have the time or ____ for long phone conversations.</strong></p><ul><li>A. patience</li><li>B. patient</li><li>C. patiently</li><li>D. patients</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（patience）</strong> —— 笔记补充解析（原题为有提示词填空）：与 time 并列作 have 的宾语，用名词。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 与 time 并列作 have 的宾语，用名词 patience（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ patient 是形容词/名词「病人」：have the time or patient 结构不成立；此处需要抽象名词。</li><li>C ❌ patiently 是副词：have 后接名词作宾语，不能用副词。</li><li>D ❌ patients 是复数名词「病人们」：与「打电话」的语境完全无关。干扰点：patients 也是名词。</li></ul><p><strong>整句翻译</strong>：我没有时间，也没有耐心打长时间的电话。</p><p><strong>词组</strong>：<code>have the time or patience for</code> 有时间和耐心去做……（for 是介词）；<code>long phone conversations</code> 长时间的电话交谈</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 第2段第4句（空8，提示词 patient））：I didn&#39;t have the time or ____（patient）for long phone conversations.</p></details><p><strong>【练习三 · 提示词 care】I stopped ____ so much about things like makeup.</strong></p><ul><li>A. to care</li><li>B. cared</li><li>C. care</li><li>D. caring</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（caring）</strong> —— 笔记补充解析（原题为有提示词填空）：stop doing sth. 表示停止做某事。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ to care 表「停下来去在意」，与句意「不再在意」相反：stop to do 是停下当前动作去做另一件事。干扰点：记混 stop doing 与 stop to do。</li><li>B ❌ cared 是过去式：stopped cared 结构不成立。</li><li>C ❌ care 原形不能直接跟在 stopped 后。</li><li>D ✅ stop doing sth. 表示停止做某事 → caring（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：我不再那么在意化妆之类的事情。</p><p><strong>词组</strong>：<code>stop doing sth.</code> 停止做某事（doing 是正在做的事）；<code>stop to do sth.</code> 停下来去做另一件事</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 第2段第5句（空9，提示词 care））：I stopped ____（care）so much about things like makeup.（stop doing）</p></details><p><strong>【练习三 · 提示词 close】My new way of thinking brought me ____ to my mother than before.</strong></p><ul><li>A. closer</li><li>B. close</li><li>C. closely</li><li>D. closest</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（closer）</strong> —— 笔记补充解析（原题为有提示词填空）：than before 提示比较级。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ than before 提示比较级 → closer（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ close 是原级：与 than before 冲突，语法不成立。干扰点：「亲近」的常用形态就是 close。</li><li>C ❌ closely 是副词「紧密地」：bring me closely to 语义变成「紧密地带到」，且 close 的比较级考点被跳过。存疑：closely 可作副词，但此处与 than 连用需比较级 more closely，仍不如 closer 贴切。</li><li>D ❌ closest 是最高级：句中无 in/of/among 等范围标志，只有 than 的比较对象。</li></ul><p><strong>整句翻译</strong>：我新的思维方式让我和母亲比以前更亲近了。</p><p><strong>词组</strong>：<code>bring sb. close to sb.</code> 使某人与某人亲近；<code>than before</code> 比以前（比较级标志）</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习三 · 第2段末句（空10，提示词 close））：My new way of thinking brought me ____（close）to my mother than before.</p></details><h3 id="练习四-·-儿童身体形象焦虑-题海-p6-7" tabindex="-1"><a class="header-anchor" href="#练习四-·-儿童身体形象焦虑-题海-p6-7"><span>练习四 · 儿童身体形象焦虑（题海 P6-7）</span></a></h3><p>A survey of English schoolchildren shows boys and girls are worrying <strong>1. ______</strong> the way they look. The study found that over half of male schoolchildren <strong>2. ______</strong>（lack）confidence because <strong>3. ______</strong> their body shape. The figure for girls was slightly higher, at 59 percent. Researchers <strong>4. ______</strong>（question）693 teachers about how their students felt about their bodies. All the children had taken lessons on body image and self-esteem. Teachers said many children were very <strong>5. ______</strong>（anger）if others said bad things about their appearances. Around 55 percent of teachers reported that girls were <strong>6. ______</strong>（extreme）sensitive to comments about their looks; the figure for boys being easily hurt by teasing（取笑）was 27 percent.</p><p>Teachers gave a number of <strong>7. ______</strong>（reason）why children as young as four years old were stressing out about their shapes. Over 90 percent of teachers blame the Internet and television. Children see images of “perfect” bodies every day and they feel they have to look that way too. Many children are on diets to make themselves <strong>8. ______</strong>（attract）to the opposite sex. One elementary school teacher said: “I work with four- to five-year-olds and some say things like, ‘I can&#39;t eat cheese; it will make <strong>9. ______</strong>（I）fat.’” A teachers&#39; spokeswoman warned that children <strong>10. ______</strong>（try）to look like “celebrities in the media only lead to misery”.</p><p><strong>【练习四 · 无提示词】A survey of English schoolchildren shows boys and girls are worrying ____ the way they look.</strong></p><ul><li>A. about</li><li>B. of</li><li>C. for</li><li>D. on</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（about）</strong> —— 笔记补充解析（原题为无提示词填空）：固定搭配 worry about。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 固定搭配 worry about（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ worry of 不成立；of 与 worry 无此搭配。</li><li>C ❌ worry for 意为「为……担心」时不接外貌这类事物；for 与 worry 的常见搭配是 worry for sb.（较少用），且不接 the way。</li><li>D ❌ worry on 不成立。</li></ul><p><strong>整句翻译</strong>：一项对英国学童的调查显示，男孩和女孩都在担心自己的外貌。</p><p><strong>词组</strong>：<code>worry about</code> 担心……（固定搭配）；<code>the way they look</code> 他们看起来的样子</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 第1段第1句（空1，无提示词））：A survey of English schoolchildren shows boys and girls are worrying ____ the way they look.（worry about）</p></details><p><strong>【练习四 · 提示词 lack】The study found that over half of male schoolchildren ____ confidence because of their body shape.</strong></p><ul><li>A. lack</li><li>B. lacking</li><li>C. have lacked</li><li>D. lacked</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（lacked）</strong> —— 笔记补充解析（原题为有提示词填空）：调查结果发生在过去，与 found 一致。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ lack 是一般现在时：研究结果是过去发现的（The study found），宾语从句叙述该研究的结论，时态应与 found 呼应为过去。干扰点：结论是普遍事实就用现在时。</li><li>B ❌ lacking 是非谓语：从句主语 over half of male schoolchildren 后缺谓语。</li><li>C ❌ have lacked 是现在完成时：与主句 found 的过去时无法呼应，且无持续到现在的时间提示。</li><li>D ✅ 调查结果发生在过去，与 found 一致 → 一般过去时 lacked（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：研究发现，超过一半的男生因为体型而缺乏自信。</p><p><strong>词组</strong>：<code>lack confidence</code> 缺乏自信；<code>body shape</code> 体型</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 第1段第2句（空2，提示词 lack））：The study found that over half of male schoolchildren ____（lack）confidence because of their body shape.</p></details><p><strong>【练习四 · 无提示词】The study found that over half of male schoolchildren lacked confidence ____ their body shape.</strong></p><ul><li>A. because of</li><li>B. because</li><li>C. for</li><li>D. as</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（because of）</strong> —— 笔记补充解析（原题为无提示词填空）：固定搭配 because of + 名词；because 后接从句。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 固定搭配 because of + 名词：空后 their body shape 是名词短语（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ because 是连词，后面要接完整从句；their body shape 只是名词短语，缺主谓。干扰点：中文都是「因为」，忘了 because of 与 because 的分工。</li><li>C ❌ for 可表原因但后面接从句或具体目的；for their body shape 表「为了体型」，语义不通。</li><li>D ❌ as 作「因为」时是连词，后面同样要接从句，不能接名词短语。</li></ul><p><strong>整句翻译</strong>：研究发现，超过一半的男生因为他们的体型而缺乏自信。</p><p><strong>词组</strong>：<code>because of + 名词</code> 因为……（of 后接名词性成分）；<code>because + 从句</code> 因为……（后接完整句子）</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 第1段第2句（空3，无提示词））：The study found that over half of male schoolchildren lacked confidence ____ their body shape.（because of + 名词）</p></details><p><strong>【练习四 · 提示词 question】Researchers ____ 693 teachers about how their students felt about their bodies.</strong></p><ul><li>A. questioning</li><li>B. questioned</li><li>C. questions</li><li>D. have questioned</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（questioned）</strong> —— 笔记补充解析（原题为有提示词填空）：调查行为发生在过去。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ questioning 是非谓语：Researchers 后缺谓语动词，从句 how their students felt 是过去时，主句也要用过去时谓语。</li><li>B ✅ 调查行为发生在过去，与全文 found/felt 一致 → 一般过去时 questioned（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ questions 是一般现在时：与从句 felt 的过去时冲突。干扰点：研究结论当作普遍事实。</li><li>D ❌ have questioned 是现在完成时：没有持续到现在的语境提示，且与 felt 不呼应。</li></ul><p><strong>整句翻译</strong>：研究人员询问了 693 名教师，了解他们的学生对自己身体的看法。</p><p><strong>词组</strong>：<code>question sb. about</code> 就……询问某人；<code>feel about</code> 对……的感受</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 第1段第4句（空4，提示词 question））：Researchers ____（question）693 teachers about how their students felt about their bodies.</p></details><p><strong>【练习四 · 提示词 anger】Teachers said many children were very ____ if others said bad things about their appearances.</strong></p><ul><li>A. anger</li><li>B. angrily</li><li>C. angry</li><li>D. angered</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（angry）</strong> —— 笔记补充解析（原题为有提示词填空）：系动词 were 后用形容词作表语。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ anger 是名词：were very anger 结构不成立，very 修饰形容词而非名词。干扰点：提示词照抄。</li><li>B ❌ angrily 是副词：系动词 were 后接形容词作表语，不接副词。</li><li>C ✅ 系动词 were 后用形容词作表语 → angry（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ angered 是过去分词「被激怒的」：were angered 语法可通，但 very 不修饰过去分词；且提示词是名词 anger，需转形容词 angry。</li></ul><p><strong>整句翻译</strong>：教师们说，如果别人说他们的外貌不好，许多孩子会非常生气。</p><p><strong>词组</strong>：<code>be angry</code> 生气（系动词 + 形容词）；<code>say bad things about</code> 说……的坏话</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 第1段第5句（空5，提示词 anger））：Teachers said many children were very ____（anger）if others said bad things about their appearances.</p></details><p><strong>【练习四 · 提示词 extreme】Around 55 percent of teachers reported that girls were ____ sensitive to comments about their looks.</strong></p><ul><li>A. extreme</li><li>B. extremeness</li><li>C. more extreme</li><li>D. extremely</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（extremely）</strong> —— 笔记补充解析（原题为有提示词填空）：副词修饰形容词 sensitive。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ extreme 是形容词，不能修饰形容词 sensitive。干扰点：提示词照抄。</li><li>B ❌ extremeness 是名词「极端」，不能修饰形容词。</li><li>C ❌ more extreme 是比较级形容词：句中没有比较对象，且词性仍是形容词，修饰不了 sensitive。</li><li>D ✅ 副词修饰形容词 sensitive → extremely（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：约 55% 的教师报告说，女孩对关于外貌的评论极其敏感。</p><p><strong>词组</strong>：<code>be sensitive to</code> 对……敏感；<code>extremely</code> 极其（副词修饰形容词）</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 第1段末句（空6，提示词 extreme））：Around 55 percent of teachers reported that girls were ____（extreme）sensitive to comments about their looks.</p></details><p><strong>【练习四 · 提示词 reason】Teachers gave a number of ____ why children as young as four years old were stressing out about their shapes.</strong></p><ul><li>A. reason</li><li>B. reason’s</li><li>C. reasons</li><li>D. reasoning</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（reasons）</strong> —— 笔记补充解析（原题为有提示词填空）：a number of 后接可数名词复数。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ reason 单数：a number of 后必须接可数名词复数。</li><li>B ❌ reason&#39;s 是所有格「理由的」，后面要接名词，而空后是 why 从句。</li><li>C ✅ a number of 后接可数名词复数 reasons（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ reasoning 是动名词「推理」：gave a number of reasoning 语义变成「给出许多推理」，与「解释焦虑原因」的语境不符。</li></ul><p><strong>整句翻译</strong>：教师们给出了不少理由，解释为什么连四岁的孩子都为自己的体型焦虑。</p><p><strong>词组</strong>：<code>a number of + 复数</code> 许多的……（后接可数名词复数）；<code>stress out about</code> 对……焦虑不安</p><p><strong>对比自测</strong>：做完后对照 quiz-t1:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 第2段第1句（空7，提示词 reason））：Teachers gave a number of ____（reason）why children as young as four years old were stressing out about their shapes.</p></details><p><strong>【练习四 · 提示词 attract】Many children are on diets to make themselves ____ to the opposite sex.</strong></p><ul><li>A. attract</li><li>B. attractively</li><li>C. attractive</li><li>D. attraction</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（attractive）</strong> —— 笔记补充解析（原题为有提示词填空）：make + 宾语 + 形容词 结构。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ attract 是动词：make themselves attract 结构不成立；make + 宾语 + 形容词才表示「使……变得……」。</li><li>B ❌ attractively 是副词：make + 宾语 + 副词不成立，此处需要宾语补足语性质的形容词。</li><li>C ✅ make + 宾语 + 形容词结构：attract 转成形容词 attractive（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ attraction 是名词「吸引力」：make themselves attraction to 结构不成立。</li></ul><p><strong>整句翻译</strong>：许多孩子节食，是为了让自己对异性有吸引力。</p><p><strong>词组</strong>：<code>be on a diet</code> 在节食；<code>make oneself attractive to</code> 使自己吸引……（make + 宾语 + 形容词）</p><p><strong>对比自测</strong>：做完后对照 quiz-t1:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 第2段第3句（空8，提示词 attract））：Many children are on diets to make themselves ____（attract）to the opposite sex.（make + 宾 + adj.）</p></details><p><strong>【练习四 · 提示词 I】“I work with four- to five-year-olds and some say things like, ‘I can’t eat cheese; it will make ____ fat.’”</strong></p><ul><li>A. I</li><li>B. me</li><li>C. my</li><li>D. mine</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（me）</strong> —— 笔记补充解析（原题为有提示词填空）：人称代词宾格作 make 的宾语。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ I 是主格：make 后接宾语要用宾格。干扰点：直接引语里保持说话人的「我」就用主格。</li><li>B ✅ 人称代词宾格作 make 的宾语 → me（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ my 是形容词性物主代词，后面必须接名词；空后是形容词 fat。</li><li>D ❌ mine 是名词性物主代词，不能作 make 的宾语。</li></ul><p><strong>整句翻译</strong>：「我不能吃奶酪，它会让我发胖。」</p><p><strong>词组</strong>：<code>make sb. + adj.</code> 使某人怎么样（sb. 用宾格）；<code>fat</code> 胖的</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 第2段第4句（空9，提示词 I））：“I can&#39;t eat cheese; it will make ____（I）fat.”（make 后接宾格）</p></details><p><strong>【练习四 · 提示词 try】A teachers’ spokeswoman warned that children ____ to look like “celebrities in the media only lead to misery”.</strong></p><ul><li>A. tried</li><li>B. trying</li><li>C. to try</li><li>D. try</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（trying）</strong> —— 笔记补充解析（原题为有提示词填空）：现在分词短语修饰 children；主干为 children...lead to misery。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ tried 是过去式：children tried to look like... 会让 lead 变成无谓语修饰的裸动词，句子结构崩塌（that 从句里只有一套谓语 lead，try 不能再作谓语）。</li><li>B ✅ 现在分词短语 trying to look like... 修饰 children；从句主干为 children...lead to misery（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ to try 是不定式：children to try...lead 结构不成立，且不定式作定语多表将来，与「一直在模仿」的语境不符。</li><li>D ❌ try 是原形：children try...lead 出现两个动词原形无谓语连接，语法不成立。干扰点：warned that 从句里以为可以再有一套主谓。</li></ul><p><strong>整句翻译</strong>：一位教师发言人警告说，孩子们试图模仿「媒体上的名人只会导致痛苦」。</p><p><strong>词组</strong>：<code>try to do sth.</code> 试图做某事；<code>lead to misery</code> 导致痛苦</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习四 · 第2段末句（空10，提示词 try））：A teachers&#39; spokeswoman warned that children ____（try）to look like “celebrities in the media only lead to misery”.（现在分词修饰 children，主干 children lead to misery）</p></details><h3 id="练习五-·-保护雨林-题海-p7" tabindex="-1"><a class="header-anchor" href="#练习五-·-保护雨林-题海-p7"><span>练习五 · 保护雨林（题海 P7）</span></a></h3><p>Today I&#39;m going to talk about rainforests. Are you familiar <strong>1. ______</strong> them? They&#39;re interesting and <strong>2. ______</strong>（excite）places! Many kinds of the world&#39;s plants and animals live in the rainforests.</p><p>However, rainforests <strong>3. ______</strong>（be）in trouble now — they are disappearing very fast because they are cut down or burnt every day. <strong>4. ______</strong> a result, various animals and plants are dying out.</p><p>Maybe you have never been to a rainforest, so why should you <strong>5. ______</strong>（protect）them with care? Rainforests are <strong>6. ______</strong>（importance）to everyone because the plants in the rainforests make oxygen. We need oxygen to breathe.</p><p>Rainforests also help to control the weather. When trees are cut down, it gets <strong>7. ______</strong>（hot）than before. Besides, one quarter of our medicines come from plants. Many of these plants can be <strong>8. ______</strong>（find）only in rainforests. There is a lot that we have not learnt about rainforests. If we destroy them, we will never find out.</p><p>In my opinion, our future depends <strong>9. ______</strong> saving the rainforests. We must tell more people how important rainforests are so that they will stop doing harm to them. We must protect the rainforests now. We must take <strong>10. ______</strong>（act）to protect the rainforests now.</p><p><strong>【练习五 · 无提示词】Today I’m going to talk about rainforests. Are you familiar ____ them?</strong></p><ul><li>A. to</li><li>B. of</li><li>C. at</li><li>D. with</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（with）</strong> —— 笔记补充解析（原题为无提示词填空）：固定搭配 be familiar with。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ be familiar to 意为「为……所熟悉」，主语应是事物（The topic is familiar to me）；本句主语是 you（人），「你熟悉它们」要用 with。</li><li>B ❌ familiar of 不成立。</li><li>C ❌ familiar at 不成立；at 不与 familiar 搭配。</li><li>D ✅ 固定搭配 be familiar with：人作主语「熟悉某物」（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：今天我要讲雨林。你们熟悉它们吗？</p><p><strong>词组</strong>：<code>be familiar with</code> 熟悉……（人作主语时用 with）；<code>talk about</code> 谈论</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 第1段第2句（空1，无提示词））：Are you familiar ____ them?（be familiar with）</p></details><p><strong>【练习五 · 提示词 excite】They’re interesting and ____ places!</strong></p><ul><li>A. exciting</li><li>B. excited</li><li>C. excitedly</li><li>D. excitement</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（exciting）</strong> —— 笔记补充解析（原题为有提示词填空）：修饰事物 places，表示「令人兴奋的」。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 修饰事物 places，表示「令人兴奋的」→ exciting（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ excited 修饰「感到兴奋的人」：places 是事物，主被动关系不对。干扰点：-ed/-ing 分工记反。</li><li>C ❌ excitedly 是副词：名词前作定语要用形容词。</li><li>D ❌ excitement 是名词：and 连接 interesting（形容词）与 excitement（名词）不平行。</li></ul><p><strong>整句翻译</strong>：它们（雨林）是有趣又令人兴奋的地方！</p><p><strong>词组</strong>：<code>exciting places</code> 令人兴奋的地方（-ing 修饰事物）；<code>and 连接并列形容词</code> interesting and exciting 并列作定语</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 第1段第3句（空2，提示词 excite））：They&#39;re interesting and ____（excite）places!（修饰事物用 -ing）</p></details><p><strong>【练习五 · 提示词 be】However, rainforests ____ in trouble now — they are disappearing very fast because they are cut down or burnt every day.</strong></p><ul><li>A. are</li><li>B. is</li><li>C. was</li><li>D. be</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（are）</strong> —— 笔记补充解析（原题为有提示词填空）：主语 rainforests 为复数，且 now 表示当前状态。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 主语 rainforests 为复数，且 now 表示当前状态 → are（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ is 是单数：与复数主语 rainforests 不一致。干扰点：把 rainforests 当作一个整体概念。</li><li>C ❌ was 是过去时：now 表示当前状态，且后文 are disappearing 是现在时。</li><li>D ❌ be 是原形：前面无情态动词或助动词，不能直接接原形。</li></ul><p><strong>整句翻译</strong>：然而，雨林现在正处于困境——它们正在消失，因为每天都被砍伐或焚烧。</p><p><strong>词组</strong>：<code>be in trouble</code> 处于困境中；<code>disappear</code> 消失</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 第2段第1句（空3，提示词 be））：However, rainforests ____（be）in trouble now — they are disappearing very fast...</p></details><p><strong>【练习五 · 无提示词】____ a result, various animals and plants are dying out.</strong></p><ul><li>A. In</li><li>B. For</li><li>C. At</li><li>D. As</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（As）</strong> —— 笔记补充解析（原题为无提示词填空）：固定搭配 as a result，位于句首首字母大写。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ In a result 不成立；in 与 result 的固定搭配是 as a result / in result of（少用）。</li><li>B ❌ For a result 不成立。</li><li>C ❌ At a result 不成立。</li><li>D ✅ 固定搭配 as a result，位于句首首字母大写 → As（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：结果，各种各样的动物和植物正在灭绝。</p><p><strong>词组</strong>：<code>as a result</code> 结果、因此（固定短语，句首 As 大写）；<code>die out</code> 灭绝</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 第2段第2句（空4，无提示词））：____ a result, various animals and plants are dying out.（As a result）</p></details><p><strong>【练习五 · 提示词 protect】Maybe you have never been to a rainforest, so why should you ____ them with care?</strong></p><ul><li>A. protecting</li><li>B. to protect</li><li>C. protect</li><li>D. protected</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（protect）</strong> —— 笔记补充解析（原题为有提示词填空）：情态动词 should 后接动词原形。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ protecting 是动名词：should 后必须接动词原形。干扰点：看到 protect them 就想到 doing。</li><li>B ❌ to protect 是不定式：should 后不接 to do（to 属于情态动词后的错误添加）。</li><li>C ✅ 情态动词 should 后接动词原形 → protect（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ protected 是过去式/过去分词：should protected 结构不成立。</li></ul><p><strong>整句翻译</strong>：也许你从未去过雨林，那么为什么你应该小心保护它们呢？</p><p><strong>词组</strong>：<code>with care</code> 小心地；<code>情态动词 + 动词原形</code> should 后接动词原形</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 第3段第1句（空5，提示词 protect））：Maybe you have never been to a rainforest, so why should you ____（protect）them with care?</p></details><p><strong>【练习五 · 提示词 importance】Rainforests are ____ to everyone because the plants in the rainforests make oxygen.</strong></p><ul><li>A. importance</li><li>B. importantly</li><li>C. important</li><li>D. more important</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（important）</strong> —— 笔记补充解析（原题为有提示词填空）：系动词 are 后用形容词。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ importance 是名词：are importance 结构不成立；系动词后接形容词。</li><li>B ❌ importantly 是副词：are 是系动词，后接形容词作表语，不接副词。</li><li>C ✅ 系动词 are 后用形容词 important（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ more important 是比较级：句中没有 than 或比较语境；本句陈述一般事实用原级。</li></ul><p><strong>整句翻译</strong>：雨林对每个人都很重要，因为雨林里的植物制造氧气。</p><p><strong>词组</strong>：<code>be important to sb.</code> 对某人重要（系动词 + 形容词）；<code>make oxygen</code> 制造氧气</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 第3段第2句（空6，提示词 importance））：Rainforests are ____（importance）to everyone because the plants in the rainforests make oxygen.</p></details><p><strong>【练习五 · 提示词 hot】When trees are cut down, it gets ____ than before.</strong></p><ul><li>A. hot</li><li>B. hotter</li><li>C. hotly</li><li>D. hottest</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（hotter）</strong> —— 笔记补充解析（原题为有提示词填空）：than before 提示比较级，hot 双写 t。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ hot 是原级：与 than before 冲突。</li><li>B ✅ than before 提示比较级；hot 双写 t 再加 -er → hotter（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ hotly 是副词「激烈地」：gets 后接形容词作表语，且与 than 不搭配。</li><li>D ❌ hottest 是最高级：句中没有 in/of/among 等范围标志，只有 than 的比较结构。</li></ul><p><strong>整句翻译</strong>：当树木被砍伐后，天气变得比以前更热。</p><p><strong>词组</strong>：<code>than before</code> 比以前（比较级标志）；<code>get hotter</code> 变得更热（get + 比较级）</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 第4段第2句（空7，提示词 hot））：When trees are cut down, it gets ____（hot）than before.</p></details><p><strong>【练习五 · 提示词 find】Many of these plants can be ____ only in rainforests.</strong></p><ul><li>A. found</li><li>B. finding</li><li>C. to find</li><li>D. founded</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（found）</strong> —— 笔记补充解析（原题为有提示词填空）：与 can be 构成被动语态。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 与 can be 构成被动语态：植物「被找到」→ found（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ finding 与 can be 构成进行式「正在被找」：主语 plants 是被找的对象，且「can be finding」语态不通。</li><li>C ❌ to find 是不定式：can be to find 结构不成立。</li><li>D ❌ founded 是 found（创立）的过去式「建立」：本句 find（找到）的过去分词是 found，但 founded 意为「被建立」，语义不通。干扰点：found 的两种词义混淆。</li></ul><p><strong>整句翻译</strong>：这些植物中的许多只能在雨林中找到。</p><p><strong>词组</strong>：<code>can be found</code> 能被找到（情态动词 + 被动）；<code>only</code> 仅仅</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 第4段第3句（空8，提示词 find））：Many of these plants can be ____（find）only in rainforests.</p></details><p><strong>【练习五 · 无提示词】In my opinion, our future depends ____ saving the rainforests.</strong></p><ul><li>A. in</li><li>B. on</li><li>C. at</li><li>D. for</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（on）</strong> —— 笔记补充解析（原题为无提示词填空）：固定搭配 depend on doing sth.。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ depend in 不成立。</li><li>B ✅ 固定搭配 depend on doing sth.（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ depend at 不成立。</li><li>D ❌ depend for 意为「依靠……获得」，语义与结构都不合（depend for sth. 后不接 doing）。</li></ul><p><strong>整句翻译</strong>：在我看来，我们的未来取决于拯救雨林。</p><p><strong>词组</strong>：<code>depend on</code> 取决于、依靠（固定搭配，后接名词或 doing）；<code>in my opinion</code> 在我看来</p><p><strong>对比自测</strong>：做完后对照 quiz-t2:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 第5段第1句（空9，无提示词））：In my opinion, our future depends ____ saving the rainforests.（depend on）</p></details><p><strong>【练习五 · 提示词 act】We must take ____ to protect the rainforests now.</strong></p><ul><li>A. acting</li><li>B. action</li><li>C. active</li><li>D. actively</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（action）</strong> —— 笔记补充解析（原题为有提示词填空）：固定搭配 take action to do sth.。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ acting 是动名词：take acting 结构不成立；take 后接名词作宾语。</li><li>B ✅ 固定搭配 take action to do sth. → action（名词）（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ active 是形容词「积极的」：take active 后缺名词，不能直接接 to protect。</li><li>D ❌ actively 是副词：take 后需要名词宾语，不能用副词。</li></ul><p><strong>整句翻译</strong>：我们必须立即采取行动保护雨林。</p><p><strong>词组</strong>：<code>take action to do sth.</code> 采取行动做某事（action 是名词）；<code>do harm to</code> 对……有害</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习五 · 第5段末句（空10，提示词 act））：We must take ____（act）to protect the rainforests now.（take action）</p></details><h3 id="练习六-·-海洋污染调查-题海-p8" tabindex="-1"><a class="header-anchor" href="#练习六-·-海洋污染调查-题海-p8"><span>练习六 · 海洋污染调查（题海 P8）</span></a></h3><p>The scientist was in <strong>1. ______</strong> hurry. She had to get some water for her experiment before <strong>2. ______</strong>（dark）fell. She was testing the water in the rivers that went into the ocean. Her job was to find out the cause of <strong>3. ______</strong>（pollute）in the sea at nearby beaches. She lifted out the water and looked <strong>4. ______</strong>（angry）at the rubbish in it. Old clothes, plastic bags and pieces of paper <strong>5. ______</strong>（be）in the dirty water. “Don&#39;t people realize that everything they throw onto the street gets washed into rivers? And they lead right into the ocean!” she said loudly. “How many years will it take to make it clean again?”</p><p>The scientist felt sad deep in her heart. She worried <strong>6. ______</strong> the ocean animals as she walked back to the beach. But when she got there, a group of students and teachers from a local primary school were carrying bags of rubbish to the bins. They had spent their afternoon <strong>7. ______</strong>（clean）the beach! She was filled with joy.</p><p>As she <strong>8. ______</strong>（speak）with the teacher, the students gathered around them. With bright smiles on their faces, they shouted, “We must do something to protect the ocean!”</p><p>“That&#39;s <strong>9. ______</strong>（exact）right,” agreed the scientist, as she smiled at their <strong>10. ______</strong>（kind）.</p><p><strong>【练习六 · 无提示词】The scientist was in ____ hurry.</strong></p><ul><li>A. an</li><li>B. the</li><li>C. one</li><li>D. a</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（a）</strong> —— 笔记补充解析（原题为无提示词填空）：固定搭配 in a hurry。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ in an hurry 错误：hurry 以辅音音素 /h/ 开头，应用 a。干扰点：把不定冠词的选择套到了固定短语上。</li><li>B ❌ in the hurry 中的 the 使短语失去「匆忙」这一惯用含义；in the hurry 不是固定搭配。</li><li>C ❌ in one hurry 不成立；one 不能替代冠词进入固定短语。</li><li>D ✅ 固定搭配 in a hurry（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：这位科学家赶时间。</p><p><strong>词组</strong>：<code>in a hurry</code> 匆忙地、赶时间（固定短语）；<code>experiment</code> 实验</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 第1段第1句（空1，无提示词））：The scientist was in ____ hurry.（in a hurry）</p></details><p><strong>【练习六 · 提示词 dark】She had to get some water for her experiment before ____ fell.</strong></p><ul><li>A. dark</li><li>B. darkness</li><li>C. darker</li><li>D. darkly</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（darkness）</strong> —— 笔记补充解析（原题为有提示词填空）：从句缺主语，名词 darkness 表示「黑暗降临」。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ dark 是形容词：before 后接从句需要主语，形容词不能作主语。干扰点：「天黑」的常用词就是 dark。</li><li>B ✅ 从句缺主语，名词 darkness 表示「黑暗降临」（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ darker 是比较级形容词：同样不能作主语，且句中没有比较对象。</li><li>D ❌ darkly 是副词「阴沉地」：副词不能作从句主语。</li></ul><p><strong>整句翻译</strong>：她必须在天黑前取些实验用水。</p><p><strong>词组</strong>：<code>before darkness fell</code> 在天黑之前（darkness 名词作主语，fell 是 fall 的过去式）；<code>get some water</code> 取水</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 第1段第2句（空2，提示词 dark））：She had to get some water for her experiment before ____（dark）fell.</p></details><p><strong>【练习六 · 提示词 pollute】Her job was to find out the cause of ____ in the sea at nearby beaches.</strong></p><ul><li>A. polluted</li><li>B. polluting</li><li>C. pollution</li><li>D. pollutant</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（pollution）</strong> —— 笔记补充解析（原题为有提示词填空）：介词 of 后用名词。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ polluted 是过去分词「被污染的」：the cause of polluted 后缺名词中心词，不能作 of 的宾语。</li><li>B ❌ polluting 是动名词：the cause of polluting 语义变成「（主动）污染的原因」，但这里指海水「被污染」这一状况，名词 pollution 更准确。</li><li>C ✅ 介词 of 后用名词 → pollution（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ pollutant 是「污染物」：the cause of pollutant 语义变成「污染物的原因」，与「海水污染」的语境不符。</li></ul><p><strong>整句翻译</strong>：她的工作是查明附近海滩海水污染的原因。</p><p><strong>词组</strong>：<code>find out the cause of</code> 查明……的原因；<code>pollution</code> 污染（名词）</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 第1段第3句（空3，提示词 pollute））：Her job was to find out the cause of ____（pollute）in the sea at nearby beaches.</p></details><p><strong>【练习六 · 提示词 angry】She lifted out the water and looked ____ at the rubbish in it.</strong></p><ul><li>A. angrily</li><li>B. angry</li><li>C. anger</li><li>D. more angry</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（angrily）</strong> —— 笔记补充解析（原题为有提示词填空）：副词修饰动词 looked，表示生气地看。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 副词修饰动词 looked，表示生气地看 → angrily（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ angry 是形容词：looked angry 意为「看起来生气」描述状态，但此处要表达「带着怒气看」这一动作方式，用副词。存疑：look 作系动词时 looked angry 成立，本题按动作方式取 angrily。</li><li>C ❌ anger 是名词：looked anger 结构不成立。</li><li>D ❌ more angry 是比较级：句中没有比较对象。</li></ul><p><strong>整句翻译</strong>：她舀起水，生气地看着里面的垃圾。</p><p><strong>词组</strong>：<code>lift out</code> 舀出、提起；<code>look angrily at</code> 生气地看着（副词修饰动词）</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 第1段第4句（空4，提示词 angry））：She lifted out the water and looked ____（angry）at the rubbish in it.</p></details><p><strong>【练习六 · 提示词 be】Old clothes, plastic bags and pieces of paper ____ in the dirty water.</strong></p><ul><li>A. was</li><li>B. are</li><li>C. be</li><li>D. were</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（were）</strong> —— 笔记补充解析（原题为有提示词填空）：并列复数主语，叙述过去场景。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ was 是单数：and 连接多个并列主语，谓语用复数。</li><li>B ❌ are 是现在时：全文叙述过去的场景（was, had to, lifted）。</li><li>C ❌ be 是原形：前面无 情态动词或助动词，不能接原形。</li><li>D ✅ 并列复数主语，叙述过去场景 → were（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：旧衣服、塑料袋和纸片都在脏水里。</p><p><strong>词组</strong>：<code>Old clothes, plastic bags and pieces of paper</code> 旧衣服、塑料袋和纸片（并列复数主语）；<code>dirty water</code> 脏水</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 第1段第5句（空5，提示词 be））：Old clothes, plastic bags and pieces of paper ____（be）in the dirty water.</p></details><p><strong>【练习六 · 无提示词】She worried ____ the ocean animals as she walked back to the beach.</strong></p><ul><li>A. about</li><li>B. of</li><li>C. for</li><li>D. at</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（about）</strong> —— 笔记补充解析（原题为无提示词填空）：固定搭配 worry about。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 固定搭配 worry about（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ worry of 不成立。</li><li>C ❌ worry for 不常用且不接动物这类对象；表「担心某人」多用 worry about。</li><li>D ❌ worry at 意为「苦思、咬啮」，不表「担心」。</li></ul><p><strong>整句翻译</strong>：她走回海滩时，担心着海洋动物。</p><p><strong>词组</strong>：<code>worry about</code> 担心……（固定搭配）；<code>walk back to</code> 走回</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 第2段第2句（空6，无提示词））：She worried ____ the ocean animals as she walked back to the beach.（worry about）</p></details><p><strong>【练习六 · 提示词 clean】They had spent their afternoon ____ the beach!</strong></p><ul><li>A. cleaned</li><li>B. to clean</li><li>C. clean</li><li>D. cleaning</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（cleaning）</strong> —— 笔记补充解析（原题为有提示词填空）：固定搭配 spend time doing sth.。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ cleaned 是过去式/过去分词：spent their afternoon cleaned 结构不成立。</li><li>B ❌ to clean 是不定式：spend 后不接 to do。干扰点：「花时间去做」就想到 to do。</li><li>C ❌ clean 原形不能跟在 their afternoon 后作 spend 的补足成分。</li><li>D ✅ 固定搭配 spend time doing sth. → cleaning（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：他们整个下午都在清理海滩！</p><p><strong>词组</strong>：<code>spend time doing sth.</code> 花费时间做某事（spend 后接动名词）；<code>clean the beach</code> 清理海滩</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 第2段第3句（空7，提示词 clean））：They had spent their afternoon ____（clean）the beach!（spend time doing）</p></details><p><strong>【练习六 · 提示词 speak】As she ____ with the teacher, the students gathered around them.</strong></p><ul><li>A. spoke</li><li>B. was speaking</li><li>C. speaks</li><li>D. had spoken</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（was speaking）</strong> —— 笔记补充解析（原题为有提示词填空）：as 表示两个过去动作同时进行，持续动作使用过去进行时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ spoke 是一般过去时：as 表示两个过去动作同时进行，持续动作（交谈）应用过去进行时，spoke 读不出「正在进行」。</li><li>B ✅ as 表示两个过去动作同时进行，持续动作使用过去进行时 → was speaking（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ speaks 是现在时：与全文过去时基调冲突。</li><li>D ❌ had spoken 是过去完成时：「先说完了话，学生才围拢」与 as「同时」的含义矛盾。</li></ul><p><strong>整句翻译</strong>：当她正与老师交谈时，学生们围拢过来。</p><p><strong>词组</strong>：<code>as 引导时间状语从句</code> 当……时（常接持续性动作）；<code>gather around</code> 围拢</p><p><strong>对比自测</strong>：做完后对照 quiz-t1:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 第3段第1句（空8，提示词 speak））：As she ____（speak）with the teacher, the students gathered around them.（as + 过去进行时）</p></details><p><strong>【练习六 · 提示词 exact】“That’s ____ right,” agreed the scientist, as she smiled at their kindness.</strong></p><ul><li>A. exact</li><li>B. exactness</li><li>C. exactly</li><li>D. more exact</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（exactly）</strong> —— 笔记补充解析（原题为有提示词填空）：副词修饰形容词 right。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ exact 是形容词：不能直接修饰形容词 right。干扰点：提示词照抄。</li><li>B ❌ exactness 是名词「精确性」，不能修饰形容词。</li><li>C ✅ 副词修饰形容词 right → exactly（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ more exact 是比较级：句中没有比较对象，且词性仍是形容词。</li></ul><p><strong>整句翻译</strong>：「完全正确。」科学家赞同道，对他们的善意微笑。</p><p><strong>词组</strong>：<code>exactly right</code> 完全正确（副词修饰形容词）；<code>agree</code> 赞同</p><p><strong>对比自测</strong>：做完后对照 quiz-t1:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 第4段（空9，提示词 exact））：“That&#39;s ____（exact）right,” agreed the scientist...</p></details><p><strong>【练习六 · 提示词 kind】“That’s exactly right,” agreed the scientist, as she smiled at their ____.</strong></p><ul><li>A. kindness</li><li>B. kind</li><li>C. kindly</li><li>D. kinds</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（kindness）</strong> —— 笔记补充解析（原题为有提示词填空）：物主代词 their 后用名词。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 物主代词 their 后用名词 → kindness（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ kind 是形容词：their kind 后缺名词，不能作 smiled at 的宾语。</li><li>C ❌ kindly 是副词「亲切地」：smiled at their kindly 结构不成立。</li><li>D ❌ kinds 是复数「种类」：与「善意」的语境不符。</li></ul><p><strong>整句翻译</strong>：「完全正确。」科学家赞同道，对他们的善意微笑。</p><p><strong>词组</strong>：<code>smile at one&#39;s kindness</code> 对某人的善意微笑；<code>their kindness</code> 他们的善意（物主代词 + 名词）</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习六 · 第4段（空10，提示词 kind））：...as she smiled at their ____（kind）.</p></details><h3 id="练习七-·-午休与健康-题海-p8-9" tabindex="-1"><a class="header-anchor" href="#练习七-·-午休与健康-题海-p8-9"><span>练习七 · 午休与健康（题海 P8-9）</span></a></h3><p>A new study shows that too many people are working through their lunch hour. Not taking a proper lunch break is <strong>1. ______</strong>（healthy）. It can <strong>2. ______</strong>（made）people sick, so then they need time off work. The study is from the Chartered Society of Physiotherapy（CSP）in the U.K. It interviewed over 2,000 people about <strong>3. ______</strong> they do for lunch at work. Twenty per cent of the workers said they did not take a lunch break. They worked through their lunch hour. Half of the people took a break but ate their lunch at their desk and <strong>4. ______</strong>（surf）the Internet, answered e-mails or went on Facebook. One in five people left the workplace <strong>5. ______</strong> lunch to go shopping or get some air, while three percent went to the gym.</p><p>The CSP told companies they should encourage all staff to take a <strong>6. ______</strong>（regulate）lunch break. It said workers needed to get more exercise at work so they do not get ill. CSP spokeswoman Karen Middleton said: “Full-time <strong>7. ______</strong>（work）spend a significant bulk of their week at work or <strong>8. ______</strong>（travel）to and from it. Finding ways to build in time to do at least 30 minutes of moderate intensity physical activity, five times a week, can be a challenge.” She <strong>9. ______</strong>（warn）that when employees get sick because they do not take breaks, companies lose money. She said: “It is in everybody&#39;s interests to find ways to tackle the enormous problem of inactivity and we would encourage people <strong>10. ______</strong>（take）responsibility for their own health.”</p><p><strong>【练习七 · 提示词 healthy】Not taking a proper lunch break is ____.</strong></p><ul><li>A. healthy</li><li>B. healthier</li><li>C. healthily</li><li>D. unhealthy</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（unhealthy）</strong> —— 笔记补充解析（原题为有提示词填空）：根据下文「使人生病」可知需要否定意义。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 句意是「不正经吃午饭不健康」，填 healthy 与语义相反。干扰点：看到提示词 healthy 就原词照填。</li><li>B ❌ healthier 是比较级，需要 than 或明确的比较对象，本句没有。干扰点：把「更健康」当褒义选项。</li><li>C ❌ healthily 是副词，不能作 is 后的表语。干扰点：忽略表语位置需要形容词。</li><li>D ✅ is 后接形容词作表语；主语 Not taking a proper lunch break 表否定行为，语义上要用反义形容词，故 unhealthy（un- 否定前缀）。</li></ul><p><strong>整句翻译</strong>：不正经吃午饭是不健康的。</p><p><strong>词组</strong>：<code>work through one’s lunch hour</code> 午休时间继续工作；<code>take a break</code> 休息</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 午休与健康 · 第1段（空1，提示词 healthy））：Not taking a proper lunch break is ____.（unhealthy）</p></details><p><strong>【练习七 · 提示词 made】It can ____ people sick, so then they need time off work.</strong></p><ul><li>A. made</li><li>B. make</li><li>C. making</li><li>D. to make</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（make）</strong> —— 笔记补充解析（原题为有提示词填空）：情态动词 can 后接动词原形。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 情态动词 can 后必须接动词原形，made 是过去式。干扰点：照抄提示词 made。</li><li>B ✅ can + 动词原形，make people sick 表「让人生病」，与后句 need time off work 构成因果。</li><li>C ❌ making 是动名词/现在分词，不能作 can 后的谓语。干扰点：把 -ing 形式填入谓语位置。</li><li>D ❌ can 后不接带 to 的不定式。干扰点：把「用不定式」当成万能规则。</li></ul><p><strong>整句翻译</strong>：它会让人生病，于是他们就需要请假。</p><p><strong>词组</strong>：<code>make sb. sick</code> 使某人生病；<code>time off work</code> 请假、休假</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 午休与健康 · 第1段（空2，提示词 made））：It can ____ people sick, so then they need time off work.（make）</p></details><p><strong>【练习七 · 无提示词】It interviewed over 2,000 people about ____ they do for lunch at work.</strong></p><ul><li>A. that</li><li>B. which</li><li>C. what</li><li>D. how</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（what）</strong> —— 笔记补充解析（原题为无提示词填空）：what 引导宾语从句并在从句中作 do 的宾语；that 引导宾语从句时不作成分。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ that 引导宾语从句时不在从句中充当成分，而本从句缺 do 的宾语。干扰点：把 that 当万能引导词。</li><li>B ❌ which 表「哪一个」，需要有明确的选择范围，本句没有。干扰点：与 what 混用。</li><li>C ✅ what 引导宾语从句并在从句中作 do 的宾语（what they do for lunch＝他们午饭吃什么），结构与语义都成立。</li><li>D ❌ how 表方式，不能充当 do 的宾语。干扰点：把「怎么做」当成「做什么」。</li></ul><p><strong>整句翻译</strong>：它调查了 2000 多人，问他们上班时午饭吃什么。</p><p><strong>词组</strong>：<code>interview sb. about sth.</code> 就某事询问某人；<code>twenty per cent of</code> 百分之二十的</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 午休与健康 · 第1段（空3，无提示词））：It interviewed over 2,000 people about ____ they do for lunch at work.（what）</p></details><p><strong>【练习七 · 提示词 surf】Half of the people took a break but ate their lunch at their desk and ____ the Internet, answered e-mails or went on Facebook.</strong></p><ul><li>A. surfing</li><li>B. surfed</li><li>C. surfs</li><li>D. to surf</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（surfed）</strong> —— 笔记补充解析（原题为有提示词填空）：与 ate, answered, went 并列，使用一般过去时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ surfing 是非谓语形式，而本处与 took、ate 并列，需要谓语动词。干扰点：把非谓语放进并列谓语的位置。</li><li>B ✅ surfed 与前面的 ate 并列构成过去时谓语（and surfed the Internet），时态与全篇过去叙述一致。</li><li>C ❌ surfs 是第三人称单数，与主语 Half of the people（复数）不符，时态也与全篇不一致。干扰点：忽略主谓一致与时态。</li><li>D ❌ to surf 不能与 ate 并列作谓语。干扰点：只求形式与提示词沾边。</li></ul><p><strong>整句翻译</strong>：一半的人休息了，但在办公桌前吃午饭、上网、回邮件或刷 Facebook。</p><p><strong>词组</strong>：<code>surf the Internet</code> 上网；<code>go on Facebook</code> 刷 Facebook</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 午休与健康 · 第1段（空4，提示词 surf））：Half of the people took a break but ate their lunch at their desk and ____ the Internet, answered e-mails or went on Facebook.（surfed）</p></details><p><strong>【练习七 · 无提示词】One in five people left the workplace ____ lunch to go shopping or get some air, while three percent went to the gym.</strong></p><ul><li>A. at</li><li>B. for</li><li>C. in</li><li>D. on</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（for）</strong> —— 笔记补充解析（原题为无提示词填空）：for lunch 表示为了吃午饭。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ at lunch 表「在午饭时」，不能说明离开工作场所的目的。干扰点：把 at lunch 这一高频短语硬套上去。</li><li>B ✅ left the workplace for lunch to go shopping or get some air 表「为了午饭外出购物或透气」，for 表目的，与 to go shopping 的目的状语一致。</li><li>C ❌ in lunch 不成搭配。干扰点：只求介词能填进去。</li><li>D ❌ on lunch 不表目的。干扰点：把 on 当成万能介词。</li></ul><p><strong>整句翻译</strong>：五分之一的人为了午饭离开工作场所去购物或透口气，另有 3% 去了健身房。</p><p><strong>词组</strong>：<code>one in five</code> 五分之一；<code>get some air</code> 透透气</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 午休与健康 · 第1段（空5，无提示词））：One in five people left the workplace ____ lunch to go shopping or get some air, while three percent went to the gym.（for）</p></details><p><strong>【练习七 · 提示词 regulate】The CSP told companies they should encourage all staff to take a ____ lunch break.</strong></p><ul><li>A. regularly</li><li>B. regulation</li><li>C. regulated</li><li>D. regular</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（regular）</strong> —— 笔记补充解析（原题为有提示词填空）：形容词修饰 lunch break。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ regularly 是副词，不能修饰名词 lunch break。干扰点：忽略词性。</li><li>B ❌ regulation 是名词，a regulation lunch break 表「规定的午休」，与原意「规律的午休」不符。干扰点：把名词当形容词。</li><li>C ❌ regulated 表「被规定的」，语义偏被动，不合此处。干扰点：只求形式与 regulate 沾边。</li><li>D ✅ regular 是形容词，修饰 lunch break，take a regular lunch break 表「按时、规律地午休」。</li></ul><p><strong>整句翻译</strong>：CSP 告诉各公司，他们应鼓励所有员工按时午休。</p><p><strong>词组</strong>：<code>encourage sb. to do sth.</code> 鼓励某人做某事；<code>all staff</code> 全体员工</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 午休与健康 · 第2段（空6，提示词 regulate））：The CSP told companies they should encourage all staff to take a ____ lunch break.（regular）</p></details><p><strong>【练习七 · 提示词 work】“Full-time ____ spend a significant bulk of their week at work or travelling to and from it.”</strong></p><ul><li>A. workers</li><li>B. work</li><li>C. working</li><li>D. worked</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（workers）</strong> —— 笔记补充解析（原题为有提示词填空）：作主语并与复数谓语 spend 一致，用名词复数。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 谓语 spend 与代词 their 都需要复数名词作主语，Full-time workers 表「全职工作者」，语义与结构都成立。</li><li>B ❌ work 作名词不能作 spend their week 的主语（不会「工作花掉他们一周」）。干扰点：照抄提示词。</li><li>C ❌ working 是动名词，不能指「人」。干扰点：把 -ing 形式当名词用。</li><li>D ❌ worked 是过去分词，不能作主语。干扰点：只求形式与提示词相近。</li></ul><p><strong>整句翻译</strong>：全职工作者每周有相当大一部分时间在工作，或在往返途中。</p><p><strong>词组</strong>：<code>a significant bulk of</code> 相当大的部分；<code>to and from</code> 往返（来去）</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 午休与健康 · 第2段（空7，提示词 work））：Full-time ____ spend a significant bulk of their week at work or travelling to and from it.（workers）</p></details><p><strong>【练习七 · 提示词 travel】“Full-time workers spend a significant bulk of their week at work or ____ to and from it.”</strong></p><ul><li>A. travelling</li><li>B. traveled</li><li>C. travel</li><li>D. to travel</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（travelling）</strong> —— 笔记补充解析（原题为有提示词填空）：与 at work 并列，介词语境下用动名词。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ or 连接的两个成分要同形：前面是 at work，后面须与 spend…doing sth. 的结构一致，travelling 合乎要求（表示「在往返途中」）。</li><li>B ❌ traveled 是过去式，不能与 or 前的 at work 并列作 spend 的补足成分。干扰点：只求形式与提示词相近。</li><li>C ❌ travel 原形同样不能进入 spend…doing 的结构。干扰点：把动词原形当万能形式。</li><li>D ❌ to travel 与 or 前的成分不并列，也与 spend…doing 冲突。干扰点：把 to do 当固定搭配。</li></ul><p><strong>整句翻译</strong>：全职工作者每周有相当大一部分时间在工作，或在往返途中。</p><p><strong>词组</strong>：<code>spend…doing sth.</code> 花（时间）做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 午休与健康 · 第2段（空8，提示词 travel））：Full-time workers spend a significant bulk of their week at work or ____ to and from it.（travelling）</p></details><p><strong>【练习七 · 提示词 warn】She ____ that when employees get sick because they do not take breaks, companies lose money.</strong></p><ul><li>A. warns</li><li>B. warning</li><li>C. has warned</li><li>D. warned</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（warned）</strong> —— 笔记补充解析（原题为有提示词填空）：叙述研究发言，用一般过去时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ warns 是一般现在时，与全篇过去时（told、said、interviewed）不一致。干扰点：只核对主谓一致。</li><li>B ❌ warning 是非谓语，不能充当主句谓语。干扰点：把 -ing 当谓语。</li><li>C ❌ has warned 是现在完成时，同样与后文 said 的过去时语境冲突。干扰点：把完成时当成「更高级」的形式。</li><li>D ✅ 全篇叙述用过去时（told、said、interviewed），She warned that… 与之保持一致。</li></ul><p><strong>整句翻译</strong>：她警告说，当员工因为不休息而生病时，公司会遭受损失。</p><p><strong>词组</strong>：<code>warn that…</code> 警告说……；<code>lose money</code> 亏钱</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 午休与健康 · 第2段（空9，提示词 warn））：She ____ that when employees get sick because they do not take breaks, companies lose money.（warned）</p></details><p><strong>【练习七 · 提示词 take】“...we would encourage people ____ responsibility for their own health.”</strong></p><ul><li>A. taking</li><li>B. took</li><li>C. to take</li><li>D. take</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（to take）</strong> —— 笔记补充解析（原题为有提示词填空）：固定搭配 encourage sb. to do sth.。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ encourage sb. doing 不是规范搭配。干扰点：把 -ing 当固定形式。</li><li>B ❌ took 不能作 encourage 的宾语补足语。干扰点：只看语义不看结构。</li><li>C ✅ encourage sb. to do sth. 是固定结构，故填 to take，take responsibility for their own health 表「为自己的健康负责」。</li><li>D ❌ take 缺少不定式符号 to，encourage sb. do 不成立。干扰点：漏掉不定式符号。</li></ul><p><strong>整句翻译</strong>：我们会鼓励人们为自己的健康负责。</p><p><strong>词组</strong>：<code>encourage sb. to do sth.</code> 鼓励某人做某事；<code>take responsibility for</code> 对……负责</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习七 · 午休与健康 · 第2段（空10，提示词 take））：…we would encourage people ____ responsibility for their own health.（to take）</p></details><h3 id="练习八-·-户外活动安全-题海-p9" tabindex="-1"><a class="header-anchor" href="#练习八-·-户外活动安全-题海-p9"><span>练习八 · 户外活动安全（题海 P9）</span></a></h3><p>Nowadays more and more people prefer to go <strong>1. ______</strong>（fish）or hiking in the woods. Experiencing nature is exciting, but when you&#39;re doing this, always keep <strong>2. ______</strong>（you）safe. It&#39;s important to remember several <strong>3. ______</strong>（base）rules if you don&#39;t want to turn a pleasant outing into a disaster.</p><p>First, be fully prepared for different weather. Before you set out, always get warm clothes and raincoats ready, just in case! This is <strong>4. ______</strong>（especial）true in the situation of <strong>5. ______</strong>（travel）in the mountain areas. The weather is really <strong>6. ______</strong>（change）in high mountains. Sometimes you can <strong>7. ______</strong>（experience）two or three seasons in one day.</p><p>Second, pack a map, a compass, and a flashlight in your bag. Even experienced travelers get lost. Before you start your trip, study the map to get familiar <strong>8. ______</strong> the area you are going to. The flashlight is important if you do get lost. Many trips that start out in daylight will <strong>9. ______</strong>（probable）become nighttime adventures when people can&#39;t find their way.</p><p>Third, bring a first-aid kit and know how to use it. Small cuts can be more serious when there <strong>10. ______</strong>（be）no doctor nearby.</p><p>Finally, tell people where you are going and when you plan to come back. That way, someone will go search for you if troubles appear. This will increase your chance of being found quickly.</p><p><strong>【练习八 · 提示词 fish】Nowadays more and more people prefer to go ____ or hiking in the woods.</strong></p><ul><li>A. fish</li><li>B. to fish</li><li>C. fishing</li><li>D. fished</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（fishing）</strong> —— 笔记补充解析（原题为有提示词填空）：固定搭配 go fishing，并与 hiking 并列。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ go fish 不表「去钓鱼」，英语里从事某项活动用 go + v-ing。干扰点：照抄提示词 fish。</li><li>B ❌ go to fish 表「去钓鱼」须用 to do 结构，但与 or hiking 的并列不同形。干扰点：把 to do 当万能形式。</li><li>C ✅ go fishing 是固定搭配（go + v-ing 表从事某项活动），与 or hiking 并列同形。</li><li>D ❌ fished 是过去分词，不能与 or hiking 并列。干扰点：只求形式与提示词相近。</li></ul><p><strong>整句翻译</strong>：如今越来越多的人喜欢去钓鱼，或到林中徒步。</p><p><strong>词组</strong>：<code>go fishing/hiking</code> 去钓鱼／去徒步；<code>prefer to do sth.</code> 更喜欢做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 户外活动安全 · 第1段（空1，提示词 fish））：Nowadays more and more people prefer to go ____ or hiking in the woods.（fishing）</p></details><p><strong>【练习八 · 提示词 you】Experiencing nature is exciting, but when you’re doing this, always keep ____ safe.</strong></p><ul><li>A. you</li><li>B. yourself</li><li>C. yours</li><li>D. your</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（yourself）</strong> —— 笔记补充解析（原题为有提示词填空）：keep oneself safe，与主语 you 呼应。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ keep you safe 语法可通，但主语 you 与宾语同指，英语习惯用反身代词。干扰点：忽略主宾同指。</li><li>B ✅ 主语与宾语同指时用反身代词，keep yourself safe 表「保护好自己」，与后文 turn a pleasant outing into a disaster 的提醒一致。</li><li>C ❌ yours 是名词性物主代词，不能作 keep 的宾语。干扰点：把物主代词当反身代词。</li><li>D ❌ your 是形容词性物主代词，不能单独作宾语。干扰点：忽略句法功能。</li></ul><p><strong>整句翻译</strong>：体验大自然是令人兴奋的，但在这样做时，请始终确保自己的安全。</p><p><strong>词组</strong>：<code>keep sb./oneself safe</code> 保证（自己）安全；<code>turn A into B</code> 把 A 变成 B</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 户外活动安全 · 第1段（空2，提示词 you））：Experiencing nature is exciting, but when you’re doing this, always keep ____ safe.（yourself）</p></details><p><strong>【练习八 · 提示词 base】It’s important to remember several ____ rules if you don’t want to turn a pleasant outing into a disaster.</strong></p><ul><li>A. basically</li><li>B. base</li><li>C. basic</li><li>D. bases</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（basic）</strong> —— 笔记补充解析（原题为有提示词填空）：形容词修饰 rules。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ basically 是副词，不能修饰名词 rules。干扰点：忽略词性。</li><li>B ❌ base 是名词或动词，不能修饰 rules。干扰点：照抄提示词。</li><li>C ✅ basic 是形容词，several basic rules 表「几条基本规则」，与后文分条列举对应。</li><li>D ❌ bases 是复数名词，同样不能修饰 rules。干扰点：只求形式与提示词相近。</li></ul><p><strong>整句翻译</strong>：如果你不想把一次愉快的郊游变成灾难，记住几条基本规则很重要。</p><p><strong>词组</strong>：<code>several basic rules</code> 几条基本规则；<code>a pleasant outing</code> 一次愉快的郊游</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 户外活动安全 · 第1段（空3，提示词 base））：It’s important to remember several ____ rules if you don’t want to turn a pleasant outing into a disaster.（basic）</p></details><p><strong>【练习八 · 提示词 especial】This is ____ true in the situation of travelling in the mountain areas.</strong></p><ul><li>A. especially</li><li>B. especial</li><li>C. more especial</li><li>D. especialness</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（especially）</strong> —— 笔记补充解析（原题为有提示词填空）：副词修饰形容词 true。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 副词 especially 修饰形容词 true，表「尤其如此」，符合上下文（山区天气尤其多变）。</li><li>B ❌ especial 是形容词，不能修饰同为形容词的 true。干扰点：忽略修饰关系。</li><li>C ❌ more especial 形式不规范，且同样不能修饰 true。干扰点：把 more 当万能修饰。</li><li>D ❌ especialness 是名词，不能作状语。干扰点：把名词当副词。</li></ul><p><strong>整句翻译</strong>：在山区旅行的情况下尤其如此。</p><p><strong>词组</strong>：<code>be especially true</code> 尤其如此；<code>in the situation of</code> 在……的情况下</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 户外活动安全 · 第2段（空4，提示词 especial））：This is ____ true in the situation of travelling in the mountain areas.（especially）</p></details><p><strong>【练习八 · 提示词 travel】This is especially true in the situation of ____ in the mountain areas.</strong></p><ul><li>A. traveled</li><li>B. travel</li><li>C. to travel</li><li>D. travelling</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（travelling）</strong> —— 笔记补充解析（原题为有提示词填空）：介词 of 后接动名词。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ traveled 是过去分词，不能作介词 of 的宾语。干扰点：只求形式相近。</li><li>B ❌ travel 原形不能作介词宾语。干扰点：把动词原形当万能形式。</li><li>C ❌ to travel 是不定式，介词后不接不定式。干扰点：把 to do 当固定形式。</li><li>D ✅ 介词 of 后接动名词：in the situation of travelling 表「在旅行的情形下」。</li></ul><p><strong>整句翻译</strong>：在山区旅行的情况下尤其如此。</p><p><strong>词组</strong>：<code>in the situation of doing sth.</code> 在做某事的情形下；<code>mountain areas</code> 山区</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 户外活动安全 · 第2段（空5，提示词 travel））：This is especially true in the situation of ____ in the mountain areas.（travelling）</p></details><p><strong>【练习八 · 提示词 change】The weather is really ____ in high mountains.</strong></p><ul><li>A. changeable</li><li>B. change</li><li>C. changing</li><li>D. changed</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（changeable）</strong> —— 笔记补充解析（原题为有提示词填空）：系动词 is 后用形容词，表示天气多变。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ changeable 是形容词，作 is 的表语，表「多变的」，与下句「一天里经历两三个季节」呼应。</li><li>B ❌ change 是动词或名词，不能作表语形容词。干扰点：照抄提示词。</li><li>C ❌ changing 作表语多表「正在变化」，而此处强调天气「多变」这一固有特性。干扰点：把 -ing 当形容词的通用形式。</li><li>D ❌ changed 表「被改变的」，语义不合。干扰点：只求形式沾边。</li></ul><p><strong>整句翻译</strong>：高山上的天气确实多变。</p><p><strong>词组</strong>：<code>changeable weather</code> 多变的天气</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 户外活动安全 · 第2段（空6，提示词 change））：The weather is really ____ in high mountains.（changeable）</p></details><p><strong>【练习八 · 提示词 experience】Sometimes you can ____ two or three seasons in one day.</strong></p><ul><li>A. experience</li><li>B. experiencing</li><li>C. experienced</li><li>D. to experience</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（experience）</strong> —— 笔记补充解析（原题为有提示词填空）：情态动词 can 后接原形。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 情态动词 can 后接动词原形，experience 表「经历」。</li><li>B ❌ experiencing 不能作 can 后的谓语。干扰点：把 -ing 填入谓语位置。</li><li>C ❌ experienced 是过去式或过去分词，不合 can 后的形式要求。干扰点：只求形式相近。</li><li>D ❌ can 后不接带 to 的不定式。干扰点：把不定式当万能形式。</li></ul><p><strong>整句翻译</strong>：有时你能在一天里经历两三个季节。</p><p><strong>词组</strong>：<code>experience two or three seasons</code> 经历两三个季节</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 户外活动安全 · 第2段（空7，提示词 experience））：Sometimes you can ____ two or three seasons in one day.（experience）</p></details><p><strong>【练习八 · 无提示词】Before you start your trip, study the map to get familiar ____ the area you are going to.</strong></p><ul><li>A. to</li><li>B. with</li><li>C. of</li><li>D. at</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（with）</strong> —— 笔记补充解析（原题为无提示词填空）：固定搭配 be/get familiar with。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ be familiar to sb. 表「为某人所熟悉」，主语应是被熟悉的事物；此处主语是人。干扰点：把 familiar to 硬套上去。</li><li>B ✅ 人作主语时用 get/be familiar with，get familiar with the area 表「熟悉这一地区」。</li><li>C ❌ familiar of 不成搭配。干扰点：只求介词能填。</li><li>D ❌ familiar at 同样不成搭配。干扰点：把 at 当万能介词。</li></ul><p><strong>整句翻译</strong>：出发前，研究地图以熟悉你要去的地区。</p><p><strong>词组</strong>：<code>get/be familiar with</code> 熟悉；<code>pack a map</code> 带上地图</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 户外活动安全 · 第3段（空8，无提示词））：Before you start your trip, study the map to get familiar ____ the area you are going to.（with）</p></details><p><strong>【练习八 · 提示词 probable】Many trips that start out in daylight will ____ become nighttime adventures when people can’t find their way.</strong></p><ul><li>A. probable</li><li>B. probability</li><li>C. more probable</li><li>D. probably</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（probably）</strong> —— 笔记补充解析（原题为有提示词填空）：副词修饰动词 become。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ probable 是形容词，不能修饰动词 become。干扰点：忽略词性。</li><li>B ❌ probability 是名词，不能作状语。干扰点：把名词当副词用。</li><li>C ❌ more probable 仍是形容词比较级，同样不能修饰动词。干扰点：把 more 当万能修饰。</li><li>D ✅ 副词 probably 修饰动词 become，will probably become 表「很可能变成」。</li></ul><p><strong>整句翻译</strong>：许多在天亮时出发的行程，会在人们找不到路时变成夜间冒险。</p><p><strong>词组</strong>：<code>start out</code> 出发；<code>find one’s way</code> 找到路</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 户外活动安全 · 第3段（空9，提示词 probable））：Many trips that start out in daylight will ____ become nighttime adventures when people can’t find their way.（probably）</p></details><p><strong>【练习八 · 提示词 be】Small cuts can be more serious when there ____ no doctor nearby.</strong></p><ul><li>A. are</li><li>B. is</li><li>C. were</li><li>D. be</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（is）</strong> —— 笔记补充解析（原题为有提示词填空）：there be 的主语是单数 no doctor。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 主语 no doctor 是单数，与 are 不一致。干扰点：忽略主谓一致。</li><li>B ✅ there be 句型遵循就近一致，no doctor 为单数，且全篇用现在时，故用 is。</li><li>C ❌ were 是过去时复数形式，与全篇现在时和单数主语都不符。干扰点：把 were 当通用形式。</li><li>D ❌ there be 不能用原形 be。干扰点：照抄提示词。</li></ul><p><strong>整句翻译</strong>：当附近没有医生时，小伤口可能更严重。</p><p><strong>词组</strong>：<code>small cuts</code> 小伤口；<code>first-aid kit</code> 急救包</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习八 · 户外活动安全 · 第4段（空10，提示词 be））：Small cuts can be more serious when there ____ no doctor nearby.（is）</p></details><h3 id="练习九-·-过量跑步-题海-p10" tabindex="-1"><a class="header-anchor" href="#练习九-·-过量跑步-题海-p10"><span>练习九 · 过量跑步（题海 P10）</span></a></h3><p>We all know that running a few kilometres each day is good for our health, right? Well, what we didn&#39;t know, until now, is that running too much could be <strong>1. ______</strong> for us. New research suggests that running long distances <strong>2. ______</strong>（regular）for many years could shorten our life instead of <strong>3. ______</strong>（extend）it. The study is from the Minneapolis Heart Institute Foundation. Researcher Dr. James O&#39;Keefe said too much running can cause plaque to build up inside your heart. This can lead <strong>4. ______</strong> heart disease. He wrote: “Years of extreme exercise... appears to erase some benefits you get from moderate exercise, so that your risk of heart disease, of dying of coronary disease（冠状动脉疾病）, is the same as an <strong>5. ______</strong>（active）person.”</p><p>The researchers <strong>6. ______</strong>（look）at the health and training of 3,300 runners over the age of 35. Seventy percent of them ran more than 30 kilometres a week. The study found that men <strong>7. ______</strong> were marathon runners for 25 years had 62 percent more plaque in their heart than men of the same age who did little or no exercise. Another doctor and long-time runner, John Hagan, said he feels cheated. He has been <strong>8. ______</strong>（run）marathons and doing triathlons（三项全能运动）<strong>9. ______</strong> 1967. He used to run up to 60 kilometres per week. He said: “As a physician and a runner, I felt betrayed. I thought I was out there exhausting myself, building <strong>10. ______</strong> absolutely indestructible heart.” Dr. Hagan advised people to exercise regularly but not to overdo things.</p><p><strong>【练习九 · 无提示词】...what we didn’t know, until now, is that running too much could be ____ for us.</strong></p><ul><li>A. good</li><li>B. well</li><li>C. bad</li><li>D. badly</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（bad）</strong> —— 笔记补充解析（原题为无提示词填空）：与前文 good 形成转折，并与「缩短寿命」一致。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ good 与后文「跑太久可能缩短寿命」相反。干扰点：凭「跑步有益健康」的常识选词。</li><li>B ❌ well 作形容词只表「身体好」，不能表「有害/有益」的判断。干扰点：把 well 当 good 的形容词对等物。</li><li>C ✅ be bad for us 表「对我们有害」，与下句 could shorten our life 的负面结论一致；本句用 what we didn’t know 转折。</li><li>D ❌ badly 是副词，不能作 is 后的表语。干扰点：忽略词性。</li></ul><p><strong>整句翻译</strong>：我们原本不知道的是，跑得太多可能对我们有害。</p><p><strong>词组</strong>：<code>be bad for</code> 对……有害；<code>run too much</code> 跑得太多</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 过量跑步 · 第1段（空1，无提示词））：Well, what we didn’t know, until now, is that running too much could be ____ for us.（bad）</p></details><p><strong>【练习九 · 提示词 regular】New research suggests that running long distances ____ for many years could shorten our life instead of extending it.</strong></p><ul><li>A. regular</li><li>B. more regular</li><li>C. regularly</li><li>D. regularity</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（regularly）</strong> —— 笔记补充解析（原题为有提示词填空）：副词修饰 running。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ regular 是形容词，不能修饰 running（此处 running 是动名词，需要状语）。干扰点：照抄提示词。</li><li>B ❌ more regular 是比较级形容词，同样不能作状语。干扰点：把 more 当万能修饰。</li><li>C ✅ 副词 regularly 修饰 running，表「规律地跑」。</li><li>D ❌ regularity 是名词，不能作状语。干扰点：把名词当副词。</li></ul><p><strong>整句翻译</strong>：新研究表明，多年规律地长跑可能缩短而非延长我们的寿命。</p><p><strong>词组</strong>：<code>long distances</code> 长距离；<code>instead of</code> 而不是</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 过量跑步 · 第1段（空2，提示词 regular））：New research suggests that running long distances ____ for many years could shorten our life instead of extending it.（regularly）</p></details><p><strong>【练习九 · 提示词 extend】New research suggests that running long distances regularly for many years could shorten our life instead of ____ it.</strong></p><ul><li>A. extended</li><li>B. to extend</li><li>C. extend</li><li>D. extending</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（extending）</strong> —— 笔记补充解析（原题为有提示词填空）：instead of 后接动名词。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ extended 是过去分词，不能作介词 of 的宾语。干扰点：只求形式相近。</li><li>B ❌ to extend 是不定式，介词 of 后不接。干扰点：把 to do 当万能形式。</li><li>C ❌ extend 原形不能作介词宾语。干扰点：把原形当通用形式。</li><li>D ✅ instead of 是介词短语，后接动名词 extending，与前面 running…could shorten 的结构对应。</li></ul><p><strong>整句翻译</strong>：……可能缩短而非延长我们的寿命。</p><p><strong>词组</strong>：<code>shorten one’s life</code> 缩短寿命；<code>instead of doing sth.</code> 而不是做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 过量跑步 · 第1段（空3，提示词 extend））：New research suggests that running long distances regularly for many years could shorten our life instead of ____ it.（extending）</p></details><p><strong>【练习九 · 无提示词】This can lead ____ heart disease.</strong></p><ul><li>A. in</li><li>B. for</li><li>C. to</li><li>D. at</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（to）</strong> —— 笔记补充解析（原题为无提示词填空）：固定搭配 lead to。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ lead in 表「引入」，不表因果。干扰点：只求能与 lead 搭配。</li><li>B ❌ lead for 不成搭配。干扰点：把介词当填充词。</li><li>C ✅ lead to 是固定搭配，表「导致」，与 plaque to build up inside your heart 的因果一致。</li><li>D ❌ lead at 不成搭配。干扰点：把 at 当万能介词。</li></ul><p><strong>整句翻译</strong>：这可能导致心脏病。</p><p><strong>词组</strong>：<code>lead to</code> 导致；<code>build up</code> 积聚</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 过量跑步 · 第1段（空4，无提示词））：This can lead ____ heart disease.（to）</p></details><p><strong>【练习九 · 提示词 active】“...your risk of heart disease, of dying of coronary disease, is the same as an ____ person.”</strong></p><ul><li>A. inactive</li><li>B. active</li><li>C. actively</li><li>D. action</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（inactive）</strong> —— 笔记补充解析（原题为有提示词填空）：过量运动者的风险与不运动者相同，需要否定前缀。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ inactive 表「不活动的」，与前文「过量运动反而抹掉了适度运动的益处」的逻辑一致：他的风险等同于不运动者。</li><li>B ❌ active 与前文语义矛盾（若等于「爱运动的人」，就不会说风险相同是坏消息）。干扰点：照抄提示词 active。</li><li>C ❌ actively 是副词，不能修饰名词 person。干扰点：忽略词性。</li><li>D ❌ action 是名词，an action person 不成语义。干扰点：只求与提示词相关。</li></ul><p><strong>整句翻译</strong>：……你患心脏病、死于冠状动脉疾病的风险，和一个不运动的人是一样的。</p><p><strong>词组</strong>：<code>the same as</code> 与……相同；<code>coronary disease</code> 冠状动脉疾病</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 过量跑步 · 第1段（空5，提示词 active））：…your risk of heart disease, of dying of coronary disease, is the same as an ____ person.（inactive）</p></details><p><strong>【练习九 · 提示词 look】The researchers ____ at the health and training of 3,300 runners over the age of 35.</strong></p><ul><li>A. looked</li><li>B. look</li><li>C. looking</li><li>D. have looked</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（looked）</strong> —— 笔记补充解析（原题为有提示词填空）：研究发生在过去。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ looked at 与全篇过去时（said、found、wrote）一致，作谓语。</li><li>B ❌ look 原形与过去时语境不符。干扰点：只看搭配不看时态。</li><li>C ❌ looking 是非谓语，不能单独作谓语。干扰点：把 -ing 填入谓语位置。</li><li>D ❌ have looked 是现在完成时，与后文 The study found 的过去时不一致。干扰点：把完成时当更「高级」的时态。</li></ul><p><strong>整句翻译</strong>：研究人员观察了 3,300 名 35 岁以上跑者的健康与训练情况。</p><p><strong>词组</strong>：<code>look at</code> 观察、查看；<code>over the age of</code> 年龄超过</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 过量跑步 · 第2段（空6，提示词 look））：The researchers ____ at the health and training of 3,300 runners over the age of 35.（looked）</p></details><p><strong>【练习九 · 无提示词】The study found that men ____ were marathon runners for 25 years had 62 percent more plaque in their heart than men of the same age who did little or no exercise.</strong></p><ul><li>A. which</li><li>B. who</li><li>C. whom</li><li>D. whose</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（who）</strong> —— 笔记补充解析（原题为无提示词填空）：限制性定语从句，先行词 men 指人，关系词作主语。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ which 指物，不能指人（先行词 men）。干扰点：把 which 当万能关系词。</li><li>B ✅ 先行词 men 指人且在从句中作主语，用关系代词 who。</li><li>C ❌ whom 指人在从句中作宾语，本从句缺主语。干扰点：who/whom 混用。</li><li>D ❌ whose 表所属，本从句已有主语 men，不需要所有格。干扰点：只求与关系词相关。</li></ul><p><strong>整句翻译</strong>：研究发现，跑了 25 年马拉松的男性，其心脏斑块比同龄且很少或不运动的人多 62%。</p><p><strong>词组</strong>：<code>plaque</code> （血管）斑块；<code>little or no exercise</code> 很少或几乎不运动</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 过量跑步 · 第2段（空7，无提示词））：The study found that men ____ were marathon runners for 25 years had 62 percent more plaque in their heart than men of the same age who did little or no exercise.（who）</p></details><p><strong>【练习九 · 提示词 run】He has been ____ marathons and doing triathlons since 1967.</strong></p><ul><li>A. ran</li><li>B. running</li><li>C. to run</li><li>D. runs</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（running）</strong> —— 笔记补充解析（原题为有提示词填空）：与 has been 构成现在完成进行时，并与 doing 并列。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ ran 不能进入 has been ____ 的结构。干扰点：只看语义不看结构。</li><li>B ✅ has been running 是现在完成进行时，表从 1967 年起持续到现在的动作，与 since 1967 一致。</li><li>C ❌ to run 不用于 has been ____ 的结构。干扰点：把 to do 当万能形式。</li><li>D ❌ runs 与 has been 冲突。干扰点：只求形式与提示词相近。</li></ul><p><strong>整句翻译</strong>：他从 1967 年起就一直跑马拉松、参加三项全能运动。</p><p><strong>词组</strong>：<code>triathlon</code> 三项全能运动；<code>feel cheated</code> 觉得受骗</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 过量跑步 · 第2段（空8，提示词 run））：He has been ____ marathons and doing triathlons since 1967.（running）</p></details><p><strong>【练习九 · 无提示词】He has been running marathons and doing triathlons ____ 1967.</strong></p><ul><li>A. for</li><li>B. from</li><li>C. in</li><li>D. since</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（since）</strong> —— 笔记补充解析（原题为无提示词填空）：since + 过去时间点与完成时连用。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ for 后接时间段（for 20 years），不能接 1967 这一时间点。干扰点：for/since 混用。</li><li>B ❌ from 多与 to 连用（from…to…），不单独引导完成时的时间状语。干扰点：把 from 当 since 用。</li><li>C ❌ in 1967 表「在 1967 年」，与 has been running 的持续义不符。干扰点：只求介词能填。</li><li>D ✅ since 1967 表「自 1967 年以来」，与 has been running 的现在完成进行时搭配。</li></ul><p><strong>整句翻译</strong>：他从 1967 年起就一直跑马拉松、参加三项全能运动。</p><p><strong>词组</strong>：<code>since + 时间点</code> 自从……（与完成时连用）</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 过量跑步 · 第2段（空9，无提示词））：He has been running marathons and doing triathlons ____ 1967.（since）</p></details><p><strong>【练习九 · 无提示词】“I thought I was out there exhausting myself, building ____ absolutely indestructible heart.”</strong></p><ul><li>A. a</li><li>B. the</li><li>C. one</li><li>D. an</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（an）</strong> —— 笔记补充解析（原题为无提示词填空）：heart 为可数名词单数，absolutely 以元音音素开头。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ a 用于辅音音素开头的词前，而 absolutely 以元音音素 /ˈæ/ 开头。干扰点：忽略读音而非字母。</li><li>B ❌ the 表特指，此处是泛指「一颗坚强的心脏」。干扰点：把 the 当冠词通用形式。</li><li>C ❌ one 不能替代冠词进入「不定冠词 + 形容词 + 名词」的结构。干扰点：把 one 当 a/an 的替换词。</li><li>D ✅ an 用于元音音素开头的词前：an absolutely indestructible heart。</li></ul><p><strong>整句翻译</strong>：“我以为自己在拼命锻炼，练就一颗绝对坚不可摧的心脏。”</p><p><strong>词组</strong>：<code>indestructible</code> 不可摧毁的；<code>exhaust oneself</code> 把自己累垮</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习九 · 过量跑步 · 第2段（空10，无提示词））：I thought I was out there exhausting myself, building ____ absolutely indestructible heart.（an）</p></details><h3 id="练习十-·-夜班与健康-题海-p10" tabindex="-1"><a class="header-anchor" href="#练习十-·-夜班与健康-题海-p10"><span>练习十 · 夜班与健康（题海 P10）</span></a></h3><p>A new study suggests working shifts at night can be damaging to one&#39;s health. In particular, it increases the risk <strong>1. ______</strong> several cancers, diabetes, mental illnesses, and <strong>2. ______</strong>（variety）heart diseases. Researchers from the Sleep Research Centre at the U.K.&#39;s University of Surrey <strong>3. ______</strong>（discover）that many genes in the body needed to follow a regular 24-hour cycle, during which the body sleeps at night. <strong>4. ______</strong> this cycle is broken, up to 1,500 genes could get damaged, eventually resulting in potentially life-threatening diseases. Professor Derk-Jan Dijk said: “The study has important <strong>5. ______</strong>（implication）because we now need to discover why these rhythms exist and think about the consequences of that.”</p><p>The human body has around 24,000 genes. Many of these switch off if the body does not follow a regular sleeping pattern. This can <strong>6. ______</strong>（causes）parts of the immune system to become less efficient, <strong>7. ______</strong>（make）us more susceptible to illnesses. Study co-author Dr. Simon Archer said: “Over 97 percent of rhythmic genes become out-of-sync with mistimed sleep, <strong>8. ______</strong> really explains why we feel so bad during jet lag or if we have to work irregular shifts.” Dr. Dijk said that despite the results of the research, it would be difficult <strong>9. ______</strong> people to change their lifestyles. He <strong>10. ______</strong>（explain）it was difficult for society to function without people working night shifts, but said people needed to understand the dangers and “mitigate the impact”.</p><p><strong>【练习十 · 无提示词】In particular, it increases the risk ____ several cancers, diabetes, mental illnesses, and various heart diseases.</strong></p><ul><li>A. of</li><li>B. for</li><li>C. in</li><li>D. at</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（of）</strong> —— 笔记补充解析（原题为无提示词填空）：固定搭配 the risk of。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ the risk of sth. 是固定搭配，of 后接风险的内容。</li><li>B ❌ risk for 不合此处搭配（常见的是 at risk for/of）。干扰点：把 for 当成万能介词。</li><li>C ❌ the risk in doing sth. 表「做某事中的风险」，与名词短语不搭。干扰点：只求介词能填。</li><li>D ❌ at risk 表「处于风险中」，本身不接名词短语作定语。干扰点：把 at risk 整块搬来。</li></ul><p><strong>整句翻译</strong>：尤其会增加多种癌症、糖尿病、精神疾病以及各种心脏病的风险。</p><p><strong>词组</strong>：<code>in particular</code> 尤其；<code>increase the risk of</code> 增加……的风险</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 夜班与健康 · 第1段（空1，无提示词））：In particular, it increases the risk ____ several cancers, diabetes, mental illnesses, and various heart diseases.（of）</p></details><p><strong>【练习十 · 提示词 variety】...it increases the risk of several cancers, diabetes, mental illnesses, and ____ heart diseases.</strong></p><ul><li>A. various</li><li>B. variety</li><li>C. variously</li><li>D. variation</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（various）</strong> —— 笔记补充解析（原题为有提示词填空）：形容词修饰复数名词 heart diseases。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ various 是形容词，修饰复数名词 heart diseases，表「各种各样的」。</li><li>B ❌ variety 是名词，须用 a variety of 才成立，此处没有冠词。干扰点：把名词当形容词。</li><li>C ❌ variously 是副词，不能修饰名词。干扰点：忽略词性。</li><li>D ❌ variation 是名词，同样不能修饰名词。干扰点：只求与提示词形式相近。</li></ul><p><strong>整句翻译</strong>：……以及各种心脏病。</p><p><strong>词组</strong>：<code>various heart diseases</code> 各种心脏病</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 夜班与健康 · 第1段（空2，提示词 variety））：…it increases the risk of several cancers, diabetes, mental illnesses, and ____ heart diseases.（various）</p></details><p><strong>【练习十 · 提示词 discover】Researchers from the Sleep Research Centre at the U.K.’s University of Surrey ____ that many genes in the body needed to follow a regular 24-hour cycle, during which the body sleeps at night.</strong></p><ul><li>A. discover</li><li>B. discovering</li><li>C. discovered</li><li>D. have discovered</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（discovered）</strong> —— 笔记补充解析（原题为有提示词填空）：研究结论是过去发现的，与报道语境一致。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ discover 是一般现在时，与后文 Professor Derk-Jan Dijk said 的过去时不一致。干扰点：只求形式相近。</li><li>B ❌ discovering 是非谓语，不能作谓语。干扰点：把 -ing 填入谓语位置。</li><li>C ✅ discovered 与全篇过去时一致，作主句谓语。</li><li>D ❌ have discovered 是现在完成时，与后文的过去时语境不符。干扰点：把完成时当更「正式」的形式。</li></ul><p><strong>整句翻译</strong>：英国萨里大学睡眠研究中心的研究人员发现，人体内许多基因需要遵循规律的 24 小时周期。</p><p><strong>词组</strong>：<code>a regular 24-hour cycle</code> 规律的 24 小时周期；<code>during which</code> 在此期间</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 夜班与健康 · 第1段（空3，提示词 discover））：Researchers from the Sleep Research Centre at the U.K.’s University of Surrey ____ that many genes in the body needed to follow a regular 24-hour cycle…（discovered）</p></details><p><strong>【练习十 · 无提示词】____ this cycle is broken, up to 1,500 genes could get damaged, eventually resulting in potentially life-threatening diseases.</strong></p><ul><li>A. Unless</li><li>B. Though</li><li>C. If</li><li>D. Until</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（If）</strong> —— 笔记补充解析（原题为无提示词填空）：引导条件状语从句，表示这一周期一旦被打破就可能产生后果。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ unless 表「除非」，会读成「除非周期被打乱，基因才会受损」，与语义相反。干扰点：把 unless 当 if 的强调形式。</li><li>B ❌ though 表让步，与「条件—结果」关系不符。干扰点：只求能连接。</li><li>C ✅ If this cycle is broken, up to 1,500 genes could get damaged：if 引导条件句，主句给结果，与 eventually resulting in… 一致。</li><li>D ❌ until 表「直到」，与 could get damaged 的结果不搭。干扰点：把 until 当时间连词通用形式。</li></ul><p><strong>整句翻译</strong>：如果这个周期被打破，多达 1500 个基因可能受损，最终导致可能危及生命的疾病。</p><p><strong>词组</strong>：<code>get damaged</code> 受损；<code>result in</code> 导致；<code>life-threatening</code> 危及生命的</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 夜班与健康 · 第1段（空4，无提示词））：____ this cycle is broken, up to 1,500 genes could get damaged, eventually resulting in potentially life-threatening diseases.（If）</p></details><p><strong>【练习十 · 提示词 implication】“The study has important ____ because we now need to discover why these rhythms exist and think about the consequences of that.”</strong></p><ul><li>A. implication</li><li>B. implications</li><li>C. implicative</li><li>D. implying</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（implications）</strong> —— 笔记补充解析（原题为有提示词填空）：implication 为可数名词，语境指多方面影响。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ implication 单数形式与「多方面意义」的语境不符，且 important 后常用复数。干扰点：照抄提示词。</li><li>B ✅ implications 是可数名词复数，has important implications 表「有重要意义」。</li><li>C ❌ implicative 是形容词，不能作 has 的宾语。干扰点：忽略词性。</li><li>D ❌ implying 是动名词，不表「意义、影响」。干扰点：只求形式相近。</li></ul><p><strong>整句翻译</strong>：“这项研究具有重要意义，因为我们现在需要弄清这些节律为何存在，并思考其后果。”</p><p><strong>词组</strong>：<code>have important implications</code> 具有重要意义；<code>think about the consequences</code> 思考后果</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 夜班与健康 · 第1段（空5，提示词 implication））：The study has important ____ because we now need to discover why these rhythms exist…（implications）</p></details><p><strong>【练习十 · 提示词 causes】This can ____ parts of the immune system to become less efficient, making us more susceptible to illnesses.</strong></p><ul><li>A. causes</li><li>B. causing</li><li>C. cause</li><li>D. caused</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（cause）</strong> —— 笔记补充解析（原题为有提示词填空）：情态动词 can 后用原形。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ causes 与情态动词 can 后的形式要求冲突。干扰点：照抄提示词 causes。</li><li>B ❌ causing 不能作 can 后的谓语。干扰点：把 -ing 填入谓语位置。</li><li>C ✅ can + 动词原形：cause parts of the immune system to become less efficient 表「使部分免疫系统变得低效」。</li><li>D ❌ caused 是过去式，不合 can 后的形式。干扰点：只求形式相近。</li></ul><p><strong>整句翻译</strong>：这会使部分免疫系统变得不那么高效，让我们更容易生病。</p><p><strong>词组</strong>：<code>immune system</code> 免疫系统；<code>be susceptible to</code> 易受……影响</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 夜班与健康 · 第2段（空6，提示词 causes））：This can ____ parts of the immune system to become less efficient, making us more susceptible to illnesses.（cause）</p></details><p><strong>【练习十 · 提示词 make】This can cause parts of the immune system to become less efficient, ____ us more susceptible to illnesses.</strong></p><ul><li>A. made</li><li>B. to make</li><li>C. makes</li><li>D. making</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（making）</strong> —— 笔记补充解析（原题为有提示词填空）：现在分词作结果状语。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ made 是过去式，不能作结果状语。干扰点：只求形式相近。</li><li>B ❌ to make 作结果状语多表意想不到的结果，且与前面 becoming 的结构不一致。干扰点：把 to do 当万能形式。</li><li>C ❌ makes 会造成句中两个谓语，结构冲突。干扰点：把从句谓语形式填进状语。</li><li>D ✅ making us more susceptible to illnesses 是现在分词作结果状语，与 cause…to become less efficient 构成因果。</li></ul><p><strong>整句翻译</strong>：……让我们更容易生病。</p><p><strong>词组</strong>：<code>more susceptible to illnesses</code> 更容易生病</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 夜班与健康 · 第2段（空7，提示词 make））：This can cause parts of the immune system to become less efficient, ____ us more susceptible to illnesses.（making）</p></details><p><strong>【练习十 · 无提示词】“Over 97 percent of rhythmic genes become out-of-sync with mistimed sleep, ____ really explains why we feel so bad during jet lag or if we have to work irregular shifts.”</strong></p><ul><li>A. what</li><li>B. that</li><li>C. it</li><li>D. which</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（which）</strong> —— 笔记补充解析（原题为无提示词填空）：非限制性定语从句，指代前面整件事。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ what 不能引导非限制性定语从句。干扰点：把 what 当万能关系词。</li><li>B ❌ 非限制性定语从句不用 that 引导。干扰点：忽略逗号后的限制。</li><li>C ❌ it 会让前后两个句子缺少连接手段。干扰点：把逗号当分号用。</li><li>D ✅ which 引导非限制性定语从句，指代前面整个句子，作 explains 的主语。</li></ul><p><strong>整句翻译</strong>：“超过 97% 的节律基因会因作息错乱而失调，这正解释了为什么我们在倒时差或不得不轮班时感觉那么糟。”</p><p><strong>词组</strong>：<code>out-of-sync</code> 不同步、失调；<code>jet lag</code> 时差反应</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 夜班与健康 · 第2段（空8，无提示词））：Over 97 percent of rhythmic genes become out-of-sync with mistimed sleep, ____ really explains why we feel so bad during jet lag…（which）</p></details><p><strong>【练习十 · 无提示词】Dr. Dijk said that despite the results of the research, it would be difficult ____ people to change their lifestyles.</strong></p><ul><li>A. of</li><li>B. for</li><li>C. to</li><li>D. with</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（for）</strong> —— 笔记补充解析（原题为无提示词填空）：固定结构 It is difficult for sb. to do sth.。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 形容人性格的形容词才用 of（如 kind of you）；difficult 描述事情，用 for。干扰点：把 of 当不定式复合结构的通用介词。</li><li>B ✅ it is difficult for sb. to do sth. 是固定结构，故用 for people to change their lifestyles。</li><li>C ❌ to 不合该结构。干扰点：只求介词能填。</li><li>D ❌ with 不合该结构。干扰点：把 with 当万能介词。</li></ul><p><strong>整句翻译</strong>：Dijk 博士说，尽管研究有了结果，人们仍难以改变自己的生活方式。</p><p><strong>词组</strong>：<code>it is difficult for sb. to do sth.</code> 某人难以做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 夜班与健康 · 第2段（空9，无提示词））：Dr. Dijk said that despite the results of the research, it would be difficult ____ people to change their lifestyles.（for）</p></details><p><strong>【练习十 · 提示词 explain】He ____ it was difficult for society to function without people working night shifts, but said people needed to understand the dangers and “mitigate the impact”.</strong></p><ul><li>A. explains</li><li>B. explaining</li><li>C. has explained</li><li>D. explained</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（explained）</strong> —— 笔记补充解析（原题为有提示词填空）：与前文 said 一致，用一般过去时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ explains 与后文 but said 的过去时不一致。干扰点：只核对主谓一致。</li><li>B ❌ explaining 是非谓语，不能作谓语。干扰点：把 -ing 当谓语。</li><li>C ❌ has explained 是现在完成时，与过去时语境不符。干扰点：把完成时当更正式的形式。</li><li>D ✅ explained 与后文 but said people needed… 的过去时一致，构成并列谓语。</li></ul><p><strong>整句翻译</strong>：他解释说，没有夜班工作者，社会很难运转，但他表示人们需要了解这些危险并「减轻影响」。</p><p><strong>词组</strong>：<code>function without</code> 在没有……的情况下运转；<code>mitigate the impact</code> 减轻影响</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十 · 夜班与健康 · 第2段（空10，提示词 explain））：He ____ it was difficult for society to function without people working night shifts, but said people needed to understand the dangers…（explained）</p></details><h3 id="练习十一-·-停电之夜-题海-p11" tabindex="-1"><a class="header-anchor" href="#练习十一-·-停电之夜-题海-p11"><span>练习十一 · 停电之夜（题海 P11）</span></a></h3><p>Everything went black! All the lights in our flat turned off, <strong>1. ______</strong>（include）the TV. Mum <strong>2. ______</strong>（take）out the candles and Dad went to see what was going on. One advantage of living in a tall building is that you always have help nearby. So I went to our next-door neighbor, Mr. Smith, <strong>3. ______</strong> lived just next to us. I hoped he could offer some help, for it was dark everywhere and we had no idea what had <strong>4. ______</strong>（happen）. I knocked at his door <strong>5. ______</strong>（gentle）, wondering whether he was at home. With a candle in his hand, Mr. Smith answered the door. Uh-oh! He didn&#39;t have lights, either. I discovered that all the buildings in our neighborhood were dark. Our neighbors went downstairs and began <strong>6. ______</strong>（chat）outside. They were not <strong>7. ______</strong>（worry）at all.</p><p>Then we heard a <strong>8. ______</strong>（frighten）sound after a bright flash of lightning. It started to rain heavily in no time. In order to get some information, Mr. Smith turned on the battery-powered radio. The weatherman said the storm caused all the problems: it hit a power station tower before the first lightning, <strong>9. ______</strong>（make）the lights go out suddenly before the rain. When the lights came back, we cheered loudly. The event made <strong>10. ______</strong> possible for the neighbors to have a chance to be together.</p><p><strong>【练习十一 · 提示词 include】Everything went black! All the lights in our flat turned off, ____ the TV.</strong></p><ul><li>A. included</li><li>B. including</li><li>C. include</li><li>D. to include</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（including）</strong> —— 笔记补充解析（原题为有提示词填空）：介词 including 表示「包括」。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ included 是过去分词，不能这样引出补充说明（习惯用 including）。干扰点：只求形式与提示词相近。</li><li>B ✅ including the TV 作补充说明，表「包括电视在内」，是分词式介词用法。</li><li>C ❌ include 原形不能作插入性的补充说明。干扰点：照抄提示词。</li><li>D ❌ to include 表目的，与「补充列举」不符。干扰点：把不定式当万能形式。</li></ul><p><strong>整句翻译</strong>：一切都黑了！我们公寓所有的灯都灭了，包括电视。</p><p><strong>词组</strong>：<code>turn off</code> （灯）熄灭；<code>everything went black</code> 一切都黑了</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十一 · 停电之夜 · 第1段（空1，提示词 include））：All the lights in our flat turned off, ____ the TV.（including）</p></details><p><strong>【练习十一 · 提示词 take】Mum ____ out the candles and Dad went to see what was going on.</strong></p><ul><li>A. takes</li><li>B. took</li><li>C. taking</li><li>D. has taken</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（took）</strong> —— 笔记补充解析（原题为有提示词填空）：与后面的 went 并列，使用一般过去时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ takes 是现在时，与 and 后 went 的过去时不一致。干扰点：只核对主谓一致。</li><li>B ✅ took 与 Dad went 并列，同为过去时谓语。</li><li>C ❌ taking 是非谓语，不能作谓语。干扰点：把 -ing 填入谓语位置。</li><li>D ❌ has taken 是现在完成时，与后面的 went 不并列。干扰点：把完成时当更正式形式。</li></ul><p><strong>整句翻译</strong>：妈妈拿出蜡烛，爸爸去看看发生了什么事。</p><p><strong>词组</strong>：<code>take out</code> 拿出；<code>see what was going on</code> 看发生了什么事</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十一 · 停电之夜 · 第1段（空2，提示词 take））：Mum ____ out the candles and Dad went to see what was going on.（took）</p></details><p><strong>【练习十一 · 无提示词】So I went to our next-door neighbor, Mr. Smith, ____ lived just next to us.</strong></p><ul><li>A. which</li><li>B. whom</li><li>C. that</li><li>D. who</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（who）</strong> —— 笔记补充解析（原题为无提示词填空）：非限制性定语从句，先行词 Mr. Smith 指人，关系词作主语；that 不能用于逗号后的非限制性定语从句。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ which 指物，不能指人（先行词 Mr. Smith）。干扰点：把 which 当万能关系词。</li><li>B ❌ whom 指人在从句中作宾语，本从句缺主语。干扰点：who/whom 混用。</li><li>C ❌ 非限制性定语从句不能用 that 引导。干扰点：忽略逗号后的限制。</li><li>D ✅ 先行词 Mr. Smith 指人且在从句中作主语，用 who 引导非限制性定语从句。</li></ul><p><strong>整句翻译</strong>：于是我去找隔壁邻居史密斯先生，他就住在我们旁边。</p><p><strong>词组</strong>：<code>next-door neighbor</code> 隔壁邻居；<code>just next to</code> 紧挨着</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十一 · 停电之夜 · 第1段（空3，无提示词））：So I went to our next-door neighbor, Mr. Smith, ____ lived just next to us.（who）</p></details><p><strong>【练习十一 · 提示词 happen】I hoped he could offer some help, for it was dark everywhere and we had no idea what had ____.</strong></p><ul><li>A. happening</li><li>B. happens</li><li>C. happened</li><li>D. was happened</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（happened）</strong> —— 笔记补充解析（原题为有提示词填空）：与 had 构成过去完成时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ happening 不能进入 what had ____ 的结构。干扰点：只求形式相近。</li><li>B ❌ happens 是现在时，与 had 冲突。干扰点：忽略时态。</li><li>C ✅ what had happened 是过去完成时，表「（当时）已经发生了什么」，与全篇过去时叙述一致。</li><li>D ❌ happen 是不及物动词，没有被动语态。干扰点：把「发生」当成需要用被动的动词。</li></ul><p><strong>整句翻译</strong>：我希望他能帮上忙，因为到处都黑着，我们不知道发生了什么。</p><p><strong>词组</strong>：<code>have no idea</code> 不知道；<code>offer help</code> 提供帮助</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十一 · 停电之夜 · 第1段（空4，提示词 happen））：I hoped he could offer some help, for it was dark everywhere and we had no idea what had ____.（happened）</p></details><p><strong>【练习十一 · 提示词 gentle】I knocked at his door ____, wondering whether he was at home.</strong></p><ul><li>A. gentle</li><li>B. gentleness</li><li>C. gently</li><li>D. more gentle</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（gently）</strong> —— 笔记补充解析（原题为有提示词填空）：副词修饰 knocked。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ gentle 是形容词，不能修饰动词 knocked。干扰点：照抄提示词。</li><li>B ❌ gentleness 是名词，不能作状语。干扰点：把名词当副词。</li><li>C ✅ 副词 gently 修饰动词 knocked，表「轻轻地敲」。</li><li>D ❌ more gentle 是比较级形容词，同样不能修饰动词。干扰点：把 more 当万能修饰。</li></ul><p><strong>整句翻译</strong>：我轻轻敲了他的门，想看看他在不在家。</p><p><strong>词组</strong>：<code>knock at the door</code> 敲门；<code>wonder whether</code> 想知道是否</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十一 · 停电之夜 · 第1段（空5，提示词 gentle））：I knocked at his door ____, wondering whether he was at home.（gently）</p></details><p><strong>【练习十一 · 提示词 chat】Our neighbors went downstairs and began ____ outside.</strong></p><ul><li>A. chatting</li><li>B. chatted</li><li>C. chats</li><li>D. to chatting</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（chatting）</strong> —— 笔记补充解析（原题为有提示词填空）：begin doing sth. 表示开始做某事。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ begin doing sth. 是固定结构，began chatting 表「开始聊天」，与 outside 的情境一致。</li><li>B ❌ chatted 是过去式，不能作 began 的宾语。干扰点：只求形式相近。</li><li>C ❌ chats 与 began 的时态和结构都不符。干扰点：忽略结构。</li><li>D ❌ to chatting 形式错误（begin to chat 或 begin chatting）。干扰点：把两种结构混搭。</li></ul><p><strong>整句翻译</strong>：邻居们下楼，开始在外面聊天。</p><p><strong>词组</strong>：<code>go downstairs</code> 下楼；<code>begin doing sth.</code> 开始做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十一 · 停电之夜 · 第1段（空6，提示词 chat））：Our neighbors went downstairs and began ____ outside.（chatting）</p></details><p><strong>【练习十一 · 提示词 worry】They were not ____ at all.</strong></p><ul><li>A. worrying</li><li>B. worriedly</li><li>C. worry</li><li>D. worried</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（worried）</strong> —— 笔记补充解析（原题为有提示词填空）：系动词后用形容词，表示人的感受。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ worrying 表「令人担忧的」（修饰事物），用来形容「人」不合。干扰点：把 -ing 与 -ed 形容词混用。</li><li>B ❌ worriedly 是副词，不能作 were 的表语。干扰点：忽略词性。</li><li>C ❌ worry 是动词或名词，不能作表语形容词。干扰点：照抄提示词。</li><li>D ✅ were not worried at all 表「一点也不担心」，worried 修饰人的感受。</li></ul><p><strong>整句翻译</strong>：他们一点也不担心。</p><p><strong>词组</strong>：<code>not…at all</code> 一点也不；<code>be worried about</code> 担心</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十一 · 停电之夜 · 第1段（空7，提示词 worry））：They were not ____ at all.（worried）</p></details><p><strong>【练习十一 · 提示词 frighten】Then we heard a ____ sound after a bright flash of lightning.</strong></p><ul><li>A. frightening</li><li>B. frightened</li><li>C. frighten</li><li>D. frightenedly</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（frightening）</strong> —— 笔记补充解析（原题为有提示词填空）：修饰事物 sound，表示「令人害怕的」。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ frightening 表「令人害怕的」，修饰sound（事物），符合句意。</li><li>B ❌ frightened 表「感到害怕的」，用于描述人的感受，不能修饰 sound。干扰点：-ing 与 -ed 形容词的修饰对象混用。</li><li>C ❌ frighten 是动词，不能修饰名词。干扰点：照抄提示词。</li><li>D ❌ frightenedly 是副词，不能修饰名词 sound。干扰点：忽略词性。</li></ul><p><strong>整句翻译</strong>：一道亮闪之后，我们听到一个令人害怕的声音。</p><p><strong>词组</strong>：<code>a flash of lightning</code> 一道闪电；<code>in no time</code> 立刻</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十一 · 停电之夜 · 第2段（空8，提示词 frighten））：Then we heard a ____ sound after a bright flash of lightning.（frightening）</p></details><p><strong>【练习十一 · 提示词 make】The weatherman said the storm caused all the problems: it hit a power station tower before the first lightning, ____ the lights go out suddenly before the rain.</strong></p><ul><li>A. made</li><li>B. to make</li><li>C. makes</li><li>D. making</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（making）</strong> —— 笔记补充解析（原题为有提示词填空）：现在分词作结果状语。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ made 是过去式，不能作结果状语。干扰点：只求形式相近。</li><li>B ❌ to make 作结果状语多表意想不到的结果，且与前面 it hit… 的结构不接。干扰点：把 to do 当万能形式。</li><li>C ❌ makes 会造成两个谓语，结构冲突。干扰点：把谓语形式填进状语。</li><li>D ✅ making the lights go out suddenly 是现在分词作结果状语，说明击中塔的后果。</li></ul><p><strong>整句翻译</strong>：天气预报员说暴风雨造成了所有问题：它在第一道闪电前击中了发电站塔，使灯在下雨前突然熄灭。</p><p><strong>词组</strong>：<code>power station tower</code> 发电站塔；<code>go out</code> （灯）熄灭</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十一 · 停电之夜 · 第2段（空9，提示词 make））：The weatherman said the storm caused all the problems: it hit a power station tower before the first lightning, ____ the lights go out suddenly before the rain.（making）</p></details><p><strong>【练习十一 · 无提示词】The event made ____ possible for the neighbors to have a chance to be together.</strong></p><ul><li>A. it</li><li>B. that</li><li>C. this</li><li>D. them</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（it）</strong> —— 笔记补充解析（原题为无提示词填空）：make it possible for sb. to do sth.，it 作形式宾语。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ make it possible for sb. to do sth. 是固定结构，it 作形式宾语，真正的宾语是后面的不定式短语。</li><li>B ❌ that 不能作形式宾语。干扰点：把 that 当万能代词。</li><li>C ❌ this 表近指，不能充当形式宾语。干扰点：只求代词能填。</li><li>D ❌ them 会使 make them possible for the neighbors 语义混乱。干扰点：把邻居的复数形式套进空格。</li></ul><p><strong>整句翻译</strong>：这件事让邻居们有机会聚在一起。</p><p><strong>词组</strong>：<code>make it possible for sb. to do sth.</code> 使某人有可能做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十一 · 停电之夜 · 第2段（空10，无提示词））：The event made ____ possible for the neighbors to have a chance to be together.（it）</p></details><h3 id="练习十二-·-过去的生活智慧-题海-p11" tabindex="-1"><a class="header-anchor" href="#练习十二-·-过去的生活智慧-题海-p11"><span>练习十二 · 过去的生活智慧（题海 P11）</span></a></h3><p>Technology has great <strong>1. ______</strong>（important）in our daily life now. Yet not many of <strong>2. ______</strong>（we）will realize how much we rely on it until we compare our lives with those in the past. There was no modern technology at that time, yet the items that people had <strong>3. ______</strong>（be）quite enough for them to live their lives.</p><p>Without necessary cooking tools, the people could still manage to make their food as <strong>4. ______</strong>（nice）as our food today. Animal parts were thrown away if they were not delicious. <strong>5. ______</strong>（Other）were cooked over the fire. However, everything they used was <strong>6. ______</strong>（take）from the forests around them.</p><p>Without the television set, the radio and the computer, we will seldom have <strong>7. ______</strong>（some）fun in our homes today. However, the people in the past had their own clever methods of enjoying <strong>8. ______</strong>（them）. For example, they made music without the use of computers but with tools <strong>9. ______</strong>（make）from wood and animal skin.</p><p>Some things are basic for us nowadays, but the people in the past could live their lives to the full even without them. We should not look down on the <strong>10. ______</strong>（wise）of people long ago.</p><p><strong>【练习十二 · 提示词 important】Technology has great ____ in our daily life now.</strong></p><ul><li>A. importance</li><li>B. important</li><li>C. importantly</li><li>D. more important</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（importance）</strong> —— 笔记补充解析（原题为有提示词填空）：has 后缺名词作宾语。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ importance 是名词，great importance 作 has 的宾语，表「极为重要」。</li><li>B ❌ important 是形容词，不能作 has 的宾语。干扰点：照抄提示词。</li><li>C ❌ importantly 是副词，同样不能作宾语。干扰点：忽略词性。</li><li>D ❌ more important 是比较级形容词，不能作 has 的宾语。干扰点：把 more 当名词的修饰方式。</li></ul><p><strong>整句翻译</strong>：如今，科技在我们的日常生活中极为重要。</p><p><strong>词组</strong>：<code>have great importance</code> 极为重要；<code>rely on</code> 依赖</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 过去的生活智慧 · 第1段（空1，提示词 important））：Technology has great ____ in our daily life now.（importance）</p></details><p><strong>【练习十二 · 提示词 we】Yet not many of ____ will realize how much we rely on it until we compare our lives with those in the past.</strong></p><ul><li>A. we</li><li>B. our</li><li>C. us</li><li>D. ourselves</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（us）</strong> —— 笔记补充解析（原题为有提示词填空）：介词 of 后用人称代词宾格。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ we 作主语，不能作介词 of 的宾语。干扰点：忽略介词后需宾格。</li><li>B ❌ our 是形容词性物主代词，不能作 of 的宾语。干扰点：把物主代词当宾格。</li><li>C ✅ 介词 of 后接宾格 us，not many of us 表「我们中很少有人」。</li><li>D ❌ ourselves 是反身代词，与 not many of 的语义不合。干扰点：把反身代词当宾格。</li></ul><p><strong>整句翻译</strong>：然而，我们中很少有人会意识到自己有多依赖它，直到我们把现在的生活与过去相比。</p><p><strong>词组</strong>：<code>not many of us</code> 我们中很少有人；<code>compare A with B</code> 把 A 与 B 比较</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 过去的生活智慧 · 第1段（空2，提示词 we））：Yet not many of ____ will realize how much we rely on it until we compare our lives with those in the past.（us）</p></details><p><strong>【练习十二 · 提示词 be】There was no modern technology at that time, yet the items that people had ____ quite enough for them to live their lives.</strong></p><ul><li>A. were</li><li>B. was</li><li>C. are</li><li>D. be</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（were）</strong> —— 笔记补充解析（原题为有提示词填空）：主语 the items 为复数，叙述过去。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 主语 the items 是复数，且全篇叙述过去的事，故用 were。</li><li>B ❌ was 是单数形式，与复数的 the items 不一致。干扰点：忽略主谓一致。</li><li>C ❌ are 是现在时，与 There was no modern technology 的过去语境不符。干扰点：只求形式相近。</li><li>D ❌ there be 之外的句子不能用原形 be 作谓语。干扰点：照抄提示词。</li></ul><p><strong>整句翻译</strong>：那时没有现代科技，但人们拥有的物品足以让他们过日子。</p><p><strong>词组</strong>：<code>at that time</code> 那时；<code>enough for sb. to do sth.</code> 足够某人做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 过去的生活智慧 · 第1段（空3，提示词 be））：There was no modern technology at that time, yet the items that people had ____ quite enough for them to live their lives.（were）</p></details><p><strong>【练习十二 · 提示词 nice】Without necessary cooking tools, the people could still manage to make their food as ____ as our food today.</strong></p><ul><li>A. nicer</li><li>B. nicest</li><li>C. nicely</li><li>D. nice</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（nice）</strong> —— 笔记补充解析（原题为有提示词填空）：as + 形容词原级 + as。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ nicer 是比较级，不能进入 as…as 结构。干扰点：把比较级与同级比较混淆。</li><li>B ❌ nicest 是最高级，同样不合 as…as。干扰点：只求与 nice 相关。</li><li>C ❌ nicely 是副词，不能作 food 的补足语（此处描述食物本身）。干扰点：忽略词性。</li><li>D ✅ as nice as our food today 是同级比较结构，中间用形容词原级。</li></ul><p><strong>整句翻译</strong>：没有必要的炊具，人们仍能把食物做得和我们今天的一样好吃。</p><p><strong>词组</strong>：<code>manage to do sth.</code> 设法做成某事；<code>as…as…</code> 和……一样</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 过去的生活智慧 · 第2段（空4，提示词 nice））：Without necessary cooking tools, the people could still manage to make their food as ____ as our food today.（nice）</p></details><p><strong>【练习十二 · 提示词 Other】Animal parts were thrown away if they were not delicious. ____ were cooked over the fire.</strong></p><ul><li>A. Other</li><li>B. Another</li><li>C. The other</li><li>D. Others</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（Others）</strong> —— 笔记补充解析（原题为有提示词填空）：some...others... 表示「一些……另一些……」，位于句首首字母大写。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ Other 后须接名词，不能单独作主语。干扰点：忽略 other 的句法限制。</li><li>B ❌ Another 表「另一个」，是单数，与 were cooked 的复数谓语不符。干扰点：忽略单复数。</li><li>C ❌ The other 指「两者中的另一个」，与「其余若干部分」的语义不符。干扰点：把 the other 当复数的 others。</li><li>D ✅ Others 是复数代词，可单独作主语，与 were cooked 一致，表「其余的部分」。</li></ul><p><strong>整句翻译</strong>：动物身上不好吃的部分被丢掉，其余的都架在火上烧烤。</p><p><strong>词组</strong>：<code>throw away</code> 丢弃；<code>over the fire</code> 在火上</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 过去的生活智慧 · 第2段（空5，提示词 Other））：Animal parts were thrown away if they were not delicious. ____ were cooked over the fire.（Others）</p></details><p><strong>【练习十二 · 提示词 take】However, everything they used was ____ from the forests around them.</strong></p><ul><li>A. taking</li><li>B. taken</li><li>C. took</li><li>D. to take</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（taken）</strong> —— 笔记补充解析（原题为有提示词填空）：与 was 构成被动语态。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ taking 不能作 was 后的成分。干扰点：只求形式相近。</li><li>B ✅ was taken from 是被动语态，表「被取自」，主语 everything they used 是动作的承受者。</li><li>C ❌ took 是主动的过去式，与 was ____ 结构冲突。干扰点：忽略被动语态。</li><li>D ❌ to take 不合 was ____ 结构。干扰点：把不定式当万能形式。</li></ul><p><strong>整句翻译</strong>：然而，他们所用的一切都取自周围的森林。</p><p><strong>词组</strong>：<code>be taken from</code> 取自；<code>around them</code> 他们周围的</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 过去的生活智慧 · 第2段（空6，提示词 take））：However, everything they used was ____ from the forests around them.（taken）</p></details><p><strong>【练习十二 · 提示词 some】Without the television set, the radio and the computer, we will seldom have ____ fun in our homes today.</strong></p><ul><li>A. some</li><li>B. any</li><li>C. no</li><li>D. many</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（any）</strong> —— 笔记补充解析（原题为有提示词填空）：否定语境 seldom 中使用 any。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ some 多用于肯定句，而本句有 seldom（否定含义）。干扰点：忽略否定语境。</li><li>B ✅ seldom 是否定词，否定句中用 any，seldom have any fun 表「几乎没有乐趣」。</li><li>C ❌ no 会与 seldom 叠加成双重否定。干扰点：把否定词重复使用。</li><li>D ❌ many 修饰可数名词复数，fun 是不可数名词。干扰点：忽略可数性。</li></ul><p><strong>整句翻译</strong>：如果没有电视、收音机和电脑，我们如今在家里很少有乐趣。</p><p><strong>词组</strong>：<code>seldom</code> 很少；<code>without…</code> 如果没有……</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 过去的生活智慧 · 第3段（空7，提示词 some））：Without the television set, the radio and the computer, we will seldom have ____ fun in our homes today.（any）</p></details><p><strong>【练习十二 · 提示词 them】However, the people in the past had their own clever methods of enjoying ____.</strong></p><ul><li>A. them</li><li>B. theirs</li><li>C. their</li><li>D. themselves</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（themselves）</strong> —— 笔记补充解析（原题为有提示词填空）：固定搭配 enjoy oneself。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ them 指别人，而此处主语与宾语同指「过去的人们」。干扰点：忽略主宾同指。</li><li>B ❌ theirs 是名词性物主代词，不表反身。干扰点：把物主代词当反身代词。</li><li>C ❌ their 是形容词性物主代词，不能作宾语。干扰点：忽略句法功能。</li><li>D ✅ 主语与宾语同指时用反身代词：enjoying themselves 表「自娱自乐」。</li></ul><p><strong>整句翻译</strong>：然而，过去的人们有自己巧妙的方式自娱自乐。</p><p><strong>词组</strong>：<code>enjoy oneself</code> 玩得开心、自娱自乐</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 过去的生活智慧 · 第3段（空8，提示词 them））：However, the people in the past had their own clever methods of enjoying ____.（themselves）</p></details><p><strong>【练习十二 · 提示词 make】For example, they made music without the use of computers but with tools ____ from wood and animal skin.</strong></p><ul><li>A. making</li><li>B. to make</li><li>C. made</li><li>D. makes</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（made）</strong> —— 笔记补充解析（原题为有提示词填空）：过去分词作后置定语，工具由木头和兽皮制成。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ making 表主动或进行，而 tools 与 make 是被动关系。干扰点：忽略主动/被动。</li><li>B ❌ to make 表目的，与 tools ____ from wood 的定语功能不符。干扰点：把不定式当定语的通用形式。</li><li>C ✅ tools made from wood and animal skin 是过去分词短语作后置定语，表「由木头和兽皮制作的工具」。</li><li>D ❌ makes 是谓语形式，不能作后置定语。干扰点：把谓语填进定语位置。</li></ul><p><strong>整句翻译</strong>：例如，他们不用电脑，而是用木头和兽皮做成的工具来制作音乐。</p><p><strong>词组</strong>：<code>animal skin</code> 兽皮；<code>make music</code> 制作音乐</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 过去的生活智慧 · 第3段（空9，提示词 make））：For example, they made music without the use of computers but with tools ____ from wood and animal skin.（made）</p></details><p><strong>【练习十二 · 提示词 wise】We should not look down on the ____ of people long ago.</strong></p><ul><li>A. wise</li><li>B. wisdom</li><li>C. wisely</li><li>D. wisest</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（wisdom）</strong> —— 笔记补充解析（原题为有提示词填空）：冠词 the 后用名词。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ wise 是形容词，不能作 on 的宾语。干扰点：照抄提示词。</li><li>B ✅ wisdom 是名词，the wisdom of people long ago 表「古人的智慧」，作 look down on 的宾语。</li><li>C ❌ wisely 是副词，不能作宾语。干扰点：忽略词性。</li><li>D ❌ wisest 是最高级形容词，不能作宾语。干扰点：只求与 wise 相关。</li></ul><p><strong>整句翻译</strong>：我们不应轻视古人的智慧。</p><p><strong>词组</strong>：<code>look down on</code> 轻视；<code>to the full</code> 充分地</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十二 · 过去的生活智慧 · 末段（空10，提示词 wise））：We should not look down on the ____ of people long ago.（wisdom）</p></details><h3 id="练习十三-·-重建学校-题海-p12" tabindex="-1"><a class="header-anchor" href="#练习十三-·-重建学校-题海-p12"><span>练习十三 · 重建学校（题海 P12）</span></a></h3><p>A school had major problems with some of <strong>1. ______</strong>（it）buildings. Susan, the head teacher, invited students to share their ideas about <strong>2. ______</strong> to rebuild the school. “We <strong>3. ______</strong>（want）our students to decide what kind of school buildings they like. We wanted them to think of ideas <strong>4. ______</strong>（express）their own interests and hopes,” she said. The news spread <strong>5. ______</strong>（wide）after it was reported <strong>6. ______</strong> a local newspaper. Students certainly seemed very <strong>7. ______</strong>（excite）. And some said they couldn&#39;t wait for the project to be finally completed at the end of this year.</p><p>In the beginning, the school was asked to close and the buildings would have to be sold off, as the school is in a very good <strong>8. ______</strong>（locate）. But parents and teachers worked together to protect the school and now they are pleased to see the result.</p><p>“This school is <strong>9. ______</strong> important part of the community and it&#39;s necessary that it should continue,” said one parent, adding, “It is also amazing that the children have had a say in the building process. This gives them the feeling that they are more closely connected with the school. I really think the school will develop with <strong>10. ______</strong>（succeed）.”</p><p><strong>【练习十三 · 提示词 it】A school had major problems with some of ____ buildings.</strong></p><ul><li>A. it</li><li>B. itself</li><li>C. it’s</li><li>D. its</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（its）</strong> —— 笔记补充解析（原题为有提示词填空）：形容词性物主代词修饰 buildings。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ it 是主格或宾格，不能作定语修饰 buildings。干扰点：照抄提示词。</li><li>B ❌ itself 是反身代词，不能作定语。干扰点：把反身代词当所有格。</li><li>C ❌ it’s 是 it is 的缩写，不能作定语。干扰点：its 与 it’s 同音混淆。</li><li>D ✅ its 是形容词性物主代词，修饰名词 buildings：some of its buildings 表「它的一些建筑」。</li></ul><p><strong>整句翻译</strong>：一所学校的一些建筑存在严重问题。</p><p><strong>词组</strong>：<code>have problems with</code> 在……方面有问题；<code>some of</code> ……中的一些</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 重建学校 · 第1段（空1，提示词 it））：A school had major problems with some of ____ buildings.（its）</p></details><p><strong>【练习十三 · 无提示词】Susan, the head teacher, invited students to share their ideas about ____ to rebuild the school.</strong></p><ul><li>A. what</li><li>B. how</li><li>C. that</li><li>D. why</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（how）</strong> —— 笔记补充解析（原题为无提示词填空）：how to do 表示「如何做」，作 about 的宾语。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ what to rebuild 表「重建什么」，而本句谈的是「如何重建」，且与 share their ideas 的语境不符。干扰点：how/what 混用。</li><li>B ✅ how to rebuild the school 表「如何重建学校」，与 share their ideas about… 的搭配一致。</li><li>C ❌ that 不能进入 about ____ to do 的结构。干扰点：把 that 当万能引导词。</li><li>D ❌ why 表原因，不合「提出建议」的语境。干扰点：只求疑问词能填。</li></ul><p><strong>整句翻译</strong>：校长 Susan 邀请学生们分享关于如何重建学校的想法。</p><p><strong>词组</strong>：<code>share one’s ideas about</code> 分享关于……的想法；<code>head teacher</code> 校长</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 重建学校 · 第1段（空2，无提示词））：Susan, the head teacher, invited students to share their ideas about ____ to rebuild the school.（how）</p></details><p><strong>【练习十三 · 提示词 want】“We ____ our students to decide what kind of school buildings they like.”</strong></p><ul><li>A. want</li><li>B. wants</li><li>C. have wanted</li><li>D. wanted</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（wanted）</strong> —— 笔记补充解析（原题为有提示词填空）：引语内容叙述当时的愿望，并与下一句 wanted 一致。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ want 是现在时，与后文 she said、We wanted them to think… 的过去时不一致。干扰点：只核对主谓一致。</li><li>B ❌ wants 是第三人称单数，与主语 We 不符。干扰点：忽略主谓一致。</li><li>C ❌ have wanted 是现在完成时，与全段过去时不符。干扰点：把完成时当更正式形式。</li><li>D ✅ wanted 与 invited、said 的过去时一致，构成连贯的叙述。</li></ul><p><strong>整句翻译</strong>：“我们想让学生自己决定他们喜欢什么样的校舍。”</p><p><strong>词组</strong>：<code>want sb. to do sth.</code> 想要某人做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 重建学校 · 第1段（空3，提示词 want））：“We ____ our students to decide what kind of school buildings they like.”（wanted）</p></details><p><strong>【练习十三 · 提示词 express】“We wanted them to think of ideas ____ their own interests and hopes,” she said.</strong></p><ul><li>A. expressing</li><li>B. to express</li><li>C. expressed</li><li>D. express</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（to express）</strong> —— 笔记补充解析（原题为有提示词填空）：不定式作目的状语，说明提出想法的目的。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ expressing 表主动或进行，而此处是「用来表达」的目的关系。干扰点：把 -ing 当定语的通用形式。</li><li>B ✅ ideas to express their own interests and hopes 中不定式作后置定语，表「用来表达自身兴趣与期望的想法」。</li><li>C ❌ expressed 表被动，与「点子用来表达兴趣」的主动义不符。干扰点：忽略主动/被动。</li><li>D ❌ express 原形不能作后置定语。干扰点：照抄提示词。</li></ul><p><strong>整句翻译</strong>：“我们想让他们想出能表达自身兴趣与期望的点子。”她说。</p><p><strong>词组</strong>：<code>think of ideas</code> 想点子；<code>interests and hopes</code> 兴趣与期望</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 重建学校 · 第1段（空4，提示词 express））：We wanted them to think of ideas ____ their own interests and hopes.（to express）</p></details><p><strong>【练习十三 · 提示词 wide】The news spread ____ after it was reported in a local newspaper.</strong></p><ul><li>A. widely</li><li>B. wide</li><li>C. width</li><li>D. widen</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（widely）</strong> —— 笔记补充解析（原题为有提示词填空）：副词修饰 spread。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ widely 是副词，修饰动词 spread，表「广泛地传播」。</li><li>B ❌ wide 作副词时多表「充分地张开」（open wide），不修饰 spread 表范围。干扰点：把 wide 当 widely 用。</li><li>C ❌ width 是名词，不能修饰动词。干扰点：忽略词性。</li><li>D ❌ widen 是动词，不能作状语。干扰点：只求与提示词相关。</li></ul><p><strong>整句翻译</strong>：这条消息在当地报纸报道后广泛传播。</p><p><strong>词组</strong>：<code>spread widely</code> 广泛传播；<code>a local newspaper</code> 当地报纸</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 重建学校 · 第1段（空5，提示词 wide））：The news spread ____ after it was reported in a local newspaper.（widely）</p></details><p><strong>【练习十三 · 无提示词】The news spread widely after it was reported ____ a local newspaper.</strong></p><ul><li>A. in</li><li>B. on</li><li>C. at</li><li>D. by</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（in）</strong> —— 笔记补充解析（原题为无提示词填空）：in a newspaper 表示刊登在报纸上。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 报纸等纸质媒体用 in：reported in a local newspaper。</li><li>B ❌ on 多用于具体平台或网页。干扰点：把 on 当通用媒介介词。</li><li>C ❌ at 不合媒介搭配。干扰点：只求介词能填。</li><li>D ❌ by 表「由……（机构/作者）」，与「在报纸上」不同。干扰点：把被动语态的执行者与载体混淆。</li></ul><p><strong>整句翻译</strong>：这条消息在当地报纸报道后广泛传播。</p><p><strong>词组</strong>：<code>be reported in a newspaper</code> 在报纸上被报道</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 重建学校 · 第1段（空6，无提示词））：The news spread widely after it was reported ____ a local newspaper.（in）</p></details><p><strong>【练习十三 · 提示词 excite】Students certainly seemed very ____.</strong></p><ul><li>A. exciting</li><li>B. excitedly</li><li>C. excited</li><li>D. excitement</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（excited）</strong> —— 笔记补充解析（原题为有提示词填空）：描述学生的感受，用 -ed 形容词。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ exciting 表「令人兴奋的」，修饰事物，不能描述学生的感受。干扰点：-ing 与 -ed 形容词的修饰对象混用。</li><li>B ❌ excitedly 是副词，不能作 seemed 的表语。干扰点：忽略词性。</li><li>C ✅ excited 表「感到兴奋的」，描述人的感受，与 Students certainly seemed very excited 一致。</li><li>D ❌ excitement 是名词，不能作表语形容词。干扰点：只求与提示词相关。</li></ul><p><strong>整句翻译</strong>：学生们看起来当然非常兴奋。</p><p><strong>词组</strong>：<code>seem excited</code> 看起来很兴奋；<code>can’t wait for</code> 迫不及待地等</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 重建学校 · 第1段（空7，提示词 excite））：Students certainly seemed very ____.（excited）</p></details><p><strong>【练习十三 · 提示词 locate】In the beginning, the school was asked to close and the buildings would have to be sold off, as the school is in a very good ____.</strong></p><ul><li>A. located</li><li>B. local</li><li>C. location</li><li>D. locating</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（location）</strong> —— 笔记补充解析（原题为有提示词填空）：形容词 good 后接名词。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ located 是过去分词，in a very good located 结构不成立。干扰点：只求形式相近。</li><li>B ❌ local 是形容词，不能作介词 in 的宾语。干扰点：忽略词性。</li><li>C ✅ location 是名词，in a very good location 表「位于很好的地段」，与 be sold off 的原因呼应。</li><li>D ❌ locating 是动名词，不表「地段」这一名词概念。干扰点：把 -ing 当名词用。</li></ul><p><strong>整句翻译</strong>：起初，学校被要求关闭，校舍将被出售，因为学校位于很好的地段。</p><p><strong>词组</strong>：<code>be sold off</code> 被出售；<code>in a good location</code> 位于好地段</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 重建学校 · 第2段（空8，提示词 locate））：In the beginning, the school was asked to close and the buildings would have to be sold off, as the school is in a very good ____.（location）</p></details><p><strong>【练习十三 · 无提示词】“This school is ____ important part of the community and it’s necessary that it should continue,” said one parent.</strong></p><ul><li>A. a</li><li>B. an</li><li>C. the</li><li>D. one</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（an）</strong> —— 笔记补充解析（原题为无提示词填空）：part 为可数名词单数，important 以元音音素开头。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ important 以元音音素 /ɪ/ 开头，不能用 a。干扰点：忽略读音，只看字母。</li><li>B ✅ an important part of the community 表「社区的一个重要组成部分」，an 用于元音音素开头的词前。</li><li>C ❌ the 表特指，而此处是泛指「一个重要部分」。干扰点：把 the 当冠词通用形式。</li><li>D ❌ one 会读成「一个（而非两个）部分」，与固定表达 an important part of 不同。干扰点：把 one 当 a/an 的替换词。</li></ul><p><strong>整句翻译</strong>：“这所学校是社区的重要组成部分，它有必要继续办下去。”一位家长说。</p><p><strong>词组</strong>：<code>an important part of</code> ……的重要组成部分；<code>have a say in</code> 在……上有发言权</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 重建学校 · 第3段（空9，无提示词））：“This school is ____ important part of the community and it’s necessary that it should continue,” said one parent.（an）</p></details><p><strong>【练习十三 · 提示词 succeed】“I really think the school will develop with ____.”</strong></p><ul><li>A. successful</li><li>B. successfully</li><li>C. success</li><li>D. succeed</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（success）</strong> —— 笔记补充解析（原题为有提示词填空）：介词 with 后用名词。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ successful 是形容词，不能作介词 with 的宾语。干扰点：忽略词性。</li><li>B ❌ successfully 是副词，同样不能作宾语。干扰点：把副词当名词用。</li><li>C ✅ success 是名词，作介词 with 的宾语：develop with success 表「成功地发展」。</li><li>D ❌ succeed 是动词，不能作介词宾语。干扰点：照抄提示词。</li></ul><p><strong>整句翻译</strong>：“我真的认为这所学校会成功地发展下去。”</p><p><strong>词组</strong>：<code>with success</code> 成功地；<code>be closely connected with</code> 与……紧密相连</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十三 · 重建学校 · 第3段（空10，提示词 succeed））：I really think the school will develop with ____.（success）</p></details><h3 id="练习十四-·-校园节约行动-题海-p13" tabindex="-1"><a class="header-anchor" href="#练习十四-·-校园节约行动-题海-p13"><span>练习十四 · 校园节约行动（题海 P13）</span></a></h3><p>Dear Jenny,</p><p>How&#39;s it going? Are you busy with your study these days?</p><p>I&#39;ve been back at school <strong>1. ______</strong> nearly four weeks. I&#39;m very glad to tell you <strong>2. ______</strong> great changes have taken place in our school this term. First of all, we&#39;re <strong>3. ______</strong>（ask）to “clear our plates” when having our meals and say no to wasting. Some of us <strong>4. ______</strong>（use）to order more than what we could eat. That was a big waste of food. Now we need to finish the food we order. We should also stop <strong>5. ______</strong>（waste）in some other ways. For example, we should turn off the lights <strong>6. ______</strong> we leave the classroom. And our school has opened up some fields for us to learn how <strong>7. ______</strong> grow vegetables.</p><p>Each class is given a small garden and our class has decided to grow some <strong>8. ______</strong>（tomato）and beans in our free time. I think that&#39;ll be very interesting. Maybe I&#39;ll be able to post you some beans we&#39;ve grown by <strong>9. ______</strong>（we）next time! What&#39;s more, we have only two classes in the afternoon so we have <strong>10. ______</strong>（much）time for after-school activities than before. I&#39;m one of the traffic safety volunteers in our school. After school, we take turns to go to the streets near our school and ask people to follow the traffic rules.</p><p>I think we are having a different school life now!</p><p>Please write back soon and tell me more about your school.</p><p><strong>【练习十四 · 无提示词】I’ve been back at school ____ nearly four weeks.</strong></p><ul><li>A. since</li><li>B. for</li><li>C. in</li><li>D. at</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（for）</strong> —— 笔记补充解析（原题为无提示词填空）：for + 时间段与现在完成时连用。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ since 后接时间点（since 2020），不能接 nearly four weeks 这一时间段。干扰点：since 与 for 混用。</li><li>B ✅ for nearly four weeks 表「持续将近四周」，与 have been back 的现在完成时搭配。</li><li>C ❌ in 表「在……之后/之内」，与持续四周不符。干扰点：只求介词能填。</li><li>D ❌ at 后接具体时刻或地点，不接时间段。干扰点：把 at 当时间介词。</li></ul><p><strong>整句翻译</strong>：我回学校已经将近四周了。</p><p><strong>词组</strong>：<code>be back at school</code> 回校；<code>for + 时间段</code> 持续一段时间</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · 节约与菜园 · 第1段（空1，无提示词））：I’ve been back at school ____ nearly four weeks.（for）</p></details><p><strong>【练习十四 · 无提示词】I’m very glad to tell you ____ great changes have taken place in our school this term.</strong></p><ul><li>A. what</li><li>B. that</li><li>C. which</li><li>D. whether</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（that）</strong> —— 笔记补充解析（原题为无提示词填空）：tell you that...，that 引导宾语从句且不作成分。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ what 引导的从句缺少成分时才能用，而本从句 great changes have taken place 成分完整。干扰点：把 what 当万能引导词。</li><li>B ✅ that 引导宾语从句且从句成分完整，great changes have taken place in our school 结构齐全。</li><li>C ❌ which 多用于定语从句或表选择，不能这样引导 tell you 后的宾语从句。干扰点：把 which 当宾语从句引导词。</li><li>D ❌ whether 表「是否」，与陈述语气不符。干扰点：只求能引导从句。</li></ul><p><strong>整句翻译</strong>：我很高兴告诉你，这个学期我们学校发生了很大变化。</p><p><strong>词组</strong>：<code>take place</code> 发生；<code>this term</code> 这个学期</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · 节约与菜园 · 第1段（空2，无提示词））：I’m very glad to tell you ____ great changes have taken place in our school this term.（that）</p></details><p><strong>【练习十四 · 提示词 ask】First of all, we’re ____ to “clear our plates” when having our meals and say no to wasting.</strong></p><ul><li>A. asking</li><li>B. to ask</li><li>C. asked</li><li>D. ask</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（asked）</strong> —— 笔记补充解析（原题为有提示词填空）：学生「被要求」，与 are 构成被动语态。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ asking 不能进入 are ____ to 的结构。干扰点：只求形式相近。</li><li>B ❌ to ask 会构成 are to ask（将要去问），与「被要求」的被动义不符。干扰点：把 to do 当万能形式。</li><li>C ✅ we are asked to do sth. 是被动语态，表「我们被要求做某事」，与句中 we 是动作承受者一致。</li><li>D ❌ ask 原形不能作 are 后的成分。干扰点：照抄提示词。</li></ul><p><strong>整句翻译</strong>：首先，我们被要求吃饭时「光盘」，向浪费说不。</p><p><strong>词组</strong>：<code>clear our plates</code> 光盘（把盘子吃干净）；<code>say no to</code> 对……说不</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · 节约与菜园 · 第1段（空3，提示词 ask））：First of all, we’re ____ to “clear our plates” when having our meals and say no to wasting.（asked）</p></details><p><strong>【练习十四 · 提示词 use】Some of us ____ to order more than what we could eat.</strong></p><ul><li>A. used</li><li>B. use</li><li>C. using</li><li>D. are used</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（used）</strong> —— 笔记补充解析（原题为有提示词填空）：固定结构 used to do sth.。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ used to do sth. 表「过去常常做某事」，与后文现在已改变的做法形成对照。</li><li>B ❌ use 是原形，不能构成 used to 的过去习惯含义。干扰点：照抄提示词。</li><li>C ❌ using 是非谓语，不能作谓语。干扰点：把 -ing 填入谓语位置。</li><li>D ❌ are used 是被动语态，与「过去常常」的语义不符。干扰点：把 be used to do 与 used to do 混淆。</li></ul><p><strong>整句翻译</strong>：我们中有些人过去常常点得比吃得下的还多。</p><p><strong>词组</strong>：<code>used to do sth.</code> 过去常常做某事；<code>more than</code> 比……更多</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · 节约与菜园 · 第1段（空4，提示词 use））：Some of us ____ to order more than what we could eat.（used）</p></details><p><strong>【练习十四 · 提示词 waste】We should also stop ____ in some other ways.</strong></p><ul><li>A. wasting</li><li>B. to waste</li><li>C. wasted</li><li>D. waste</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（wasting）</strong> —— 笔记补充解析（原题为有提示词填空）：stop doing sth. 表示停止浪费。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ stop wasting 表「停止浪费」，stop doing sth. 是固定结构（停止正在做的事）。</li><li>B ❌ stop to waste 表「停下来去浪费」，与句意相反。干扰点：忽略 stop doing 与 stop to do 的区别。</li><li>C ❌ wasted 是过去分词，不能作 stop 的宾语。干扰点：只求形式相近。</li><li>D ❌ waste 原形不能进入 stop 后的宾语位置。干扰点：照抄提示词。</li></ul><p><strong>整句翻译</strong>：我们还应该以其它方式停止浪费。</p><p><strong>词组</strong>：<code>stop doing sth.</code> 停止做某事；<code>in some other ways</code> 以其它方式</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · 节约与菜园 · 第1段（空5，提示词 waste））：We should also stop ____ in some other ways.（wasting）</p></details><p><strong>【练习十四 · 无提示词】For example, we should turn off the lights ____ we leave the classroom.</strong></p><ul><li>A. where</li><li>B. until</li><li>C. unless</li><li>D. when</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（when）</strong> —— 笔记补充解析（原题为无提示词填空）：when 引导时间状语从句，表示离开教室时关灯。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ where 表地点，与两个动作的时间关系不符。干扰点：把 where 当万能关系词。</li><li>B ❌ until 表「直到」，会读成「直到离开教室才关灯」，与节能的做法相反。干扰点：把 until 当时间连词通用形式。</li><li>C ❌ unless 表「除非」，与「离开时关灯」的习惯做法不符。干扰点：把否定条件与时间混淆。</li><li>D ✅ when 引导时间状语从句，表「当我们离开教室时关灯」，与节能建议一致。</li></ul><p><strong>整句翻译</strong>：例如，我们离开教室时应该关灯。</p><p><strong>词组</strong>：<code>turn off</code> 关掉；<code>leave the classroom</code> 离开教室</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · 节约与菜园 · 第1段（空6，无提示词））：For example, we should turn off the lights ____ we leave the classroom.（when）</p></details><p><strong>【练习十四 · 无提示词】And our school has opened up some fields for us to learn how ____ grow vegetables.</strong></p><ul><li>A. grow</li><li>B. to</li><li>C. growing</li><li>D. grew</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（to）</strong> —— 笔记补充解析（原题为无提示词填空）：how to grow vegetables 是「疑问词 + 不定式」。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ grow 会造成 how grow 缺 to 的结构错误。干扰点：只求语义通顺。</li><li>B ✅ learn how to grow vegetables 中 how to do sth. 是「疑问词 + 不定式」结构，故填 to。</li><li>C ❌ growing 会造成 how growing 的结构错误。干扰点：把 -ing 当疑问词后的形式。</li><li>D ❌ grew 是过去式，不能进入 how ____ do 的结构。干扰点：只求与 grow 形式相近。</li></ul><p><strong>整句翻译</strong>：我们学校还开辟了一些田地，让我们学习如何种菜。</p><p><strong>词组</strong>：<code>open up some fields</code> 开辟田地；<code>learn how to do sth.</code> 学习如何做某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · 节约与菜园 · 第2段（空7，无提示词））：And our school has opened up some fields for us to learn how ____ grow vegetables.（to）</p></details><p><strong>【练习十四 · 提示词 tomato】Each class is given a small garden and our class has decided to grow some ____ and beans in our free time.</strong></p><ul><li>A. tomato</li><li>B. tomatos</li><li>C. tomato’s</li><li>D. tomatoes</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（tomatoes）</strong> —— 笔记补充解析（原题为有提示词填空）：some 后接可数名词复数；tomato 加 -es。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ tomato 是单数，与 some 后接复数的要求不符。干扰点：照抄提示词。</li><li>B ❌ tomatos 拼写错误，tomato 的复数加 -es。干扰点：误按一般名词加 -s。</li><li>C ❌ tomato’s 是所有格，不表复数。干扰点：把所有格当复数。</li><li>D ✅ some 后接可数名词复数，tomato 以 -o 结尾且为「有生命」类，复数加 -es：tomatoes。</li></ul><p><strong>整句翻译</strong>：每个班都被分到一小块园地，我们班决定在空闲时间种一些西红柿和豆子。</p><p><strong>词组</strong>：<code>be given</code> 被给予；<code>in one’s free time</code> 在空闲时间</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · 节约与菜园 · 第2段（空8，提示词 tomato））：Each class is given a small garden and our class has decided to grow some ____ and beans in our free time.（tomatoes）</p></details><p><strong>【练习十四 · 提示词 we】Maybe I’ll be able to post you some beans we’ve grown by ____ next time!</strong></p><ul><li>A. us</li><li>B. ours</li><li>C. ourselves</li><li>D. we</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（ourselves）</strong> —— 笔记补充解析（原题为有提示词填空）：固定搭配 by oneself，主语为 we。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ us 是宾格，不能与 by 连用表「由我们自己（做）」。干扰点：忽略 by + 反身代词的结构。</li><li>B ❌ ours 是名词性物主代词，by ours 不成语义。干扰点：把物主代词当反身代词。</li><li>C ✅ by ourselves 表「由我们自己（亲手）」，与 we’ve grown 的主语一致。</li><li>D ❌ we 是主格，不能作 by 的宾语。干扰点：忽略介词后需宾格。</li></ul><p><strong>整句翻译</strong>：也许下次我能寄给你们一些我们自己种的豆子！</p><p><strong>词组</strong>：<code>by ourselves</code> 我们自己（亲手）；<code>post sb. sth.</code> 给某人寄某物</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · 节约与菜园 · 第2段（空9，提示词 we））：Maybe I’ll be able to post you some beans we’ve grown by ____ next time!（ourselves）</p></details><p><strong>【练习十四 · 提示词 much】What’s more, we have only two classes in the afternoon so we have ____ time for after-school activities than before.</strong></p><ul><li>A. much</li><li>B. most</li><li>C. more</li><li>D. very much</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（more）</strong> —— 笔记补充解析（原题为有提示词填空）：than before 提示比较级。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ much 是原级，不能与 than before 构成比较。干扰点：忽略比较结构。</li><li>B ❌ most 是最高级，不能与 than 连用。干扰点：把最高级当比较级。</li><li>C ✅ 句末有 than before，需要比较级：more time for after-school activities 表「更多时间参加课外活动」。</li><li>D ❌ very much 不能用于比较结构。干扰点：把 very much 当 more 的替代。</li></ul><p><strong>整句翻译</strong>：而且，我们下午只有两节课，所以比过去有更多时间参加课外活动。</p><p><strong>词组</strong>：<code>What’s more</code> 而且；<code>after-school activities</code> 课外活动；<code>than before</code> 比以前</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十四 · 节约与菜园 · 第2段（空10，提示词 much））：What’s more, we have only two classes in the afternoon so we have ____ time for after-school activities than before.（more）</p></details><h3 id="练习十五-·-旅途中的思乡-题海-p13" tabindex="-1"><a class="header-anchor" href="#练习十五-·-旅途中的思乡-题海-p13"><span>练习十五 · 旅途中的思乡（题海 P13）</span></a></h3><p>I was in <strong>1. ______</strong> most beautiful city in the world, yet I only wanted home.</p><p>It was an amazing week for my husband and me — the trip of a lifetime. Months ago, when my husband told me that he <strong>2. ______</strong>（will）have a meeting in London, I expressed my wish to go to Europe together with him. Then we asked his mother to look after our two <strong>3. ______</strong>（child）and started off.</p><p>During the week&#39;s time, we visited London and Paris — as much as we <strong>4. ______</strong>（can）: Big Ben, the Louvre and so on. All these were beautiful places we expected to see before. We really enjoyed ourselves.</p><p>On our last night in Paris, after we enjoyed the night view of the Eiffel Tower, my husband called home. His mother answered the phone. In a second, my husband&#39;s face fell and he looked so <strong>5. ______</strong>（worry）. I could feel something bad happened.</p><p>“What&#39;s wrong?” I asked.</p><p>He didn&#39;t answer and continued to listen. A few minutes later, he said sadly to me that Tony, our seven-year-old son, <strong>6. ______</strong>（have）fallen off his bike and broken his leg. He must be sent to hospital at once.</p><p>At that moment, Paris <strong>7. ______</strong>（sudden）lost its charm.</p><p>“I don&#39;t want to be here! I shouldn&#39;t be here! I should be home with my kids!”</p><p>We hurried back to our hotel and then to the airport...</p><p>Finally, we got home. We rushed into our children&#39;s bedroom. <strong>8. ______</strong>（see）our two children, I suddenly realized the <strong>9. ______</strong>（true）: there is no <strong>10. ______</strong>（sweet）sight in the world than your children&#39;s faces that greet you at home.</p><p><strong>【练习十五 · 无提示词】I was in ____ most beautiful city in the world, yet I only wanted home.</strong></p><ul><li>A. a</li><li>B. the</li><li>C. an</li><li>D. one</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（the）</strong> —— 笔记补充解析（原题为无提示词填空）：最高级 most beautiful 前用定冠词。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ a 与最高级不搭配（最高级前通常用 the）。干扰点：忽略最高级前冠词的要求。</li><li>B ✅ the most beautiful city in the world 是「最高级 + 范围」的固定结构，最高级前用 the。</li><li>C ❌ an 同样不合最高级的要求，且 most 以辅音音素开头。干扰点：只求冠词能填。</li><li>D ❌ one 不能替代冠词与最高级连用。干扰点：把 one 当 a/an 的替换。</li></ul><p><strong>整句翻译</strong>：我身处世界上最美丽的城市，可我只想回家。</p><p><strong>词组</strong>：<code>the most beautiful</code> 最美丽的；<code>the trip of a lifetime</code> 一生一次的旅行</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:1，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 旅途中的思乡 · 第1段（空1，无提示词））：I was in ____ most beautiful city in the world, yet I only wanted home.（the）</p></details><p><strong>【练习十五 · 提示词 will】Months ago, when my husband told me that he ____ have a meeting in London, I expressed my wish to go to Europe together with him.</strong></p><ul><li>A. will</li><li>B. would</li><li>C. shall</li><li>D. can</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（would）</strong> —— 笔记补充解析（原题为有提示词填空）：主句为过去时，过去将来时用 would。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ will 是一般将来时，与 told 的过去时不符。干扰点：只看「将来」义。</li><li>B ✅ 主句 told 是过去时，宾语从句表「过去将来」用 would have a meeting。</li><li>C ❌ shall 多用于第一人称的将来，与第三人称 he 及过去时语境不合。干扰点：把 shall 当 will 的同义替换。</li><li>D ❌ can 表能力，与「将要开会」的将来义不符。干扰点：只求情态动词能填。</li></ul><p><strong>整句翻译</strong>：几个月前，丈夫告诉我他将在伦敦开会时，我说出了想和他一起去欧洲的愿望。</p><p><strong>词组</strong>：<code>express one’s wish</code> 表达愿望；<code>start off</code> 出发</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:2，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 旅途中的思乡 · 第2段（空2，提示词 will））：Months ago, when my husband told me that he ____ have a meeting in London, I expressed my wish to go to Europe together with him.（would）</p></details><p><strong>【练习十五 · 提示词 child】Then we asked his mother to look after our two ____ and started off.</strong></p><ul><li>A. child</li><li>B. childs</li><li>C. child’s</li><li>D. children</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（children）</strong> —— 笔记补充解析（原题为有提示词填空）：two 后接可数名词复数，child 的复数是不规则形式。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ child 是单数，与 two 后接复数的要求不符。干扰点：照抄提示词。</li><li>B ❌ childs 拼写错误，child 的复数是不规则形式 children。干扰点：按一般规则加 -s。</li><li>C ❌ child’s 是所有格，不表复数。干扰点：把所有格当复数。</li><li>D ✅ two 后接复数名词，child 的复数是不规则形式 children。</li></ul><p><strong>整句翻译</strong>：然后我们请他的母亲照看两个孩子，便出发了。</p><p><strong>词组</strong>：<code>look after</code> 照看；<code>start off</code> 出发</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:3，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 旅途中的思乡 · 第2段（空3，提示词 child））：Then we asked his mother to look after our two ____ and started off.（children）</p></details><p><strong>【练习十五 · 提示词 can】During the week’s time, we visited London and Paris — as much as we ____: Big Ben, the Louvre and so on.</strong></p><ul><li>A. can</li><li>B. may</li><li>C. must</li><li>D. could</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（could）</strong> —— 笔记补充解析（原题为有提示词填空）：叙述过去一周内尽可能多地游览，用 can 的过去式。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ can 是现在时，与 visited 的过去时不符。干扰点：忽略时态一致。</li><li>B ❌ may 表许可或可能，与「尽可能」的语义不符。干扰点：只看情态动词类别。</li><li>C ❌ must 表必须，不合「尽可能多」的表达。干扰点：把 must 与 could 混用。</li><li>D ✅ as much as we could 表「尽可能多地」，与全篇过去时一致。</li></ul><p><strong>整句翻译</strong>：那一周里，我们尽可能多地游览了伦敦和巴黎。</p><p><strong>词组</strong>：<code>as much as one could</code> 尽可能多地；<code>enjoy oneself</code> 玩得开心</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:4，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 旅途中的思乡 · 第3段（空4，提示词 can））：During the week’s time, we visited London and Paris — as much as we ____: Big Ben, the Louvre and so on.（could）</p></details><p><strong>【练习十五 · 提示词 worry】His mother answered the phone. In a second, my husband’s face fell and he looked so ____.</strong></p><ul><li>A. worrying</li><li>B. worried</li><li>C. worriedly</li><li>D. worry</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（worried）</strong> —— 笔记补充解析（原题为有提示词填空）：looked 为系动词，形容人的担忧感受。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ worrying 表「令人担忧的」，修饰事物，不能描述人的神情。干扰点：-ing/-ed 形容词混用。</li><li>B ✅ worried 表「感到担忧的」，描述人的神情，looked so worried 表「看起来很担忧」。</li><li>C ❌ worriedly 是副词，不能作 looked 的表语。干扰点：忽略词性。</li><li>D ❌ worry 是动词或名词，不能作表语形容词。干扰点：照抄提示词。</li></ul><p><strong>整句翻译</strong>：他母亲接了电话。一瞬间，丈夫的脸沉了下来，看起来非常担忧。</p><p><strong>词组</strong>：<code>one’s face fell</code> （某人）脸色沉了下来；<code>in a second</code> 一瞬间</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:5，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 旅途中的思乡 · 第4段（空5，提示词 worry））：In a second, my husband’s face fell and he looked so ____.（worried）</p></details><p><strong>【练习十五 · 提示词 have】A few minutes later, he said sadly to me that Tony, our seven-year-old son, ____ fallen off his bike and broken his leg.</strong></p><ul><li>A. has</li><li>B. have</li><li>C. had</li><li>D. was</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（had）</strong> —— 笔记补充解析（原题为有提示词填空）：与 fallen 构成过去完成时；摔倒发生在「他说」之前。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ has 是现在完成时，与主句 said 的过去时不符。干扰点：只求与 have 形式相近。</li><li>B ❌ have 是原形，不能用于此处。干扰点：照抄提示词。</li><li>C ✅ 主句 said 是过去时，从句动作发生在此之前，用过去完成时 had fallen。</li><li>D ❌ was 不能与 fallen 构成时态。干扰点：只求形式相近。</li></ul><p><strong>整句翻译</strong>：几分钟后，他难过地告诉我，我们七岁的儿子 Tony 从自行车上摔下来摔断了腿。</p><p><strong>词组</strong>：<code>fall off</code> 从……摔下；<code>break one’s leg</code> 摔断腿</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:6，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 旅途中的思乡 · 第5段（空6，提示词 have））：A few minutes later, he said sadly to me that Tony, our seven-year-old son, ____ fallen off his bike and broken his leg.（had）</p></details><p><strong>【练习十五 · 提示词 sudden】At that moment, Paris ____ lost its charm.</strong></p><ul><li>A. suddenly</li><li>B. sudden</li><li>C. suddenness</li><li>D. more sudden</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（suddenly）</strong> —— 笔记补充解析（原题为有提示词填空）：副词修饰 lost。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ suddenly 是副词，修饰动词 lost，表「突然失去」。</li><li>B ❌ sudden 是形容词，不能修饰动词。干扰点：照抄提示词。</li><li>C ❌ suddenness 是名词，不能作状语。干扰点：把名词当副词。</li><li>D ❌ more sudden 是比较级形容词，同样不能修饰动词。干扰点：把 more 当万能修饰。</li></ul><p><strong>整句翻译</strong>：那一刻，巴黎突然失去了它的魅力。</p><p><strong>词组</strong>：<code>lose its charm</code> 失去魅力；<code>at that moment</code> 在那一刻</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:7，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 旅途中的思乡 · 第6段（空7，提示词 sudden））：At that moment, Paris ____ lost its charm.（suddenly）</p></details><p><strong>【练习十五 · 提示词 see】____ our two children, I suddenly realized the truth: there is no sweeter sight in the world than your children’s faces that greet you at home.</strong></p><ul><li>A. Seen</li><li>B. To see</li><li>C. Seeing</li><li>D. Saw</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（Seeing）</strong> —— 笔记补充解析（原题为有提示词填空）：现在分词作时间状语，逻辑主语是 I，与 see 为主动关系。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ Seen 是被动形式，而 I 与 see 是主动关系。干扰点：忽略主动/被动。</li><li>B ❌ To see 多表目的，与「看到时（同时发生）」的时间关系不符。干扰点：把不定式当状语通用形式。</li><li>C ✅ Seeing our two children, I suddenly realized…：现在分词作时间状语，主语 I 与 see 是主动关系。</li><li>D ❌ Saw 是谓语形式，句中已有谓语 realized。干扰点：把谓语填进状语位置。</li></ul><p><strong>整句翻译</strong>：看到我们的两个孩子时，我突然明白了真相。</p><p><strong>词组</strong>：<code>greet sb.</code> 迎接某人；<code>no…than…</code> 没有比……更……</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:8，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 旅途中的思乡 · 末段（空8，提示词 see））：____ our two children, I suddenly realized the truth…（Seeing）</p></details><p><strong>【练习十五 · 提示词 true】Seeing our two children, I suddenly realized the ____: there is no sweeter sight in the world than your children’s faces that greet you at home.</strong></p><ul><li>A. true</li><li>B. truly</li><li>C. truth</li><li>D. truer</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（truth）</strong> —— 笔记补充解析（原题为有提示词填空）：定冠词 the 后用名词。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ true 是形容词，不能作 realized 的宾语。干扰点：照抄提示词。</li><li>B ❌ truly 是副词，不能作宾语。干扰点：把副词当名词用。</li><li>C ✅ truth 是名词，realized the truth 表「明白了真相」，与后文冒号引出的感悟对应。</li><li>D ❌ truer 是比较级形容词，不能作宾语。干扰点：只求形式上沾边。</li></ul><p><strong>整句翻译</strong>：……我突然明白了真相。</p><p><strong>词组</strong>：<code>realize the truth</code> 明白真相；<code>in the world</code> 世界上（用于最高级范围）</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:9，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 旅途中的思乡 · 末段（空9，提示词 true））：Seeing our two children, I suddenly realized the ____: there is no sweeter sight in the world than your children’s faces that greet you at home.（truth）</p></details><p><strong>【练习十五 · 提示词 sweet】Seeing our two children, I suddenly realized the truth: there is no ____ sight in the world than your children’s faces that greet you at home.</strong></p><ul><li>A. sweeter</li><li>B. sweet</li><li>C. sweetest</li><li>D. sweetly</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（sweeter）</strong> —— 笔记补充解析（原题为有提示词填空）：than 提示比较级；「否定词 + 比较级」表达最高级含义。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 句中有 no…than… 的比较结构，需要用比较级 sweeter。</li><li>B ❌ sweet 是原级，不能与 than 构成比较。干扰点：忽略 than 的存在。</li><li>C ❌ sweetest 是最高级，与 than 连用不合语法。干扰点：把最高级当比较级。</li><li>D ❌ sweetly 是副词，不能修饰名词 sight。干扰点：忽略词性。</li></ul><p><strong>整句翻译</strong>：……世界上没有比回家时孩子迎接你的笑脸更美的景象了。</p><p><strong>词组</strong>：<code>no…than…</code> 没有比……更……；<code>greet you at home</code> 在家迎接你</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:0，比较两题的判断依据</p><p><strong>原文定位</strong>（练习十五 · 旅途中的思乡 · 末段（空10，提示词 sweet））：…there is no ____ sight in the world than your children’s faces that greet you at home.（sweeter）</p></details><h2 id="口诀卡" tabindex="-1"><a class="header-anchor" href="#口诀卡"><span>口诀卡</span></a></h2><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>本课全部口诀 <strong>有提示，看词性；无提示，看成分。</strong></p><p><strong>一空一词先定岗：主宾名代，修饰副，系后形，句间连。</strong></p><p><strong>动词三问：是不是谓语？什么时态语态？主谓是否一致？</strong></p><p><strong>已有谓语无连词，第二动词变非谓。</strong></p></div>`,696),a(`p`,null,[l[11]||=e(`关联复习：`,-1),o(m,{href:`/courses/zsb-english/l/9/`},{default:i(()=>[...l[5]||=[e(`时态和语态`,-1)]]),_:1}),l[12]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/l/11/`},{default:i(()=>[...l[6]||=[e(`非谓语动词`,-1)]]),_:1}),l[13]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/l/10/`},{default:i(()=>[...l[7]||=[e(`主谓一致`,-1)]]),_:1}),l[14]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/l/12/`},{default:i(()=>[...l[8]||=[e(`定语从句`,-1)]]),_:1}),l[15]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/l/13/`},{default:i(()=>[...l[9]||=[e(`名词性从句`,-1)]]),_:1}),l[16]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/l/14/`},{default:i(()=>[...l[10]||=[e(`状语从句`,-1)]]),_:1})]),l[23]||=a(`p`,null,`延伸阅读：语法填空 · 完整笔记 · 原始课件 PDF`,-1),l[24]||=a(`p`,null,`有不懂的随时问你的 AI 老师——回到 ZCode 对话里直接提问即可。`,-1),l[25]||=a(`hr`,null,null,-1),a(`p`,null,[o(m,{href:`/courses/zsb-english/l/22/`},{default:i(()=>[...l[17]||=[e(`← 第 22 课`,-1)]]),_:1}),l[20]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/`},{default:i(()=>[...l[18]||=[e(`课程目录`,-1)]]),_:1}),l[21]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/l/24/`},{default:i(()=>[...l[19]||=[e(`第 24 课 →`,-1)]]),_:1})])])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};